        \item If $v_p(\alpha) = t$, then exists a partial valuation $w_p$ such that $w_p(\alpha) \in \{ \fnec, \fcont \}$ and, for every $\beta$, if $v_p(\beta) = \tnec$ then $w_p(\beta) = \tnec$.
    \end{enumerate}

\end{definition}
\fi

