\begin{theorem}[Soundness of $\star$]\label{theo:LvalSound}
    If $\Gamma \vdash_{\star} A$, then $\Gamma \Vdash_{\mathcal{M}_{\star}}^{\mathcal{L}} A$.
\end{theorem}
\begin{proof}
    Proved in [ref].
\end{proof}

\begin{theorem}[Completeness of $\star$]\label{theo:LvalComplete}
    If $\Gamma \Vdash_{\mathcal{M}_{\star}}^{\mathcal{L}} A$, then $\Gamma \vdash_{\star} A$.
\end{theorem}
\begin{proof}
    Proved in [ref].
\end{proof}

