\begin{definition}[Partial valuation]
    Let $\star \in \{ \mKT, \mKTB, \mKTfor, \mKTBfourfive \}$. The partial valuation in $\mathcal{M}_{\star}$ is a function $v_p : \Lambda \to \mathcal{V}$ where $\Lambda \subseteq For(\star)$ is a domain closed under subformulas and 

    \[
        v_p(\# (\alpha_0, \ldots, \alpha_n)) \in \{ undef \} \cup \#^{\star}(v_p(\alpha_0), \ldots, v_p(\alpha_n))
    \]

    with $\# \in \{ \neg, \to, \land, \lor, \Box, \Diamond \}$.

\end{definition}

\begin{remark}
    Note that every valuation function is a partial valuation function where $\Lambda = For(\star)$.
\end{remark}

Each filter turns into a definition of partial level valuation.

\subsection{$\mKT$}

\begin{definition}[Partial level valuation in $\mKT$]\label{def:PLVT}
    Let $v_p : \Lambda \to \mathcal{V}$ be a partial valuation and $\alpha \in \Lambda$. The function $v_p$ is a partial level valuation in $\mKT$ iff

    \begin{enumerate}
        \item If $v_p(\alpha) = \fcont$, then there is a level valuation $w$ in $\mathcal{L}(\mathcal{M}_{\mKT})$ such that $\tilde w^{\star}(\alpha) \in \{ \tnec, \tcont \}$ and, $\forall \beta \in \Lambda$, if $v_p(\beta) = \tnec$ then $w(\beta) \in \{ \tnec, \tcont \}$.
        \item If $v_p(\alpha) = \tcont$, then there is a level valuation $w$ in $\mathcal{L}(\mathcal{M}_{\mKT})$ such that $\tilde w^{\star}(\alpha) \in \{ \fnec, \fcont \}$ and, $\forall \beta \in \Lambda$, if $v_p(\beta) = \tnec$ then $w(\beta) \in \{ \tnec, \tcont \}$.
    \end{enumerate}

\end{definition}

\begin{lemma}[Co-analyticity for $\mathcal{L}(\mathcal{M}_{\mKT})$] For every level valuation $v \in \mathcal{L}(\mathcal{M}_{\mKT})$ and every set closed under subformulas $\Lambda$, the function $v_p = v \mid_{\Lambda}$ is a partial level valuation in $\mKT$.
\end{lemma}

\begin{proof}
Let $v \in \mathcal{L}(\mathcal{M}_{\mKT})$ be a level valuation, $\Lambda$ a set closed under subformulas and $v_p = v \mid_{\Lambda}$. Let $\Gamma = \{ \beta \in For(\star) \mid v(\beta) = \tnec \}$. Suppose that $v_p$ is not a partial level valuation. By Definition~\ref{def:PLVT}, there is a formula $\alpha$ such that $v_p (\alpha) = \fcont$ or $v_p (\alpha) = \tcont$ and, for each case,

\begin{description}
    \item[$v_p (\alpha) = \fcont$] In this case, either there is no valuation $w$ such that $\tilde w^{\star}(\alpha) \in \{ \tnec, \tcont \}$ or, for every level valuation $w$ such that $\tilde w^{\star}(\alpha) \in \{ \tnec, \tcont \}$, there is some formula $\beta \in \Gamma$ such that $w(\beta) \in \{ \fnec, \fcont \}$.

    Observe that $v(\neg \alpha) = \tcont$ and $\Gamma \Vdash^{\mathcal{L}}_{{\mathcal{M}_{\mKT}}} \neg \alpha$, in any case, even when $\Gamma = \emptyset$. By Theorem~\ref{theo:LvalComplete}, $\Gamma \vdash_{\mKT} \neg \alpha$. By the finitariness of $\vdash_{\mKT}$, there is a finite subset of $\{ \beta_0, \ldots, \beta_n \} \subseteq \Gamma$ such that $\{ \beta_0, \ldots, \beta_n \} \vdash_{\mKT} \neg \alpha$. 

    Now, by applications of Deduction Theorem and RN, we get 

    \[ 
        \vdash_{\mKT} \Box (\beta_0 \to (\beta_1 \to (\ldots \to (\beta_n \to \neg \alpha))))
    \]

    However, in $\mathcal{M}_{\mKT}$, using the assumptions, we get
    \begin{align*}
        v(\beta_0 \to (\beta_1 \to (\ldots \to (\beta_n \to \neg \alpha)))) = \tcont \\
        \therefore v(\Box (\beta_0 \to (\beta_1 \to (\ldots \to (\beta_n \to \neg \alpha))))) \in \{ \fnec, \fcont \}
    \end{align*}
    which is a contradiction.

    \item[$v_p (\alpha) = \tcont$] In this case, either there is no valuation $w$ such that $\tilde w^{\star}(\alpha) \in \{ \fnec, \fcont \}$ or, for every level valuation $w$ such that $\tilde w^{\star}(\alpha) \in \{ \fnec, \fcont \}$, there is some formula $\beta \in \Gamma$ such that $w(\beta) \in \{ \fnec, \fcont \}$. 

    Observe that $\Gamma \Vdash^{\mathcal{L}}_{{\mathcal{M}_{\mKT}}} \alpha$, in any case, even when $\Gamma = \emptyset$. By Theorem~\ref{theo:LvalComplete}, $\Gamma \vdash_{\mKT} \alpha$. By the finitariness of $\vdash_{\mKT}$, there is a finite subset of $\{ \beta_0, \ldots, \beta_n \} \subseteq \Gamma$ such that $\{ \beta_0, \ldots, \beta_n \} \vdash_{\mKT} \alpha$. 

    Now, by applications of MP and RN, we get 

    \[ 
        \vdash_{\mKT} \Box (\beta_0 \to (\beta_1 \to (\ldots \to (\beta_n \to \alpha))))
    \]

    However, in $\mathcal{M}_{\mKT}$, using the assumptions, we get
    \begin{align*}
        v(\beta_0 \to (\beta_1 \to (\ldots \to (\beta_n \to \alpha)))) = \tcont \\
        \therefore v(\Box (\beta_0 \to (\beta_1 \to (\ldots \to (\beta_n \to \alpha))))) \in \{ \fnec, \fcont \}
    \end{align*}
    which is a contradiction.



\end{description}

\end{proof}

\begin{lemma}[Analyticity for $\mathcal{L}(\mathcal{M}_{\mKT})$] Every partial valuation $v_p : \Lambda \to \mathcal{V}$ in $\mKT$ can be extended to a level valuation in $\mathcal{L}(\mathcal{M}_{\mKT})$.
\end{lemma}

\subsection{$\mKTB$}


\begin{definition}[Partial level valuation in $\mKTB$]\label{def:PLVB}
    Let $v_p$ be a partial valuation and $\alpha$ some formula in the domain of $v_p$. The function $v_p$ is a partial level valuation iff

    \begin{enumerate}
        \item If $v_p(\alpha) = \fcont$, then there is a level valuation $w$ in $\mathcal{L}(\mathcal{M}_{\mKTB})$ such that $\tilde w^{\star}(\alpha) \in \{ \tnec, \tcont \}$ and, $\forall \beta \in \Lambda$, if $v_p(\beta) = \tnec$ then $w(\beta) \in \{ \tnec, \tcont \}$ and if $w(\beta) = \tnec$ then $v_p(\beta) \in \{ \tnec, \tcont \}$.
        \item If $v_p(\alpha) = \tcont$, then there is a level valuation $w$ in $\mathcal{L}(\mathcal{M}_{\mKTB})$ such that $\tilde w^{\star}(\alpha) \in \{ \fnec, \fcont \}$ and, $\forall \beta \in \Lambda$, if $v_p(\beta) = \tnec$ then $w(\beta) \in \{ \tnec, \tcont \}$ and if $w(\beta) = \tnec$ then $v_p(\beta) \in \{ \tnec, \tcont \}$.
    \end{enumerate}

\end{definition}

\begin{lemma}[Co-analyticity for $\mathcal{L}(\mathcal{M}_{\mKTB})$] For every level valuation $v \in \mathcal{L}(\mathcal{M}_{\mKTB})$ and every set closed under subformulas $\Lambda$, the function $v_p = v \mid_{\Lambda}$ is a partial level valuation in $\mKTB$.
\end{lemma}

\begin{proof}
Let $v \in \mathcal{L}(\mathcal{M}_{\mKTB})$ be a level valuation, $\Lambda$ a set closed under subformulas and $v_p = v \mid_{\Lambda}$. Let $\Gamma_1 = \{ \beta \in For(\star) \mid v(\beta) = \tnec \}$ and $\Gamma_2 = \{  \beta \in For(\star) \mid v(\beta) \in \{ \fnec, \fcont \} \}$. Suppose that $v_p$ is not a partial level valuation. By Definition~\ref{def:PLVB}, there is a formula $\alpha$ such that $v_p (\alpha) = \fcont$ or $v_p (\alpha) = \tcont$ and, for each case,

\begin{description}
    \item[$v_p (\alpha) = \fcont$] In this case, either there is no valuation $w$ such that $\tilde w^{\star}(\alpha) \in \{ \tnec, \tcont \}$ or, for every level valuation $w$ such that $\tilde w^{\star}(\alpha) \in \{ \tnec, \tcont \}$, either there is some formula $\beta \in \Gamma_1$ such that $w(\beta) \in \{ \fnec, \fcont \}$ (\textbf{Case 1}) or there is some formula $\beta \in \Gamma_2$ such that $w(\beta) = \tnec$ (\textbf{Case 2}).

    \begin{description}
        \item[Case 1] Similar to $\mKT$ when $v_p (\alpha) = \fcont$.
        \item[Case 2] In this case, we observe that $w(\neg \beta) = \fnec$ and $v(\neg \alpha) = \tcont$, which is sufficient to state that $\{ \neg \beta \mid \beta \in \Gamma_2 \} \Vdash^{\mathcal{L}}_{{\mathcal{M}_{\mKTB}}} \neg \alpha$. By Theorem~\ref{theo:LvalComplete}, we get $\{ \neg \beta \mid \beta \in \Gamma_2 \} \vdash_{\mKTB} \neg \alpha$ and, by finitariness, there is a finite subset $\{ \neg \beta_0, \ldots, \neg \beta_n \} \subseteq \{ \neg \beta \mid \beta \in \Gamma_2 \}$ such that $\{ \neg \beta_0, \ldots, \neg \beta_n \} \vdash_{\mKTB} \neg \alpha$. By MP and RN, we get 

        \[ 
            \vdash_{\mKTB} \Box (\neg \beta_0 \to (\neg \beta_1 \to (\ldots \to (\neg \beta_n \to \neg \alpha))))
        \]

        However, in $\mathcal{M}_{\mKTB}$, using the assumptions, we get
        \begin{align*}
            v(\neg \beta_0 \to (\neg \beta_1 \to (\ldots \to (\neg \beta_n \to \neg \alpha)))) = \tcont \\
            \therefore v(\Box (\neg \beta_0 \to (\neg \beta_1 \to (\ldots \to (\neg \beta_n \to \neg \alpha))))) \in \{ \fnec, \fcont \}
        \end{align*}
        which is a contradiction.
    \end{description}

    \item[$v_p (\alpha) = \tcont$] In this case, either there is no valuation $w$ such that $\tilde w^{\star}(\alpha) \in \{ \fnec, \fcont \}$ or, for every level valuation $w$ such that $\tilde w^{\star}(\alpha) \in \{ \fnec, \fcont \}$, either there is some formula $\beta \in \Gamma_1$ such that $w(\beta) \in \{ \fnec, \fcont \}$ (\textbf{Case 1}) or there is some formula $\beta \in \Gamma_2$ such that $w(\beta) = \tnec$ (\textbf{Case 2}).
    \begin{description}
        \item[Case 1] Similar to $\mKT$ when $v_p (\alpha) = \tcont$.
        \item[Case 2] In this case, we observe that $w(\neg \beta) = \fnec$, which is sufficient to state that $\{ \neg \beta \mid \beta \in \Gamma_2 \} \Vdash^{\mathcal{L}}_{{\mathcal{M}_{\mKTB}}}\alpha$. By Theorem~\ref{theo:LvalComplete}, we get $\{ \neg \beta \mid \beta \in \Gamma_2 \} \vdash_{\mKTB} \alpha$ and, by finitariness of $\vdash_{\mKTB}$, there is a finite subset $\{ \neg \beta_0, \ldots, \neg \beta_n \} \subseteq \{ \neg \beta \mid \beta \in \Gamma_2 \}$ such that $\{ \neg \beta_0, \ldots, \neg \beta_n \} \vdash_{\mKTB} \alpha$. By MP and RN, we get 

        \[ 
            \vdash_{\mKTB} \Box (\neg \beta_0 \to (\neg \beta_1 \to (\ldots \to (\neg \beta_n \to \alpha))))
        \]

        However, in $\mathcal{M}_{\mKTB}$, using the assumptions, we get
        \begin{align*}
            v(\neg \beta_0 \to (\neg \beta_1 \to (\ldots \to (\neg \beta_n \to \alpha)))) = \tcont \\
            \therefore v(\Box (\neg \beta_0 \to (\neg \beta_1 \to (\ldots \to (\neg \beta_n \to \alpha))))) \in \{ \fnec, \fcont \}
        \end{align*}
        which is a contradiction.


    \end{description}
\end{description}

\end{proof}



\subsection{$\mKTfor$}

\begin{definition}[Partial level valuation in $\mKTfor$]
    Let $v_p$ be a partial valuation and $\alpha$ some formula in the domain of $v_p$. The function $v_p$ is a partial level valuation iff

    \begin{enumerate}
        \item If $v_p(\alpha) = \fcont$, then there is a level valuation $w$ in $\mathcal{L}(\mathcal{M}_{\mKTfor})$ such that $\tilde w^{\star}(\alpha) \in \{ \tnec, \tcont \}$ and, $\forall \beta \in \Lambda$, if $v_p(\beta) = \tnec$ then $w(\beta) = \tnec$.
        \item If $v_p(\alpha) = \tcont$, then there is a level valuation $w$ in $\mathcal{L}(\mathcal{M}_{\mKTfor})$ such that $\tilde w^{\star}(\alpha) \in \{ \fnec, \fcont \}$ and, $\forall \beta \in \Lambda$, if $v_p(\beta) = \tnec$ then $w(\beta) = \tnec$.
    \end{enumerate}

\end{definition}

\begin{lemma}[Co-analyticity for $\mathcal{L}(\mathcal{M}_{\mKTfor})$] For every level valuation $v \in \mathcal{L}(\mathcal{M}_{\mKTfor})$ and every set closed under subformulas $\Lambda$, the function $v_p = v \mid_{\Lambda}$ is a partial level valuation in $\mKTfor$.
\end{lemma}

\begin{proof}
Let $v \in \mathcal{L}(\mathcal{M}_{\mKTfor})$ be a level valuation, $\Lambda$ a set closed under subformulas and $v_p = v \mid_{\Lambda}$. Let $\Gamma = \{ \beta \in For(\star) \mid v(\beta) = \tnec \}$. Suppose that $v_p$ is not a partial level valuation. By Definition~\ref{def:PLVT}, there is a formula $\alpha$ such that $v_p (\alpha) = \fcont$ or $v_p (\alpha) = \tcont$ and, for each case,

\begin{description}
    \item[$v_p(\alpha) = \fcont$] In this case, either there is no valuation $w$ such that $\tilde w^{\star}(\alpha) \in \{ \tnec, \tcont \}$ or, for every level valuation $w$ such that $\tilde w^{\star}(\alpha) \in \{ \tnec, \tcont \}$, there is some formula $\beta \in \Gamma$ such that $w(\beta) \in \{ \fnec, \fcont, \tcont \}$. Therefore, $w(\Box \beta) = \fnec$. 

    Now, observe that $v(\neg \alpha) = \tcont$. Hence, $\{ \Box \beta \mid \beta \in \Gamma \} \Vdash^{\mathcal{L}}_{{\mathcal{M}_{\mKTfor}}} \neg \alpha$. By Theorem~\ref{theo:LvalComplete}, $\{ \Box \beta \mid \beta \in \Gamma \} \vdash_{\mKTfor} \neg \alpha$. By finitariness of $\vdash_{\mKTfor}$, there is a finite subset such that $\{ \Box \beta_0, \ldots, \Box \beta_n \} \vdash_{\mKTfor} \neg \alpha$. By applications of MP and RN, we get 
    \[ 
        \vdash_{\mKTfor} \Box (\Box \beta_0 \to (\Box \beta_1 \to (\ldots \to (\Box \beta_n \to \neg \alpha))))
    \]
    However, in $\mathcal{M}_{\mKTfor}$, using the assumptions, we get
    \begin{align*}
        v(\Box \beta_0 \to (\Box \beta_1 \to (\ldots \to (\Box \beta_n \to \neg \alpha)))) = \tcont \\
        \therefore v(\Box (\Box \beta_0 \to (\Box \beta_1 \to (\ldots \to (\Box \beta_n \to \neg \alpha))))) \in \{ \fnec, \fcont \}
    \end{align*}
    which is a contradiction.
    \item[$v_p(\alpha) = \tcont$] In this case, either there is no valuation $w$ such that $\tilde w^{\star}(\alpha) \in \{ \fnec, \fcont \}$ or, for every level valuation $w$ such that $\tilde w^{\star}(\alpha) \in \{ \fnec, \fcont \}$, there is some formula $\beta \in \Gamma$ such that $w(\beta) \in \{ \fnec, \fcont, \tcont \}$. Therefore, $w(\Box \beta) = \fnec$. 

    Hence, $\{ \Box \beta \mid \beta \in \Gamma \} \Vdash^{\mathcal{L}}_{{\mathcal{M}_{\mKTfor}}} \alpha$. By Theorem~\ref{theo:LvalComplete}, $\{ \Box \beta \mid \beta \in \Gamma \} \vdash_{\mKTfor} \alpha$. By finitariness of $\vdash_{\mKTfor}$, there is a finite subset such that $\{ \Box \beta_0, \ldots, \Box \beta_n \} \vdash_{\mKTfor} \alpha$. By applications of MP and RN, we get
    \[ 
        \vdash_{\mKTfor} \Box (\Box \beta_0 \to (\Box \beta_1 \to (\ldots \to (\Box \beta_n \to \alpha))))
    \]
    However, in $\mathcal{M}_{\mKTfor}$, using the assumptions, we get
    \begin{align*}
        v(\Box \beta_0 \to (\Box \beta_1 \to (\ldots \to (\Box \beta_n \to \alpha)))) = \tcont \\
        \therefore v(\Box (\Box \beta_0 \to (\Box \beta_1 \to (\ldots \to (\Box \beta_n \to \alpha))))) \in \{ \fnec, \fcont \}
    \end{align*}
    which is a contradiction.
\end{description}

\end{proof}

\subsection{$\mKTBfourfive$}

