\begin{abstract}
The recent work [Kurz \textsl{et al.}, Numer.\ Math., 147 (2021)] proposed functional \textsl{a~posteriori} error estimates for boundary element methods (BEMs) together with a related adaptive mesh-refinement strategy. Unlike most \textsl{a~posteriori} BEM error estimators, the proposed functional error estimators cover Galerkin as well as collocation BEM and, more importantly, do not control the error in the integral density on the boundary, but the error of the potential approximation in the domain, which is of greater relevance in practice. The estimates rely on the numerical solution of auxiliary problems on auxiliary strip domains along the boundary, where the strips are affected by the adaptive mesh-refinement and hence vary. For Galerkin BEM, we prove that the proposed adaptive mesh-refinement algorithm yields convergence of the potential error to zero. Due to the structural difference to residual-based estimators, the proof requires new ideas.
\end{abstract}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Introduction}

%!TEX root = fabem_convergence.tex
\noindent
Let $\Omega \subset \R^d$, $d \geq 2$, be a bounded Lipschitz domain with polyhedral boundary $\Gamma \coloneqq \partial\Omega$. We consider the Poisson problem with inhomogeneous Dirichlet boundary data $g$, i.e.,
\begin{align}\label{eq:poisson}
 \Delta u^\exact = 0
 \quad \text{in } \Omega
 \quad \text{subject to} \quad
 u^\exact = g
 \quad \text{on } \Gamma.
\end{align}
For the numerical solution of~\eqref{eq:poisson}, we employ the boundary element method (BEM).
For the ease of presentation in this introduction, we consider an indirect ansatz based on the single-layer potential
\begin{align}\label{eq:slp}
 (\widetilde V\phi^\exact)(x) 
 \coloneqq \int_\Gamma G(x-y) \phi^\exact(y) \, \d{y} 
 = u^\exact(x) 
 \quad \text{for all } x \in \Omega
\end{align}
with unknown density $\phi^\exact$, where 
%
\begin{equation} \label{eq:fundamental}
 G(x) = \begin{cases} - \frac{1}{2\pi} \log|x|  & \text{for } d = 2 \\
                       \frac{1}{(d-2)\abs{\S_{d-1}}} \abs{x}^{2-d} & \text{for } d \geq 3
 \end{cases}
\end{equation}
%
denotes the fundamental solution of the Laplacian. Here, $\abs{\S_{d-1}}$ denotes the surface area of the unit sphere in $\R^d$. Taking the trace of~\eqref{eq:slp} on $\Gamma$, we obtain the weakly-singular boundary integral equation 
\begin{align}\label{eq:bie}
 (V\phi^\exact)(x) = g(x)
 \quad \text{for almost all } x \in \Gamma,
\end{align}
where the integral representation of $(V\phi^\exact)(x)$ coincides with that of $(\widetilde V\phi^\exact)(x)$ (at least for bounded densities) but is now evaluated on $\Gamma$ (instead of the interior of $\Omega$). Supposing that $\diam(\Omega) < 1$ in case of $d = 2$ (which can always be ensured by scaling of $\Omega$), the boundary integral equation~\eqref{eq:bie} admits a unique solution $\phi^\exact \in H^{-1/2}(\Gamma)$; see, e.g., \cite{Mclean2000}. Given a triangulation $\TT_\ell^\Gamma$ of the boundary $\Gamma$, the boundary element method (BEM) approximates $\phi^\exact \approx \phi_\ell \in \PP^p(\TT_\ell^\Gamma)$ by a $\TT_\ell^\Gamma$-piecewise polynomial of degree $p \in \N_0$, where the index $\ell \in \N_0$ indicates the sequential step of a mesh-refining adaptive algorithm. Independently of how $\phi_\ell$ is computed (e.g., Galerkin BEM or collocation BEM with/without inexact iterative solver), this yields an approximation
\begin{align}\label{eq:approximation}
 u_\ell \coloneqq \widetilde V \phi_\ell
 \quad \text{satisfying} \quad
 \Delta u_\ell = 0 
 \quad \text{in } \Omega.
\end{align}
Unlike usual notation, we stress that $u_\ell$ is \emph{not} a discrete function but computed by an integral operator applied to the discrete density $\phi_\ell$, i.e., $u_\ell$ is only data sparse. Since $\nabla u^\exact \approx \nabla u_\ell$ is usually of physical relevance and thus targeted by numerical simulation, the work~\cite{Kurz2020} proposed the functional \textsl{a~posteriori} error estimate 
\begin{align}\label{eq:estimation}
 \begin{split}
 \norm{\ttau_\ell}_{L^2(\omega_\ell)}
 &\le 
% \max_{\substack{\ttau \in L^2(\Omega) \\ \div \ttau = 0}}
% \Big( 2 \, \dual{g - u_\ell|_\Gamma}{\nn \cdot \ttau|_\Gamma}_\Gamma - \norm{\ttau}_{L^2(\Omega)}^2 \Big)^{1/2}
% \\&
%  = 
 \norm{\nabla(u^\exact - u_\ell)}_{L^2(\Omega)}
 %\\&
 %= 
 %\min_{\substack{w \in H^1_(\Omega) \\ w|_\Gamma = g - u_\ell|_\Gamma}} 
 %\norm{\nabla w}_{L^2(\Omega)}
 %\\&
 \le
 \norm{\nabla w_\ell}_{L^2(\omega_\ell)} 
 + \const{C}{osc} \, \osc_\ell,
 \end{split}
\end{align}
where $\ttau_\ell \in \boldsymbol{H}({\rm div}, \omega_\ell)$ and $w_\ell \in H^1(\omega_\ell)$ are computable finite element functions that solve auxiliary problems on an $\ell$-dependent and shrinking strip $\omega_\ell \subseteq \Omega$ and $\osc_\ell$ are appropriate data approximation terms; see Section~\ref{section:mainresult} below.
The proposed adaptive strategy in~\cite{Kurz2020} relies only on the upper bound in~\eqref{eq:estimation} and adapts the strip $\omega_\ell$ in each step of the adaptive loop so that the necessary degrees of freedoms to compute $\ttau_\ell$ and $w_\ell$ appear to be proportional to the number of boundary elements $\#\TT_\ell^\Gamma$. 
Of particular relevance is the fact that the upper and lower bound in \eqref{eq:estimation} hold with \emph{known constant} $1$, where the adaptive algorithm, employed for Galerkin BEM with discrete density $\phi_\ell^\exact = \phi_\ell \in \PP^p(\TT_\ell)$ and induced potential $u_\ell^\exact \coloneqq \widetilde V\phi_\ell^\exact$, empirically led to optimal convergence rates for the error and accurate error estimation $\norm{\nabla(u^\exact - u_\ell^\exact)}_{L^2(\Omega)} \approx \norm{\nabla w_\ell}_{L^2(\omega_\ell)}$ in the experiments of~\cite{Kurz2020}.

The purpose of the present work is to show that the proposed adaptive strategy applied for Galerkin BEM indeed guarantees plain convergence 
\begin{align}\label{eq:convergence}
 \norm{\nabla(u^\exact - u_\ell^\exact)}_{L^2(\Omega)} \to 0
 \quad \text{as } \ell \to \infty, 
\end{align}
where the index $\ell \in \N_0$ indicates the sequential nature of the adaptive algorithm proposed in~\cite{Kurz2020}. 
While similar and even stronger results are available for adaptive Galerkin methods that aim for the optimal adaptive approximation of the integral density $\phi^\exact$ (see, e.g.,~{\cite{Feischl2013,Gantumur2013,Feischl2014a,Gantner2022,Gantner2022a}), we note that the present analysis is impacted (and challenged) by the fact that the strip domain $\omega_\ell \subseteq \Omega$ is changed in each step of the adaptive loop.

We note that our proof of convergence~\eqref{eq:convergence} hinges on the use of Galerkin BEM as this allows to guarantee \textsl{a~priori} convergence of the computed integral densities $\phi_\ell^\exact \to \phi_\infty^\exact$ in the natural Sobolev space $H^{-1/2}(\Gamma)$ as well as on the assumption of additional regularity $g \in H^1(\Gamma)$ (despite only $g \in H^{1/2}(\Gamma)$) for the given Dirichlet data in~\eqref{eq:poisson} that, as in other works~\cite{Bartels2004,afkpp2013,Feischl2014a,Feischl2014}, is exploited to localize the data approximation terms.

\textbf{Outline.} Section~\ref{section:preliminaries} collects all necessary preliminaries and notation on Sobolev spaces on domains and boundaries, meshes and patches, discrete spaces, and Galerkin BEM. In Section~\ref{section:mainresult}, we first recall the main idea of functional-based BEM error estimation from~\cite{Kurz2020} and then formulate the related adaptive algorithm (Algorithm~\ref{algo:adap}). Theorem~\ref{theorem:mainresult} is the main result of this work. It states, first, that the functional upper bound provides also a lower bound for the potential error (as well as the BEM error) and, second, that Algorithm~\ref{algo:adap} guarantees convergence. The proof of Theorem~\ref{theorem:mainresult} is given in Section~\ref{section:proof-mainresult}--\ref{section:extension}. Section~\ref{section:numerics} concludes the work with some numerical experiments that underline the theory and show that, at least empirically, the proposed strategy leads to optimal convergence rates.


\section{Preliminaries and Notation}
\label{section:preliminaries}

\setcounter{subsection}{0}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{General notation}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

Throughout this paper, let $\Omega$ be a bounded domain in $\R^d$, $d \geq 2$, with polyhedral Lipschitz boundary $\Gamma \coloneqq \partial \Omega$. By $\abs{\cdot}$, we denote, without any ambiguity, the absolute value of a scalar, the Euclidean norm of a vector in $\R^d$, the $(d-1)$-dimensional Hausdorff measure of a surface (piece), or the $d$-dimensional Lebesgue volume of a measurable set.

Again, without any ambiguity, we write $\int_\Xi \cdot \d x$ for integration over a Lebesgue measurable set $\Xi \subseteq \Omega$ and over a Hausdorff measurable set $\Xi \subseteq \Gamma$.

For Lipschitz domains $\Xi \subseteq \Omega$, we denote by $\bm{n}_{\partial \Xi}$ the outward pointing unit normal vector on $\partial \Xi$.

For $1 < r < +\infty$, $\norm{\cdot}_{L^r(\Xi)}$ denotes the usual $L^r$-norm and $1 < r' < +\infty$ is  the Hölder conjugate, i.e., $1/r + 1/r' = 1$. For $r=2$, we additionally write $\dual{\cdot}{\cdot}_{\Xi}$ for the $L^2(\Xi)$-inner product. For vector-valued spaces $[L^r(\Xi)]^n$ with $n \in \N$, we will omit the superscript if it is clear from the context. 

Throughout, discrete (or data-sparse) quantities are indicated by an index, e.g., $\TT_\ell^\Gamma$ is a conforming triangulation of $\Gamma$ with corresponding Galerkin BEM approximation $\phi_\ell^\exact$ and induced potential $u_\ell^\exact$. Moreover, we always use the same index for related quantities, e.g., $\phi_\ell$ is a BEM approximation corresponding to $\TT_\ell^\Gamma$ etc.
%
Finally, we abbreviate notation in proofs and write $A \lesssim B$, if there holds $A \le cB$ with a constant $c > 0$ which is independent of the adaptivity index $\ell \in \N_0$ and clear from the context. We write $A \simeq B$ to abbreviate $A \lesssim B \lesssim A$.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Integer-order Sobolev spaces}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

For Lipschitz domains $\Xi \subseteq \Omega$, we define the usual integer-order Sobolev space
%
\begin{equation*}
 W^{1,r}(\Xi) \colon= \set{w \in L^r(\Xi) \given \nabla w \in L^r(\Xi)}
\end{equation*}
%
with corresponding norm
%
\begin{equation*}
 \norm{w}_{W^{1,r}(\Xi)} \coloneqq \bigl( \norm{w}_{L^r(\Xi)}^r + \norm{\nabla w}_{L^r(\Xi)}^r \bigr)^{1/r},
\end{equation*}
%
where $\nabla$ denotes the distributional gradient. Furthermore, defining $C_0^\infty(\Xi)$ as the space of smooth functions with compact support in $\Xi$, we set
%
\begin{equation*}
 W^{1,r}_{\partial \Xi}(\Xi) \coloneqq \overline{C_0^\infty(\Xi) \cap W^{1,r}(\Xi)}^{W^{1,r}(\Xi)}.
\end{equation*}
%
\begin{remark}
 Usually, one employs the notation $W^{1,r}_0(\Omega) = W^{1,r}_{\partial \Omega}(\Omega) = W^{1,r}_\Gamma(\Omega)$ for the space of $W^{1,r}$-functions with zero boundary conditions. However, our approach involves subdomains $\Xi \subseteq \Omega$ and corresponding boundary conditions. We therefore decided to use the notation $W^{1,r}_{\partial \Xi}(\Xi)$ to be explicit on these boundary conditions.
\end{remark}
%
For boundary pieces $\Xi \subseteq \Gamma$, we define 
%
\begin{equation*}
 W^{1,r}(\Xi) 
 \coloneqq 
 \set{\varphi \in L^r(\Xi) \given \nabla_{\Gamma} \varphi \in L^r(\Xi)}
\end{equation*}
%
with corresponding norm 
%
\begin{equation*}
 \norm{\varphi}_{W^{1,r}(\Xi)} 
 \coloneqq 
 \bigl( \norm{\varphi}_{L^r(\Xi)}^r + \norm{\nabla_{\Gamma} \varphi}_{L^r(\Xi)}^r \bigr)^{1/r},
\end{equation*}
%
where $\nabla_\Gamma$ denotes the surface gradient on the boundary $\Gamma$. For $r=2$, we write $H^1(\Xi) = W^{1,2}(\Xi)$ for either $\Xi \subseteq \Omega$ or $\Xi \subseteq \Gamma$. Additionally, we also write $H^1_{\partial \Xi}(\Xi) = W^{1,2}_{\partial \Xi}(\Xi)$ for $\Xi \subseteq \Omega$ being a Lipschitz domain. Moreover, we use the convention that $W^{0,r}(\Xi) = L^r(\Xi)$ and $H^0(\Xi) = L^2(\Xi)$ as well as $\norm{\cdot}_{W^{0,r}(\Xi)} = \norm{\cdot}_{L^r(\Xi)}$ and $\norm{\cdot}_{H^0(\Xi)} = \norm{\cdot}_{L^2(\Xi)}$ for $\Xi \subseteq \Omega$ or $\Xi \subseteq \Gamma$.

\subsection{Fractional-order Sobolev spaces}

For $0 < s < 1$, we define the $W^{s,r}(\Xi)$-seminorm as
%
\begin{equation*}
 |w|_{W^{s,r}(\Xi)} \coloneqq \begin{cases} \left( \int_{\Xi} \int_{\Xi} \frac{|w(x) - w(y)|^r}{\abs{x-y}^{d + sr}} \d x \d y \right)^{1/r} & \text{if } \Xi \subseteq \Omega, \\[1ex]
 \left( \int_{\Xi} \int_{\Xi} \frac{|w(x) - w(y)|^r}{\abs{x-y}^{d - 1 + sr}} \d x \d y \right)^{1/r} & \text{if }\Xi \subseteq \Gamma,
 \end{cases}
\end{equation*} 
%
and, additionally,
%
\begin{equation*}
|w|_{W^{1,r}(\Xi)} \coloneqq \begin{cases} \norm{\nabla w}_{L^2(\Xi)} & \text{if } \Xi \subseteq \Omega, \\[1ex]
\norm{\nabla_\Gamma w}_{L^2(\Xi)}  & \text{if }\Xi \subseteq \Gamma.
	\end{cases}
\end{equation*}
%
For $0 < s < 2$ and $s \neq 1$ we define the $W^{s,r}(\Xi)$-norm as
%
\begin{equation*}
 \norm{w}_{W^{s,r}(\Xi)} \coloneqq (\norm{w}_{W^{\lfloor s \rfloor,r}(\Xi)}^r + |w|_{W^{s - \lfloor s \rfloor,r}(\Xi)}^r)^{1/r},
\end{equation*}
%
establishing the fractional-order Sobolev space
%
\begin{equation*}
 W^{s,r}(\Xi) \coloneqq \set{w \in L^r(\Xi) \given \norm{w}_{W^{s,r}(\Xi)} < +\infty},
\end{equation*}
%
where $\N_0 \ni \lfloor s \rfloor \leq s$ denotes the largest possible integer and $W^{\lfloor s \rfloor,r}(\Xi)$ is the usual integer-order Sobolev space. In accordance with the definition of integer-order Sobolev spaces, we set $H^s(\Xi) \coloneqq W^{s,2}(\Xi)$ for $0 < s < 2$ and $s \neq 1$. Given a Lipschitz domain $\Xi \subseteq \Omega$, the trace operator $(\cdot) |_{\partial \Xi} \colon W^{s,r}(\Xi) \rightarrow W^{s - 1/r,r}(\partial \Xi)$ is well-defined and bounded for $1/r < s < 2$. Furthermore, there holds
%
\begin{equation*}
 W^{1,r}_{\partial \Xi}(\Xi) = \rm{ker}((\cdot) |_{\partial \Xi}) \cap W^{1,r}(\Xi).
\end{equation*}
%
Lastly, we note that the $W^{s,r}$-norm and $W^{s,r}$-seminorm are absolutely continuous with respect to the measure $\abs{\cdot}$ of the underlying space, i.e., for all $w \in W^{s,r}(\Xi)$, there holds
%
\begin{equation} \label{eq:abscont}
 \lim_{\abs{T} \to 0} \norm{w}_{W^{s,r}(T)} = 0 = \lim_{\abs{T} \to 0} \abs{w}_{W^{s,r}(T)}.
\end{equation}
%


\subsection{Negative-order Sobolev spaces on the boundary}


Let $\Xi \subseteq \Omega$ be a Lipschitz domain. For $0 \leq s \leq 1$, we define the negative-order Sobolev spaces on $\partial \Xi$ as
%
\begin{equation*}
	W^{-s,r}(\partial \Xi) \coloneqq (W^{s,r'}(\partial \Xi))',
\end{equation*}
%
where the duality pairing is defined by continuous extension of the pairing between $L^{r'}(\partial \Xi)$ and $L^{r}(\partial \Xi)$ and, without any ambiguity, is denoted by $\dual{\cdot}{\cdot}_{\partial \Xi}$. The space $H^{-s}(\partial \Xi)$ and the associated duality pairing is defined accordingly.

\subsection{The space \boldmath $H(\div,\Xi)$}

For $\Xi \subseteq \Omega$ being a Lipschitz domain, we set
%
\begin{equation*}
	H(\mathrm{div},\Xi) \coloneqq \set{\bm{\sigma} \in [L^2(\Xi)]^d \given \div \bm{\sigma} \in L^2(\Xi)}
\end{equation*}
%
equipped with the usual graph norm
%
\begin{equation*}
	\norm{\bm{\sigma}}_{H(\mathrm{div},\Xi)} \coloneqq \left( \norm{\bm{\sigma}}_{L^2(\Xi)}^2 + \norm{\div \bm{\sigma}}_{L^2(\Xi)}^2 \right)^{1/2}.
\end{equation*}
%
We note that the normal traces $\bm{\sigma}|_{\partial \Xi} \cdot \bm{n}_{\partial \Xi}$ of $\bm{\sigma} \in H(\div,\Xi)$ are well-defined and belong to $H^{-1/2}(\partial \Xi)$ by Green's formula$\colon$ For given $\varphi \in H^{1/2}(\partial \Xi)$, we choose $w \in H^1(\Xi)$ such that $w|_{\partial \Xi} = \varphi$. Then, we define
%
\begin{equation*}
 \dual{\bm{\sigma}|_{\partial \Xi} \cdot \bm{n}_{\partial \Xi}}{\varphi}_{\partial \Xi} \coloneqq \dual{\bm{\sigma}}{\nabla w}_{\Xi} + \dual{w}{\div \bm{\sigma}}_{\Xi}.
\end{equation*}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Meshes}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

A $k$-dimensional simplex $T \subseteq \R^d$ is a compact set satisfying $T = \mathrm{conv} (\NN_T)$ with vertices $\NN_T = \set{z_0, \ldots , z_k}$ for some $z_0, \ldots , z_k \in \R^d$ and $\abs{T} > 0$ for the $k$-dimensional measure. Let $\TT_\ell$ be a conforming mesh on $\Omega$, i.e., a partition of $\overline{\Omega}$ into $d$-dimensional simplices $T$ such that the intersection of two different elements $T \cap T'$ is either empty or the joint $k$-dimensional compact simplex $T \cap T' = \mathrm{conv}(\NN_T \cap \NN_{T'})$. Throughout, we assume that all considered meshes $\TT_{\ell}$ are obtained by a finite amount of newest-vertex bisection refinements of some initial conforming mesh $\TT_0$ of $\Omega$. We refer to~\cite{Stevenson2008} for newest vertex bisection for $d \geq 2$ with admissible $\TT_0$, as well as to \cite{Karkulik2012} for $d=2$ and to~\cite{Diening2025} for $d \geq 2$ with non-admissible $\TT_0$. It is well-known that newest vertex bisection guarantees uniform $\kappa$-shape regularity, i.e., there exists $\kappa > 0$ depending only on $\TT_0$ such that each refined mesh $\TT_\ell$ satisfies
%
\begin{equation*}
 \sup_{T \in \TT_\ell} \frac{\mathrm{diam}(T)}{\abs{T}^{1/d}} 
 \leq 
 \kappa.
\end{equation*}
%
Moreover, $\TT_\ell$ induces a conforming boundary mesh on $\Gamma$ by
%
\begin{equation} \label{eq:boundarymesh}
 \TT_\ell^\Gamma \coloneqq \TT_\ell|_\Gamma \coloneqq \set{T \cap \Gamma \given T \in \TT_\ell \text{ with }(d-1) \text{-dimensional measure } \abs{T \cap \Gamma} > 0},
\end{equation}
%
which is also $\kappa$-shape regular in the sense of
%
\begin{equation*}
\sup_{F \in \TT_\ell^\Gamma} \frac{\mathrm{diam}(F)}{\abs{F}^{d-1}} \leq \kappa.
\end{equation*}
%
We denote by $\NN_\ell$, $\EE_\ell$ and $\FF_\ell$ the sets of ($0$-dimensional) nodes, ($1$-dimensional) edges and ($(d-1)$-dimensional) facets of the mesh $\TT_\ell$, respectively. We define the patch of a set $U \subseteq \overline{\Omega}$ by
\begin{subequations} \label{eq:patch}
%
\begin{equation} \label{eq:1patch}
	\Omega_\ell[U] \coloneqq \mathrm{interior} \Bigl(\bigcup \TT_\ell[U]\Bigr) \quad \text{with} \quad \TT_\ell[U] \coloneqq \set{T \in \TT_\ell \given T \cap \overline{U} \neq \emptyset}.
\end{equation}
%
For $k \in \N$, we define the $k$-patch of $U$ as
%
\begin{equation} \label{eq:kpatch}
	\Omega_\ell^{[k]}[U] \coloneqq \mathrm{interior} \Bigl(\bigcup \TT_\ell^{[k]}[U] \Bigr)\quad \text{with} \quad \TT_\ell^{[k]}[U] \coloneqq \begin{cases} \TT_\ell[\Omega_\ell^{[k-1]}[U]] & \text{for } k > 1, \\
	\TT_\ell[U] & \text{for } k = 1
	\end{cases}.
\end{equation}
%
\end{subequations}
To ease notation, we write $\Omega_\ell^{[k]}[z] \coloneqq \Omega_\ell^{[k]}(\set{z})$ and $\TT_\ell^{[k]}[z] \coloneqq \TT_\ell^{[k]}(\set{z})$ for any $z \in \NN_\ell$. The $k$-patch $\Gamma_\ell^{[k]}[U]$ on the boundary is defined accordingly, with the volume mesh $\TT_\ell$ replaced by the induced boundary mesh $\TT_\ell^\Gamma$.

We define the piecewise constant mesh-size function $h_\ell \in L^\infty(\Omega)$ by $h_\ell|_T \coloneqq h_T \coloneqq |T|^{1/d}$ for every $T \in \TT_\ell$. The quantities $h_E \coloneqq \abs{E} = \mathrm{diam}(E)$ and $h_F \coloneqq \abs{F}^{1/(d-1)}$ for edges $E \in \EE_\ell$ and facets $F \in \FF_\ell$, respectively, are defined analogously. 

\subsection{Discrete spaces}

Given $q \in \N$, let $\P^{q-1}(U)$ be the space of polynomials of degree at most $q-1$ defined on some set $U$ and denote by
%
\begin{equation*}
 \PP^{q-1}(\TT_\ell) \coloneqq \set{v \in L^2(\Omega) \given v|_T \in \P^{q-1}(T) \text{ for all } T \in \TT_\ell}
\end{equation*}
%
the space of $\TT_\ell$-piecewise polynomials of degree at most $q-1$. 

We define the usual FEM-space of globally continuous $\TT_\ell$-piecewise polynomials by
%
\begin{equation*}
	\SS^q(\TT_\ell) \coloneqq \set{v \in \PP^q(\TT_\ell) \given v \text{ is continuous on } \Omega}  = \PP^q(\TT_\ell) \cap H^1(\Omega).
\end{equation*}
%
Given $\Upsilon \subseteq \Gamma$, we set
%
\begin{equation*}
 \SS_\Upsilon^q(\TT_\ell) \coloneqq \set{v \in \SS^q(\TT_\ell) \given v|_{\Upsilon} = 0}.
\end{equation*}
%
Furthermore, we define the $H(\div,\Omega)$-conforming Raviart--Thomas space
%
\begin{equation*}
 \RR\TT^{q-1}(\TT_\ell) \coloneqq \set{\bm{\sigma} \in H(\div,\Omega) \given \bm{\sigma}|_T \in [\P^{q-1}(T)]^d + \P^{q-1}(T) \cdot \mathrm{id} \text{ for all } T \in \TT_\ell},
\end{equation*}
%
where $\mathrm{id}(x) = x$ denotes the identity. Given $\Upsilon \subseteq \Gamma$, we set
%
\begin{equation*}
 \RR\TT^{q-1}_\Upsilon(\TT_\ell) \coloneqq \set{\bm{\sigma} \in \RR\TT^{q-1}(\TT_\ell) \given \bm{\sigma}|_{\Upsilon} \cdot \bm{n}_{\Upsilon} = 0}.
\end{equation*}
%
Discrete spaces on $\Gamma$ and $\omega_\ell$ are defined accordingly. Lastly, we introduce the $L^2$-orthogonal projections
%
\begin{equation*}
 \begin{split}
  Q_\ell^\Omega &\colon L^2(\Omega) \to \PP^0(\TT_\ell), 
  \quad Q_\ell^\Omega(w)|_T \coloneqq \dual{w}{1}_T/\abs{T}, \\
  Q_\ell^\Gamma &\colon L^2(\Gamma) \to \PP^0(\TT_\ell^\Gamma), 
  \quad Q_\ell^\Gamma(\varphi)|_F \coloneqq \dual{\varphi}{1}_F/\abs{F}.
 \end{split}
\end{equation*}
%
Given $0 < s \leq 1$, $Q_\ell^\Omega$ and $Q_\ell^\Gamma$ satisfy
%
\begin{equation} \label{eq:avgprop}
 \begin{split}
  \norm{w - Q_\ell^\Omega w}_{L^2(T)} 
  &\leq C
  h_T^s \abs{w}_{H^s(T)} 
  \quad \text{for all } T \in \TT_\ell \text{ and } w \in H^s(T), \\
  \norm{\varphi - Q_\ell^\Gamma \varphi}_{L^2(F)} 
  &\leq C
  h_F^s \abs{\varphi}_{H^s(F)} 
  \quad \text{for all } F \in \TT_\ell^\Gamma \text{ and } \varphi \in H^s(F),
 \end{split}
\end{equation}
%
with a constant $C > 0$ depending only on $\kappa$-shape regularity.

\subsection{Bases of discrete spaces}
For $U \subseteq \overline{\Omega}$ we denote by $\DD_\ell^q(U)$ the set of all Lagrange nodes of the space $\SS^q(\TT_\ell)$ in $U$. We abbreviate $\DD_\ell^q \coloneqq \DD_\ell^q(\overline{\Omega})$ and let $(\zeta_{\ell,z}^q)_{z \in \DD_\ell^q}$ be the corresponding nodal basis of $\SS^q(\TT_\ell)$, i.e., $\zeta_{\ell,z}^q(z') = \delta_{zz'}$ for all $z,z' \in \DD_\ell^q$ with Kroneckers's delta $\delta$. Hence, there holds
%
\begin{equation*}
 v_\ell = \sum_{z \in \DD_\ell^q} \alpha_z \zeta_{\ell,z}^q \quad \text{for all } v_\ell \in \SS^q(\TT_\ell)
\end{equation*}
%
with unique coefficients $\alpha_z = v_\ell(z) \in \R$. For every $T \in \TT_\ell$, the functions $(\zeta_{\ell,z}^q|_T)_{z \in \DD_{\ell}^q(T)}$ are related to the standard basis of $\P^q(T_{\mathrm{ref}})$, denoted by $(\widetilde{\zeta}_j)_{j=1}^{n_{q,d}}$, by an affine diffeomorphism $\Phi_T \colon T \to T_{\mathrm{ref}}$, i.e., for all $j = 1, \ldots , n_{q,d}$ there is a unique $z \in \DD_\ell^q(T)$ such that $\widetilde{\zeta}_j = \zeta_{\ell,z}^q|_T \circ \Phi_T$.

From now on, we assume that the polynomial degree $q$ is fixed. To ease notation, we will write $\DD_\ell \coloneqq \DD_\ell^q$, $\zeta_{\ell,z} \coloneqq \zeta_{\ell,z}^q$, and $n_d = n_{q,d}$.

Clearly, it holds $\DD_\ell(\Gamma) = \DD_\ell \cap \Gamma$. Hence, every $f_\ell \in \SS^q(\TT_\ell^\Gamma)$ in the form
%
\begin{equation*}
 f_\ell = \sum_{z \in \DD_\ell(\Gamma)} \alpha_z \zeta_z|_{\Gamma}
\end{equation*}
%
can be naturally lifted to a function $\widehat{f}_\ell \in \SS^q(\TT_\ell)$ by setting
%
\begin{equation} \label{eq:natext}
 \widehat{f}_\ell \coloneqq \sum_{z \in \DD_\ell(\Gamma)} \alpha_z \zeta_z,
\end{equation}
%
and we note that the discrete lifting $\widehat{(\cdot)} \colon \SS^q(\TT_\ell^\Gamma) \to \SS^q(\TT_\ell)$ is a linear operator.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Boundary integral equation}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\noindent For $-1/2 \leq s \leq 1/2$, we consider the single-layer integral operator $V \colon H^{s - 1/2}(\Gamma) \to H^{s + 1/2}(\Gamma)$ defined by
%
\begin{equation} \label{eq:singlelayer}
    (V\psi)(x) \coloneqq \int_\Gamma G(x-y) \psi(y) \d y \quad \text{for all } x \in \Gamma,
\end{equation}
%
where $G$ is the fundamental solution of the Laplace equation; see~\eqref{eq:fundamental}. The operator $V \colon H^{s - 1/2}(\Gamma) \rightarrow H^{s + 1/2}(\Gamma)$ is a bounded isomorphism for $-1/2 \leq s \leq 1/2$ and elliptic for $s = 0$, provided that $\mathrm{diam}(\Omega) < 1$ if $d=2$, which can always be achieved by scaling; see, e.g.,~\cite{Mclean2000}. Hence, for every $g \in H^{1/2}(\Gamma)$ there is a unique solution $\phi^\exact \in H^{-1/2}(\Gamma)$ of the problem
%
\begin{equation*}
    \dual{V \phi^\exact}{\psi}_{\Gamma} = \dual{g}{\psi}_{\Gamma} \quad \text{for all } \psi \in H^{-1/2}(\Gamma),
\end{equation*}
%
which satisfies $\norm{\phi^\exact}_{H^{-1/2}(\Gamma)} \simeq \norm{g}_{H^{1/2}(\Gamma)}$, where the hidden equivalence constants depend only on the operator norm of $V$ and its inverse and hence only on $
\Omega$. Moreover, the single-layer operator $\widetilde{V} \colon H^{-1/2}(\Gamma) \to H^1(\Omega)$ with the same integral representation as in~\eqref{eq:singlelayer} is a continuous linear operator satisfying $-\Delta(\widetilde{V}\phi) = 0$ for all $\phi \in H^{-1/2}(\Gamma)$.\\ \\
%

\subsection{Galerkin BEM}


Given $p \in \N_0$, we seek $\phi_\ell^\exact \in \PP^p(\TT_\ell^\Gamma)$ such that 
%
\begin{equation} \label{eq:weakdisc}
    \dual{V\phi_\ell^\exact}{\psi_\ell}_{\Gamma} = \dual{g}{\psi_\ell}_{\Gamma} \quad \text{for all } \psi \in \PP^p(\TT_\ell^\Gamma).
\end{equation}
%
By ellipticity, the Lax--Milgram lemma yields existence and uniqueness of the solution $\phi_\ell^\exact$ of~\eqref{eq:weakdisc} and there holds the Céa lemma
%
\begin{equation} \label{eq:cea}
	\norm{\phi^\exact - \phi_\ell^\exact}_{H^{-1/2}(\Gamma)} \lesssim \min_{\psi_\ell \in \PP^p(\TT_\ell^\Gamma)} \norm{\phi^\exact - \psi_\ell}_{H^{-1/2}(\Gamma)},
\end{equation}
%
where the hidden constant depends only on ellipticity and continuity of $V$ and hence only on $\Omega$.

\section{Functional error estimation and main result}
\label{section:mainresult}

%!TEX root = fabem_convergence.tex
\noindent
\subsection{General notation}

Throughout this section, we adhere to the following notation: 
Let $\Omega_0 \subseteq \Omega$ be an initial strip domain along the boundary, i.e., $\Omega_0$ is a bounded polyhedral Lipschitz domain with $\Gamma = \partial\Omega \subseteq \partial\Omega_0$.
Let $\TT_\ell$ be a conforming triangulation of $\Omega_0$ into simplices.
Let $\TT_\ell^\Gamma \coloneqq \TT_\ell|_\Gamma$ be the induced conforming triangulation of the boundary $\Gamma = \partial\Omega$ into surface simplices defined in~\eqref{eq:boundarymesh}. For fixed $k \in \N$, let $\TT_\ell^\omega \coloneqq \TT_\ell^{[k]}[\Gamma] \subseteq \TT_\ell$ be the $k$-patch of $\Gamma$, e.g., for $k = 2$, the patch $\TT_\ell^{[2]}[\Gamma]$ consists of all volume simplices $T \in \TT_\ell$ that touch an element $T' \in \TT_\ell$ with $T' \cap \Gamma \neq \emptyset$; see~\eqref{eq:patch} for the formal definition.
Let $\omega_\ell \coloneqq {\rm interior}\big( \bigcup \TT_\ell^\omega \big)$ denote the induced strip domain along $\Gamma$ and $\Gamma_\ell^\complement \coloneqq \partial \omega_\ell \backslash \Gamma$ be the complementary boundary part, i.e., $\partial\omega_\ell = \Gamma \cup \Gamma_\ell^\complement$. By definition of $\omega_\ell$, we note that $\Gamma_\ell^\complement$ is indeed closed and well separated from $\Gamma$ in the sense that $\dist(\Gamma, \Gamma_\ell^\complement) > 0$. We refer to Figure~\ref{fig:strip} for an illustration.

\begin{figure}[!ht]
   \includegraphics[scale=0.5]{numerics/Plots/Square/squarereferencemesh.pdf}

   \caption{Boundary strip $\omega_\ell$ ({\color{blue} blue}) of strip depth $k=2$ of a square domain. The outer boundary $\Gamma$ is depicted in {\color{red} red}, the complementary boundary $\Gamma_\ell^\complement$ in {\color{green} green}.}

    \label{fig:strip}

\end{figure}
In the remainder of this section, we recall the ideas of~\cite{Kurz2020} for functional \textsl{a~posteriori} error estimation and formulate our main result. To this end, let $p\in \N_0$ und $q \in \N$ be polynomial degrees for the BEM as well as the auxiliary problems, respectively.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Functional \textsl{a~posteriori} error estimation (upper bound)}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

Suppose additional regularity $g \in H^1(\Gamma)$ for the inhomogeneous Dirichlet data in~\eqref{eq:poisson} (instead of only $g \in H^{1/2}(\Gamma)$).
Note that this leads to additional regularity $\phi^\exact \in L^2(\Gamma)$ of the solution to~\eqref{eq:bie} (instead of only $\phi^\exact \in H^{-1/2}(\Gamma)$).
Let $\phi_\ell \in \PP^p(\TT_\ell^\Gamma)$ be an approximation of $\phi^\exact$.
Since $\Delta u_\ell = 0$ for $u_\ell \coloneqq \widetilde{V} \phi_\ell$, the Dirichlet principle yields
%
\begin{equation*}
 \norm{\nabla (u^\exact - u_\ell)}_{L^2(\Omega)} 
 \leq \norm{\nabla w}_{L^2(\Omega)} 
 \quad \text{for all } w \in H^1(\Omega) 
 \text{ with } w|_\Gamma = (u^\exact-u_\ell)|_\Gamma
 = g - u_\ell|_\Gamma.
\end{equation*}
%
%We want to take advantage of the inequality above and derive a computable, reliable error estimator. \\ \\
%
Since discrete functions cannot satisfy continuous Dirichlet conditions, let $J_\ell \colon H^{1/2}(\Gamma) \rightarrow \SS^q(\TT_\ell^{\Gamma})$ be an $H^1(\Gamma)$-stable projection, i.e., there is a constant $\const{C}{stab}$ such that $\norm{J_\ell \psi}_{H^1(\Gamma)} \leq \const{C}{stab} \norm{\psi}_{H^1(\Gamma)}$ for all $\psi \in H^1(\Gamma)$.
Then, the discrete auxiliary problem reads:
Find $w_\ell \in \SS^q(\TT_\ell^\omega)$ such that
%
\begin{equation} \label{eq:defwh}
 \begin{split}
  \dual{\nabla w_\ell}{\nabla v_\ell}_{L^2(\omega_\ell)} 
  &= 
  0 
  \quad 
  \text{for all } v_\ell \in \SS^q_{\partial \omega_\ell}(\TT_\ell^\omega), \\
  w_\ell|_{\Gamma} 
  &= 
  g_\ell 
  \coloneqq 
  J_\ell(g - V\phi_\ell), \\ 
  w_\ell|_{\Gamma_\ell^\complement} 
  &= 
  0.
 \end{split}
\end{equation}
%
It is well-known that~\eqref{eq:defwh} admits a unique solution $w_\ell \in \SS^q(\TT_\ell^\omega)$; see, e.g.,~\cite{Bartels2004,afkpp2013,Feischl2014}.
According to the homogeneous Dirichlet condition on $\Gamma_\ell^\complement$, we can extend $w_\ell$ by zero to $w_\ell \in H^1(\Omega)$. Therefore,~\cite[Theorem~5]{Kurz2020} proves
\begin{align}\label{eq:upper-bound}
 \norm{\nabla (u^\exact - u_\ell)}_{L^2(\Omega)} 
 \le 
 \norm{\nabla w_\ell}_{L^2(\Omega)} + \norm{(1-J_\ell)(g - V\phi_\ell)}_{H^{1/2}(\Gamma)}.
\end{align}
By assumption on $g$ and the mapping properties of $V$, there holds $g - V\phi_\ell \in H^1(\Gamma)$. Moreover, the assumptions on the projection $J_\ell$ prove the Poincar\'e-type estimate
\begin{equation}\label{eq:rel}
 \const{C}{osc}^{-1} \, \norm{(1-J_\ell)(g - V\phi_\ell)}_{H^{1/2}(\Gamma)} 
 \leq 
 \norm{h_\ell^{1/2} \nabla_\Gamma (1-J_\ell)(g - V\phi_\ell)}_{L^2(\Gamma)}
 \eqqcolon \osc_\ell,
\end{equation}
where the constant $\const{C}{osc}$ depends only on $\const{C}{stab}$, $\Gamma$, and $\kappa$-shape regularity of $\TT_\ell$; see~\cite[Theorem~4]{kop2013} for $q = 1$ and~\cite[Lemma~7]{Aurada2015} for $q \ge 1$. Combining~\eqref{eq:upper-bound}--\eqref{eq:rel}, we prove
%
\begin{equation} \label{eq:compupperbound}
 \norm{\nabla (u^\exact - u_\ell)}_{L^2(\Omega)} 
 \leq
 \norm{\nabla w_\ell}_{L^2(\Omega)} + \const{C}{osc} \, \osc_\ell 
 \eqqcolon 
 \eta_\ell + \const{C}{osc} \, \osc_\ell
\end{equation}
%
which is the computable upper bound of~\eqref{eq:estimation} with known constant $1$ up to data oscillations.

\begin{remark} \label{rem:whjustification}
The auxiliary problem~\eqref{eq:defwh} is motivated by the fact that, for $\omega_\ell = \Omega$ and $\Gamma_\ell^\complement = \emptyset$, the discrete function $w_\ell$ is the unique FEM approximation of the potential error, i.e., $w_\ell \approx w \coloneqq u^\exact - u_\ell$. As noted above, the homogeneous Dirichlet condition on $\Gamma_\ell^\complement$ is chosen to allow for the conforming extension of $w_\ell$ from the strip domain $\omega_\ell$ to the whole of $\Omega$.
\end{remark}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Functional \textsl{a~posteriori} error estimation (lower bound)}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

In order to obtain a computable lower bound, we aim to find a solution pair $(\ttau_\ell, p_\ell) \in \RR^{q-1}_{\Gamma_\ell^\complement}(\TT_\ell^\omega) \times \PP^{q-1}(\TT_\ell^\omega)$ such that 
%
\begin{equation} \label{eq:mixed}
	\begin{split}
		\dual{\ttau_\ell}{\ssigma_\ell}_{L^2(\omega_\ell)} + \dual{\div \ssigma_\ell}{p_\ell}_{L^2(\omega_\ell)} &= \dual{g - V\phi_\ell}{\ssigma_\ell \cdot \nn}_{L^2(\Gamma)} \\
		\dual{\div \ttau_\ell}{q_\ell}_{L^2(\omega_\ell)} &= 0
	\end{split}
\end{equation}
%
for all $(\ssigma_\ell, q_\ell) \in \RR^{q-1}_{\Gamma_\ell^\complement}(\TT_\ell^\omega) \times \PP^{q-1}(\TT_\ell^\omega)$. It is well-known that this problem has a unique solution $(\ttau_\ell, p_\ell) \in \RR^{q-1}_{\Gamma_\ell^\complement}(\TT_\ell^\omega) \times \PP^{q-1}(\TT_\ell^\omega)$; see, e.g.,~\cite{Bahriawati2005}. 
According to the homogeneous boundary condition $\ttau_\ell \cdot \nn = 0$ on $\Gamma_\ell^\complement$ included in the definition of $\RR^{q-1}_{\Gamma_\ell^\complement}(\TT_\ell^\omega)$, we can extend $\ttau_\ell$ by zero to $\ttau_\ell \in \boldsymbol{H}(\div, \Omega)$.
From~\cite[Theorem~5]{Kurz2020}, we then have that
%
\begin{equation*}
	2\dual{g - V\phi_\ell}{\ttau_\ell \cdot \nn}_{L^2(\Gamma)} - \norm{\ttau_\ell}_{L^2(\omega_\ell)}^2 \leq \norm{\nabla (u^\exact - u_\ell)}_{L^2(\Omega)}^2.
\end{equation*}
%
Plugging $(\ssigma_\ell, q_\ell) = (\ttau_\ell, p_\ell)$ into~\eqref{eq:mixed}, we obtain
%
\begin{equation*}
	\begin{split}
		\norm{\ttau_\ell}_{L^2(\omega_\ell)}^2 + \dual{\div \ttau_\ell}{p_\ell}_{L^2(\omega_\ell)} &= \dual{g - V\phi_\ell}{\ttau_\ell \cdot \nn}_{L^2(\Gamma)} \\
		\dual{\div \ttau_\ell}{p_\ell}_{L^2(\omega_\ell)} &= 0
	\end{split}
\end{equation*}
%
%which yields
%
%\begin{equation*}
%	\norm{\ttau_\ell}_{L^2(\omega_\ell)}^2 = \dual{g - V\phi_\ell^\exact}{\nn \cdot \ttau_\ell}_{L^2(\Gamma)},
%\end{equation*}
%
and hence
%
\begin{equation} \label{eq:lower-bound}
 \tau_\ell^2 \coloneqq \norm{\ttau_\ell}_{L^2(\omega_\ell)}^2 
 = 
 2\dual{g - V\phi_\ell}{\ttau_\ell \cdot \nn}_{L^2(\Gamma)} - \norm{\ttau_\ell}_{L^2(\omega_\ell)}^2 
 \leq 
 \norm{\nabla (u^\exact - u_\ell)}_{L^2(\Omega)}^2.
\end{equation}
Altogether, we proved the computable lower bound of~\eqref{eq:estimation} with known constant $1$.

\begin{remark} \label{rem:}
The auxiliary problem~\eqref{eq:mixed} is motivated by the fact that, for $\omega_\ell = \Omega$ and $\Gamma_\ell^\complement = \emptyset$, the discrete function $\ttau_\ell$ is the unique mixed FEM approximation of the potential error, i.e., $\ttau_\ell \approx \ttau \coloneqq \nabla(u^\exact - u_\ell)$. As noted above, the homogeneous boundary condition on $\Gamma_\ell^\complement$ is chosen to allow for the conforming extension of $\ttau_\ell$ from the strip domain $\omega_\ell$ to the whole of $\Omega$.
\end{remark}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Galerkin BEM, adaptive algorithm, and main result}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

From now on, we restrict to Galerkin BEM. Given the triangulation $\TT_\ell^\Gamma$ of $\Gamma$, let $\phi_\ell^\exact \in \PP^p(\TT_\ell^\Gamma)$ be the unique solution to~\eqref{eq:weakdisc}. 
The adaptive algorithm is driven by the computable upper bound from~\eqref{eq:estimation}.
To this end, let $w_\ell^\exact = w_\ell \in \SS^q(\TT_\ell^\omega)$ be the unique solution to~\eqref{eq:defwh} for $\phi_\ell = \phi_\ell^\exact$, where we employ the Scott--Zhang projector $J_\ell \colon L^2(\Gamma) \to \SS^q(\TT_\ell^\Gamma)$ on the boundary as considered, e.g., in~\cite{Feischl2014} for $q = 1$ and~\cite{Aurada2015} for $q \ge 1$; see Section~\ref{section:proof-mainresult} below for the definition.
With this, we define the $\TT_\ell$-elementwise contributions 
%
\begin{equation}\label{eq:indicators}
 \begin{split}
  \eta_\ell(T) 
  &\coloneqq 
  \norm{\nabla w_\ell^\exact}_{L^2(T)}, \\
  \osc_\ell(T) 
  &\coloneqq  
  \norm{h_\ell^{1/2} \nabla_\Gamma (1-J_\ell)(g - V\phi_\ell^\exact)}_{L^2(\partial T \cap \Gamma)}
\quad \text{for all } T \in \TT_\ell.
 \end{split}
\end{equation}
%
Based on these indicators and $\sum_{T \in \TT_\ell^\omega} \eta_\ell(T)^2 = \norm{\nabla w_\ell^\exact}_{L^2(\omega_\ell)}^2$ and $\sum_{T \in \TT_\ell^\omega} \osc_\ell(T)^2 = \osc_\ell^2$, the following adaptive algorithm has essentially been proposed by~\cite{Kurz2020}, where we note that $\eta_\ell(T) = 0 = \osc_\ell(T)$ for all $T \in \TT_\ell \backslash \TT_\ell^\omega$.

\begin{algorithm}[Adaptive algorithm]\label{algo:adap}
\textbf{Input:}
Initial strip domain $\Omega_0 \subseteq \Omega$ with $\Gamma = \partial\Omega \subseteq \partial\Omega_0$ and conforming triangulation $\TT_0$ of $\Omega_0$, 
polynomial degrees $p \in \N_0$ for the BEM in~\eqref{eq:weakdisc} and $q \in \N$ for the estimator in~\eqref{eq:compupperbound},
patch order $k \in \N$,
marking function $M \colon \R_{\ge0} \to \R_{\ge0}$ that is continuous at $0 = M(0)$,
and right-hand side $g \in H^1(\Gamma)$.
\\
\textbf{Loop:} For all $\ell = 0,1,2,\dots$, repeat the following steps:
\begin{enumerate}[label = \rm(\roman*)]
%
\item Extract the boundary mesh $\TT_{\ell}^{\Gamma} = \TT_\ell|_\Gamma$ from $\TT_{\ell}$ and solve~\eqref{eq:weakdisc} to obtain the Galerkin BEM solution $\phi_{\ell}^\exact \in \PP^p(\TT_{\ell}^{\Gamma})$.
%
\item Extract the boundary strip $\omega_\ell \coloneqq {\rm interior}\big( \bigcup \TT_\ell^\omega \big)$ and the associated triangulation $\TT_{\ell}^{\omega} \coloneqq \TT_\ell^{[k]}[\Gamma]$,
and compute the auxiliary FEM solution $w_\ell^\exact \in \SS^q(\TT_\ell^\omega)$ by solving~\eqref{eq:defwh} with $\phi_\ell = \phi_\ell^\exact$ and $J_\ell$ being the Scott--Zhang projector.
%
\item Compute the error indicators $\eta_\ell(T)$ and $\osc_\ell(T)$ from~\eqref{eq:indicators} for all $T \in \TT_\ell^\omega$.
%
\item Determine a set $\MM_\ell \subseteq \TT_{\ell}^{\omega}$ (usually of minimal cardinality) such that
\begin{align}\label{eq:marking}
 \max_{T \in \TT_{\ell}^{\omega} \setminus \MM_{\ell}} \big[ \eta_\ell(T)^2 + \osc_\ell(T)^2 \big] 
 \leq 
 M\Bigl(\max_{T \in \MM_{\ell}} \big[ \eta_\ell(T)^2 + \osc_\ell(T)^2 \big]\Bigr).
\end{align}
%
\item Generate a new triangulation $\TT_{\ell+1}$ by use of newest vertex bisection such that at least all elements in $\MM_{\ell}$ are refined, i.e., $\MM_\ell \subseteq \TT_\ell \backslash \TT_{\ell+1}$.
%
\end{enumerate}
\end{algorithm}

\begin{remark}
The marking criterion~\eqref{eq:marking} is proposed and analyzed in the context of adaptive finite element methods in~\cite{Siebert2011}. Clearly, it is satisfied with $M(t) = t$ if 
\begin{align*}
 \max_{T \in \TT_{\ell}^{\omega}} \big[ \eta_\ell(T)^2 + \osc_\ell(T)^2 \big] 
 =  \max_{T \in \MM_\ell} \big[ \eta_\ell(T)^2 + \osc_\ell(T)^2 \big],
\end{align*}
i.e., $\MM_\ell$ contains one element with largest overall indicator, which can easily be enforced algorithmically at linear cost.
Instead, the work~\cite{Kurz2020} uses the D\"orfler marking criterion from~\cite{doerfler1996} to select, for some fixed $0 < \theta \le 1$, the set $\MM_\ell \subseteq \TT_{\ell}^{\omega}$ via
\begin{align}\label{eq:doerfler}
 \theta \sum_{T \in \TT_\ell^\omega} \big[ \eta_\ell(T)^2 + \osc_\ell(T)^2 \big]
 \le \sum_{T \in \MM_\ell} \big[ \eta_\ell(T)^2 + \osc_\ell(T)^2 \big].
\end{align}
Usually, $\MM_\ell$ is obtained by sorting of the overall indicators so that
\begin{align*}
 \max_{T \in \TT_{\ell}^{\omega} \backslash \MM_\ell} \big[ \eta_\ell(T)^2 + \osc_\ell(T)^2 \big] 
 \le \min_{T \in \MM_\ell} \big[ \eta_\ell(T)^2 + \osc_\ell(T)^2 \big]
\end{align*}
and hence~\eqref{eq:marking} is satisfied with $M(t) = t$. If $\MM_\ell$ in~\eqref{eq:doerfler} is obtained by inexact binsort as proposed in~\cite{stevenson2007}, then
\begin{align*}
 \max_{T \in \TT_{\ell}^{\omega} \backslash \MM_\ell} \big[ \eta_\ell(T)^2 + \osc_\ell(T)^2 \big] 
 \le 2  \min_{T \in \MM_\ell} \big[ \eta_\ell(T)^2 + \osc_\ell(T)^2 \big]
\end{align*}
and hence\eqref{eq:marking} is satisfied with $M(t) = 2t$.
\end{remark}

\begin{remark}
Algorithm~\ref{algo:adap} could also include the computation of the estimator $\tau_{\ell}$ from \eqref{eq:lower-bound} in order to determine the guaranteed lower bound~\eqref{eq:estimation}. However, our main result of Theorem~\ref{theorem:mainresult} exploits only the upper bound \eqref{eq:compupperbound} of \eqref{eq:estimation}.
\end{remark}

The following plain convergence theorem is the main result of this work. The subsequent sections will be concerned with its proof.

\begin{theorem}[Efficiency and plain convergence of functional upper bound]\label{theorem:mainresult}
Under the foregoing assumptions, Algorithm~\ref{algo:adap} guarantees the existence of a constant $\const{C}{eff} > 0$ such that
\begin{equation}\label{eq:theorem:mainresult}
 \begin{split}
  \const{C}{eff}^{-1}\eta_\ell 
  \leq 
  \norm{\phi^\exact - \phi_\ell^\exact}_{H^{-1/2}(\Gamma)} 
  \leq 
  \const{C}{V} \norm{u^\exact - u_\ell^\exact}_{H^1(\Omega)}
 \end{split}
\end{equation}
%
as well as plain convergence in the sense of
%
\begin{equation} \label{eq:plainconv}
 \const{C}{P}^{-1} \norm{u^\exact - u_\ell^{\exact}}_{H^1(\Omega)} 
 \leq 
 \norm{\nabla(u^\exact - u_\ell^\exact)}_{L^2(\Omega)} 
 \eqreff{eq:compupperbound}{\leq} 
 \eta_\ell +  \const{C}{osc}\mathrm{osc}_\ell
 \xrightarrow{\ell \to \infty} 
 0,
\end{equation}
where $\const{C}{P} > 0$ is a Poincaré constant and $C_V > 0$ is the operator norm of $\widetilde V \colon H^{-1/2}(\Gamma) \to H^1(\Omega)$, which both depend only on $\Omega$.
\end{theorem}

\section{Proof of Theorem~\ref{theorem:mainresult} (Efficiency and plain convergence)}
\label{section:proof-mainresult}

%!TEX root = fabem_convergence.tex

\noindent
The proof of Theorem~\ref{theorem:mainresult} crucially hinges on \textsl{a~priori} convergence of the solutions to the auxiliary problems \eqref{eq:defwh}, which relies on a special construction of the Scott--Zhang projector $P_\ell \colon H^1(\Omega) \to \SS^q(\TT_\ell)$ from \cite{Scott1990}. We briefly present this construction as well as properties of $P_\ell$. Subsequently, we prove \textsl{a~priori} convergence of the auxiliary solutions and efficiency of the functional error estimator. The proof of Theorem~\ref{theorem:mainresult} is then concluded by combining these results.

\subsection{Scott--Zhang projector} \label{subsec:SZ}
Recall that $\DD_\ell = \DD_\ell(\overline{\Omega})$ denotes the Lagrange nodes of $\SS^q(\TT_\ell)$. In essence, the construction of the Scott--Zhang projector $P_\ell \colon H^1(\Omega) \to \SS^q(\TT_\ell)$ in \cite{Scott1990} is based on selecting $(K_{\ell,z})_{z \in \DD_\ell}$ with $z \in K_{\ell,z}$, where $K_{\ell,z}$ is either an element $K_{\ell,z} \in \TT_\ell$ or a facet $K_{\ell,z} \in \FF_\ell$ for all $z \in \DD_\ell$.Then, one chooses $\psi_{\ell,z} \in \P^q(K_{\ell,z})$ such that
%
\begin{equation*}
 \int_{K_{\ell,z}} \psi_{\ell,z} \zeta_{\ell,z'} \, \d{x} 
 = 
 \delta_{zz'} 
 \quad \text{for all } z \in \DD_\ell 
 \text{ and } z' \in \DD_\ell\cap K_{\ell,z}
\end{equation*}
%
to define the projector $P_\ell$ by
%
\begin{equation} \label{eq:SZdef}
  P_\ell w 
  = 
  \sum_{z \in \DD_\ell} \Bigl(\int_{K_{\ell,z}} \psi_{\ell,z} w \d x \Bigr) \zeta_{\ell,z}.
\end{equation}
%
The construction of $P_\ell$ thus provides considerable freedom in the choice of the sets $(K_{\ell,z})_{z \in \DD_\ell}$, which can be exploited to ensure certain additional properties of $P_\ell$. 


\begin{lemma} \label{lem:SZconstruct}
 There exist sets $(K_{\ell,z})_{\ell \in \N_0,z \in \DD_\ell}$ such that the following properties hold.
 \begin{enumerate}[label = \rm(\roman*)]
  \item If $z \in \mathrm{interior}(T_z) \cap \DD_\ell$ for some $T_z \in \TT_\ell$, we set $K_{\ell,z} \coloneqq T_z$.
  \item If $z \in \mathrm{interior}(F_z) \cap \DD_\ell$ for some facet $F_z \in \FF_\ell$, we set $K_{\ell,z} \coloneqq F_z$.
  \item If $z \in \DD_\ell(\Gamma)$, then $K_{\ell,z} \subseteq \Gamma$.
  \item If $z \in \DD_\ell(\omega_{\ell})$, then $\mathrm{interior}(K_{\ell,z}) \subseteq \omega_{\ell}$.
  \item If $z \in \DD_\ell(\Omega \setminus \omega_{\ell})$, then $K_{\ell,z} \subseteq \Omega \setminus \omega_{\ell}$.
  \item If $z \in \DD_\ell \cap \DD_{\ell-1}$ and $\zeta_{\ell,z} = \zeta_{\ell-1,z}$, then $K_{\ell,z} = K_{\ell-1,z}$.
 \end{enumerate}
\end{lemma}


\begin{proof}
In the following, we prove that all the properties \rm (i)--(vi) can hold simultaneously. The proof is split into $3$ steps.

\textbf{Step~1 (Properties of \boldsymbol{$\omega_\ell$}).}
We first note that, due to the construction of $\omega_\ell$, whenever $z \in \DD_\ell \cap \omega_\ell$, there holds $\mathrm{interior}(F_z) \subset \omega_\ell$ for all facets $F_z \in \FF_\ell$ with $z \in F_z$. Additionally, if $z \in \mathrm{interior}(T_z)$ for some element $T_z \in \TT_\ell$, there holds $\mathrm{interior}(T_z) \subseteq \omega_\ell$. By a similar argument, an analogous statement holds for $\Omega \setminus \overline{\omega_\ell}$. Moreover, if $z \in \DD_\ell \cap \Gamma_\ell^\complement$, there exists a facet $F_z \in \FF_\ell$ with $z \in F_z \subset \Omega \setminus \omega_\ell$. Hence, whenever $z \in \DD_\ell(\Omega \setminus \omega_\ell)$, there exists either an element $T_z \in \TT_\ell$ with $z \in \mathrm{int}(T_z) \subset \Omega \setminus \overline{\omega_\ell}$ or a facet $F_z \in \FF_\ell$ with $z \in F_z \subset \Omega \setminus \omega_\ell$. We further note that the properties \rm (iii)--(v) are independent of each other since $\Gamma$, $\omega_\ell$, and $\Omega \setminus \omega_\ell$ are pairwise disjoint.

In the following, we will construct $(K_{\ell,z})_{\ell \in \N_0,z \in \DD_\ell}$ recursively starting with $\ell = 0$. 

 \textbf{Step~2 (Case \boldsymbol{$\ell = 0$}).} We first note that $\ell=0$ excludes \rm (vi). Let $z \in \mathrm{int}(T_z) \cap \DD_0$ for some $T_z \in \TT_0$ and define $K_{0,z} \coloneqq T_z$. Note that this excludes \rm (iii). Hence, it only remains to prove \rm{(iv)--(v)}. By Step~1, $z \in \omega_0$ implies $T_z \in \TT_0^\omega$ and hence $\mathrm{interior}(K_{0,z}) =  \mathrm{interior}(T_z) \subseteq \omega_0$, yielding \rm (iv). Similarly, Step~1 also establishes \rm (v).

 Let $z \in \mathrm{interior}(F_z) \cap \DD_0$ for some facet $F_z \in \FF_\ell$ and define $K_{0,z} \coloneqq F_z$. Arguing analogously to the case $z \in \mathrm{interior}(T_z) \cap \DD_0$, we show that \rm{(iv)--(v)} hold. It thus remains to prove \rm (iii), which is an easy consequence of the fact that $z \in \Gamma$ implies $K_{0,z} = F_z \subseteq \Gamma$.

 If $z \in \DD_0$ is neither contained in the interior of an element nor the interior of a facet, we have to choose a suitable facet such that \rm (iii)--(v) hold. If $z \in \Gamma$, there exists $F_z \in \TT_0^\Gamma$ with $z \in F_z$. Choosing $K_{0,z} \coloneqq F_z$ proves \rm (iii). Given $z \in \omega_0$ and the fact that $z$ is not contained in the interior of an element, Step~1 yields the existence of $F_z \eqqcolon K_{0,z}$ with $z \in F_z$ and $\mathrm{int}(F_z) \subset \omega_0$, which thus proves \rm (iv). Lastly, if $z \in \Omega \setminus \omega_0$, due to Step~1, there exists $F_z \eqqcolon K_{0,z}$ with $z \in F_z$ and $F_z \subseteq \Omega \setminus \omega_0$.

 \textbf{Step~3 (Induction on \boldsymbol{$\ell$}).}
 Suppose that $(K_{\ell-1,z})_{z \in \DD_{\ell-1}}$ is chosen such that \rm{(i)--(vi)} hold for $\ell-1$. We now choose $K_{\ell,z}$ such that \rm (i)--(vi) also hold for $\ell$.

Let $z \in \DD_\ell$. If either $z \notin \DD_{\ell-1}$ or $\zeta_{\ell,z} \neq \zeta_{\ell-1,z}$, \rm (vi) is excluded, and an analogous choice of $K_{\ell,z}$ as in the case $\ell=0$, guarantees \rm (i)--(v).

 Let $z \in \DD_\ell \cap \DD_{\ell -1}$ and $\zeta_{\ell,z} = \zeta_{\ell-1,z}$ and define $K_{\ell,z} \coloneqq K_{\ell-1,z}$. This validates \rm (vi). If $z \in \mathrm{interior}(T_z)$ for some element $T_z \in \TT_\ell$ or $z \in \mathrm{interior}(F_z)$ for some facet $F_z \in \FF_\ell$, $\zeta_{\ell,z} = \zeta_{\ell-1,z}$ implies that $K_{\ell,z} = K_{\ell-1,z} = T_z \in \TT_{\ell-1} \cap \TT_\ell$ or $K_{\ell,z} = K_{\ell-1,z} = F_z \in \FF_{\ell-1} \cap \FF_\ell$, respectively. This proves \rm (i)--(ii). If $z \in \Gamma$, the induction hypothesis yields $K_{\ell,z} = K_{\ell-1,z} \subset \Gamma$. This proves \rm (iii). If $z \in \omega_\ell$, Step~1 yields $K_{\ell,z} \subset \omega_\ell$. This proves \rm (iv). By analogous arguments, there holds \rm (v). This concludes the proof.
\end{proof}


From now on, we assume that the Scott--Zhang projector \eqref{eq:SZdef} is constructed with sets $(K_{\ell,z})_{z \in \DD_\ell}$ from Lemma~\ref{lem:SZconstruct}. 
We note that the Scott--Zhang projectors on boundaries $J_\ell \colon L^2(\Gamma) \to \SS^q(\TT_\ell^\Gamma)$ from \cite{Feischl2014, Aurada2015} are related to $P_\ell$ by the trace operator $(P_\ell v)|_\Gamma = J_\ell(v|_\Gamma)$ for all $v \in H^1(\Omega)$.
The following result states certain stability properties of the Scott--Zhang projector, which are immediate consequences of the considerations of, e.g., \cite{Scott1990,Ciarlet2013}. They rely only on the properties Lemma~\ref{lem:SZconstruct}\rm (i)--(iii).

\begin{lemma}[Stability of Scott--Zhang projectors] \label{lem:SZ}
  There exists a constant $\const{C}{stab}>0$ depending only on $\kappa$-shape regularity of $\TT_\ell$, $s$, and $t$  such that the following statements \rm (a)--(b) hold.
 \begin{enumerate}[label = \rm(\roman*)]
  \item[(a)] For given $1/2 < t \leq 1$, $0 < s \leq t$, $T \in \TT_\ell$, and $w \in H^t(\Omega_\ell[T])$, there holds
  %
  \begin{equation} \label{eq:SZvolstab}
   \abs{P_\ell w}_{H^s(T)}
   \leq
   \const{C}{stab} h_T^{t-s} \abs{w}_{H^t(\Omega_\ell[T])}.
  \end{equation}
  In particular, $P_\ell w$ is the quasi-best approximation of $w$ in the sense of
  %
  \begin{equation} \label{eq:SZvolbest}
    \abs{w - P_\ell w}_{H^s(T)}
    \leq
    \const{C}{stab} h_T^{t-s} \min_{w_\ell \in \SS^q(\TT_\ell)} \abs{w - w_\ell}_{H^t(\Omega_\ell[T])}.
  \end{equation}
  %
  \item[(b)] For given $0 < s \leq t \leq 1$, $F \in \TT_\ell^\Gamma$ and $\varphi \in H^t(\Gamma_\ell[F])$, there holds
  %
  \begin{equation} \label{eq:SZtracestab}
    \abs{J_\ell \varphi}_{H^s(F)}
    \leq
    \const{C}{stab} h_F^{t-s} \abs{\varphi}_{H^t(\Gamma_\ell[F])}.
  \end{equation}
  %
  In particular, $J_\ell w$ is the quasi-best approximation of $w$ in the sense of
  %
  \begin{equation} \label{eq:SZtracebest}
   \abs{\varphi - J_\ell \varphi}_{H^s(F)}
   \leq
   \const{C}{stab} h_F^{t-s} \min_{\varphi_\ell \in \SS^q(\TT_\ell^\Gamma)} \abs{\varphi - \varphi_\ell}_{H^t(\Gamma_\ell[F])}
  \end{equation}
  %
  Additionally, for $\varphi \in L^2(\Gamma_\ell[F])$ there holds 
  %
  \begin{equation} \label{eq:SZtraceL2}
   \norm{J_\ell \varphi}_{L^2(F)} \leq \const{C}{stab} \norm{\varphi}_{L^2(\Gamma_\ell[F])}
  \end{equation}
  %
  and
  %
  \begin{equation} \label{eq:SZtraceL2best}
    \norm{\varphi - J_\ell \varphi}_{L^2(F)} \leq \const{C}{stab} \min_{\varphi_\ell \in \SS^q(\TT_\ell^\Gamma)} \norm{\varphi - \varphi_\ell}_{L^2(\Gamma_\ell[F])}.
  \end{equation}
  \qed
 \end{enumerate}

\end{lemma} 
%
The properties \rm (i)--(iii) and (vi) of Lemma~\ref{lem:SZconstruct} ensure \textsl{a~priori} convergence of the Scott--Zhang projectors, e.g.,~\cite{Feischl2014}. We note that~\cite{Feischl2014} states the result for $q = 1$, but the proof transfers verbatim to any fixed $q \in \N$.
%
\begin{lemma}[{\textsl{A~priori} convergence of Scott--Zhang projector on $\boldsymbol{\Omega}$ \cite{Feischl2014}}]\label{lem:SZconv}
  For every $v \in H^{1}(\Omega)$, there exists a unique limit $P_{\infty}v \in H^1(\Omega)$ such that
  %\YY_{\infty} \coloneqq \displaystyle{\overline{\bigcup_{\ell \in \N_0} \SS^p(\TT_{\ell})}}$, such that
  %
  \begin{equation}
   \lim_{\ell \rightarrow \infty} \norm{P_{\infty}v - P_{\ell}v}_{H^{1}(\Omega)} = 0 \quad \text{for all } v \in H^{1}(\Omega).
   \qquad \qed
  \end{equation}
  \end{lemma}
%  
Lastly, the choices of $K_{\ell,z}$ in Lemma~\ref{lem:SZconstruct} ensure validity ofthe following statement.
%
\begin{lemma}[Scott--Zhang projector is compatible with boundary strip] \label{lem:SZrest}
 Let $\ell \in \N_0$ and $w \in H^1(\Omega)$. Then, $\mathrm{supp}(w) \subseteq \overline{\omega_\ell}$ yields $\mathrm{supp}(P_\ell w) \subseteq \overline{\omega_\ell}$.
\end{lemma} 
%
\begin{proof}
Given $w \in H^1(\Omega)$ with $\mathrm{supp}(w) \subseteq \overline{\omega_\ell}$ and $z \in \DD_\ell \setminus \omega_\ell$, there holds $w|_{K_{\ell,z}} = 0$ due to the properties \rm{(i)}, \rm{(iii)}, and \rm{(v)} of Lemma~\ref{lem:SZconstruct}. Hence,
%
\begin{equation*}
 P_\ell w = \sum_{z \in \DD_\ell(\omega_\ell)} \Bigl( \int_{K_{\ell,z}} \psi_{\ell,z} w \, \d{x} \Bigr) \zeta_{\ell,z},
\end{equation*}
%
which yields $\mathrm{supp}(P_\ell w) \subseteq \displaystyle{\bigcup_{z \in \DD_\ell(\omega_\ell)} \mathrm{supp}(\zeta_{\ell,z})}$. Since $(\zeta_{\ell,z})_{z \in \DD_\ell \cap \omega_\ell}$ is the nodal basis of the space $\SS^q_{\partial \omega_\ell}(\TT_\ell^\omega)$, we obtain $\mathrm{supp}(\zeta_{\ell,z}) \subseteq \overline{\omega_\ell}$ for all $z \in \DD_\ell(\omega_\ell)$. This implies $\mathrm{supp}(P_\ell w) \subseteq \overline{\omega_\ell}$ and concludes the proof.
\end{proof}

\subsection{Proof of Theorem~\ref{theorem:mainresult}} \label{subsec:proofmainresult}
As in other works~\cite{Morin2008, Siebert2011, Gantner2021} on plain convergence of adaptive finite element methods, one crucial ingredient of our proof is \textsl{a~priori} convergence in Hilbert spaces that already goes back to the seminal work~\cite{bv1984} and results from the validity of the C\'ea lemma in the context of the Lax--Milgram lemma; see also~\cite{Morin2008} for the generalization to uniformly $\inf$-$\sup$-stable problems.

\begin{lemma}[{\textsl{A~priori} convergence in Hilbert spaces~\cite{bv1984}}]\label{lemma:apriori}
Let $H$ be a Hilbert space and $X_\ell \subseteq H$ a sequence of closed subspaces with $X_\ell \subseteq X_{\ell+1}$ for all $\ell \in \N_0$. Let $a(\cdot,\cdot)$ be an elliptic and continuous bilinear form and $F \in H'$. Then, for all $\ell \in \N_0$, the Lax--Milgram yields the existence and uniqueness of $x_\ell \in X_\ell$ with 
\begin{align}
 a(x_\ell, y_\ell) = F(y_\ell)
 \quad \text{for all } y_\ell \in X_\ell.
\end{align}
Moreover, there exists a unique limit $x_\infty \in X_\infty \coloneqq \overline{\bigcup_{\ell \in \N_0} X_\ell} \subseteq H$ such that
\begin{align}
 \lim_{\ell \to \infty} \norm{x_\infty - x_\ell}_{H} = 0.
 \qquad \qed
\end{align}
\end{lemma}

This allows to prove \textsl{a~priori} convergence of the discretized boundary residuals $g_{\ell} = J_{\ell}(g - V\phi_{\ell}^\exact)$ from~\eqref{eq:defwh}.

\begin{corollary}[{\textsl{A~priori} convergence of discretized boundary residuals $\boldsymbol{g_\ell}$}] \label{cor:gellconv}
Recall $g_{\ell}$ from~\eqref{eq:defwh}. 
Then, there exists a limit $g_{\infty} \in H^{1/2}(\Gamma)$ such that 
\begin{equation}
 \lim_{\ell \rightarrow \infty} \norm{g_{\infty} - g_{\ell}}_{H^{1/2}(\Gamma)} = 0,
 %= \lim_{\ell \rightarrow \infty} \norm{g_{\infty} - J_{\ell}(g - V\phi_{\ell}^\exact)}_{H^{1/2}(\Gamma)} = 0.
\end{equation}
where we note that $g_\ell$ is defined on $\partial\omega_\ell \supseteq \Gamma$.
\end{corollary}

\begin{proof}
According to Lemma~\ref{lemma:apriori} applied to $H = H^{-1/2}(\Gamma)$ and $X_\ell = \PP^p(\TT_\ell^\Gamma)$, there exists $\phi_\infty^\star \in H^{-1/2}(\Gamma)$ such that 
\begin{align}\label{eq:apriori:phi}
\norm{\phi_\infty^\exact - \phi_\ell^\exact}_{H^{-1/2}(\Gamma)} \xrightarrow{\ell \to \infty} 0.
\end{align}
%According to~\cite{Morin2008}, nestedness of the spaces $(\PP^0(\TT_\ell^\Gamma))_{\ell \in \N_0}$ and the Céa-Lemma~\eqref{eq:cea} imply a priori convergence $\lim\limits_{\ell \rightarrow \infty} \phi_{\ell}^\exact \eqqcolon \phi_\infty^\exact \in H^{-1/2}(\Gamma)$ and therefore, 
With Lemma~\ref{lem:SZconv}, we define $g_\infty \coloneqq (P_\infty(u^\exact - u_\infty^\exact))|_\Gamma$, where $u_\infty^\exact \coloneqq \widetilde V\phi_\infty^\exact$. With $H^{1/2}(\Gamma)$-stability of $J_\ell$ from~\cite{Feischl2014, Aurada2015}, continuity of $V$, continuity of the trace operator, and~\eqref{eq:apriori:phi}, we obtain
\begin{align*}
 \norm{g_{\infty} - g_{\ell}}_{H^{1/2}(\Gamma)} 
 &\leq 
 \norm{g_{\infty} - J_{\ell}(g - V\phi_\infty^\exact)}_{H^{1/2}(\Gamma)} 
 + \norm{J_{\ell}(g - V\phi_\infty^\exact) - g_{\ell}}_{H^{1/2}(\Gamma)} 
 \\&
 = 
 \norm{((P_{\infty} - P_{\ell})(u^\exact - u_{\infty}^\exact))|_\Gamma}_{H^{1/2}(\Gamma)} 
 + \norm{J_{\ell}V(\phi_\infty^\exact - \phi_{\ell}^\exact)}_{H^{1/2}(\Gamma)} 
 \\&
 \lesssim  
 \norm{(P_{\infty} - P_{\ell})(u^\exact - u_{\infty}^\exact)}_{H^{1}(\Omega)} 
 + \norm{\phi_\infty^\exact - \phi_{\ell}^\exact}_{H^{-1/2}(\Gamma)} 
 \xrightarrow{\ell \to \infty} 0.
\end{align*}
This concludes the proof.
\end{proof}

The proof of Theorem~\ref{theorem:mainresult} requires the following theorem, which is proved in Section~\ref{section:extension} below but stated here to ease reading of the core arguments.

\begin{theorem}[\textsl{A~priori} convergent lifting of discretized boundary residual] \label{thm:extconv}
  Under the assumptions of Section~\ref{section:mainresult}, there exists a sequence $(\widehat{g}_\ell)_{\ell \in \N_0}$ in $H^1(\Omega)$ with $\widehat{g}_{\ell} \in \SS^q(\TT_\ell^\omega)$ and $\widehat{g}_{\ell}|_{\Gamma} = g_\ell$ and $\widehat{g}_{\ell|_{\Gamma_\ell^\complement}} = 0$ for all $\ell \in \N_0$ as well as a limit function $\widehat{g}_{\infty} \in H^1(\Omega)$ such that 
  %
  \begin{equation} \label{eq:extconv}
   \lim_{\ell \rightarrow \infty} \norm{\nabla(\widehat{g}_{\infty} - \widehat{g}_{\ell})}_{L^2(\Omega)} = 0.
  \end{equation}
  %
  Moreover, there exists a constant $\const{\widetilde{C}}{eff} > 0$ depending only on the dimension $d$ and $\kappa$-shape regularity of $\TT_\ell$ such that 
  %
  \begin{equation} \label{eq:exteff}
   \norm{\nabla \widehat{g}_\ell}_{L^2(\Omega)} \leq \const{\widetilde{C}}{eff} \, \norm{\phi^\exact - \phi_\ell^\exact}_{H^{-1/2}(\Omega)} \quad \text{for all } \ell \in \N_0.
  \end{equation}
\end{theorem}
Theorem~\ref{thm:extconv} is a crucial ingredient in the proofs of the following results stating efficiency of the functional error estimates and \textsl{a~priori} convergence of the auxiliary solutions.


\begin{proposition}[Efficiency of functional error estimator]\label{prop:efficiency}
Under the assumptions of Section~\ref{section:mainresult}, there exists a constant $\const{C}{eff} > 0$ depending only on $d$ and $\kappa$-shape regularity of $\TT_\ell$ such that
%
\begin{equation} \label{eq:efficiency}
 \eta_\ell = \norm{\nabla w_\ell^\exact}_{L^2(\Omega)} \leq \const{C}{eff} \, \norm{\phi^\exact - \phi_\ell^\exact}_{H^{-1/2}(\Gamma)}.
\end{equation}
\end{proposition}


\begin{proof}
 Let $(\widehat{g}_\ell)_{\ell \in \N_0}$ be the sequence from Theorem~\ref{thm:extconv}. Since $\widehat{g}_\ell \in \SS^q(\TT_\ell^\omega)$, $\widehat{g}_{\ell}|_{\Gamma} = g_\ell$, and $\widehat{g}_{\ell}|_{\Gamma_\ell^\complement} = 0$, we have that $w_\ell^\exact = w_{\ell,0}^\exact + \widehat{g}_{\ell}$, where $w_{\ell,0}^\exact \in \SS^q_{\partial \omega_\ell}(\TT_\ell^\omega)$ is the unique solution to 
 %
 \begin{equation} \label{eq:dirichletzeroprob}
  \dual{\nabla w_{\ell,0}^\exact}{\nabla v_\ell}_{L^2(\omega_\ell)} 
  = 
  -\dual{\nabla \widehat{g}_{\ell}}{\nabla v_\ell}_{L^2(\omega_\ell)} \quad 
  \text{for all } v_\ell \in \SS^q_{\partial \omega_\ell}(\TT_\ell^\omega).
 \end{equation}
 %
 Choosing $v_\ell = w_{\ell,0}^\exact$ and extending $w_{\ell,0}^\exact$ and $\widehat{g}_\ell$ by zero to the whole domain $\Omega$, we obtain
 %
 \begin{equation*}
  \norm{\nabla w_{\ell,0}^\exact}_{L^2(\Omega)}^2
  =
  \norm{\nabla w_{\ell,0}^\exact}_{L^2(\omega_\ell)}^2 
  = 
  -\dual{\nabla \widehat{g}_{\ell}}{\nabla w_{\ell,0}^\exact}_{L^2(\omega_\ell)} 
  \leq 
  \norm{\nabla \widehat{g}_{\ell}}_{L^2(\Omega)} \norm{\nabla w_{\ell,0}^\exact}_{L^2(\Omega)}.
 \end{equation*}
 %
 Due to Theorem~\ref{thm:extconv}, this implies
 %
 \begin{equation*}
  \begin{split}
   \norm{\nabla w_\ell^\exact}_{L^2(\Omega)} 
   \leq 
   \norm{\nabla w_{\ell,0}^\exact}_{L^2(\Omega)} + \norm{\nabla\widehat{g}_{\ell}}_{L^2(\Omega)} 
   \leq 
   2 \, \norm{\nabla\widehat{g}_{\ell}}_{L^2(\Omega)} 
   \eqreff{eq:exteff}{\leq} 
   2\const{\widetilde{C}}{eff} \, \norm{\phi^\exact - \phi_\ell^\exact}_{H^{-1/2}(\Gamma)}.
  \end{split}
 \end{equation*}
 % 
 This concludes \eqref{eq:efficiency} with $\const{C}{eff} = 2 \const{\widetilde{C}}{eff}$.
\end{proof}



\begin{proposition}[\textsl{A~priori} convergence of functional upper bound]\label{prop:auxconv}
Under the assumptions of Section~\ref{section:mainresult}, there exists $w_\infty^\exact \in H^1(\Omega)$ such that
%
\begin{equation} \label{eq:auxconv}
 \lim_{\ell \to \infty} \norm{\nabla(w_\infty^\exact - w_\ell^\exact)}_{L^2(\Omega)} 
 = 
 0.
\end{equation}
\end{proposition}


\begin{proof}

For $\ell \in \N_0$, let $\widehat{g}_\ell$ be the extension of $g_\ell$ from Theorem~\ref{thm:extconv}. Then, it follows that $w_\ell^\exact = w_{\ell,0}^\exact + \widehat{g}_\ell$, where $w_{\ell,0}^\exact \in \SS^q_{\partial \omega_\ell}(\TT_\ell^\omega)$ solves \eqref{eq:dirichletzeroprob} and satisfies $\norm{\nabla w_{\ell,0}^\exact}_{L^2(\Omega)} \leq \norm{\nabla \widehat{g}_{\ell}}_{L^2(\Omega)}$.

\textbf{Step~1 (Problem formulation on limit space)}. For $\ell \in \N_0$, we define the space
%
\begin{equation*}
 \XX_\ell 
 \coloneqq 
 \bigcup_{m \geq \ell} \set{v_m \in \SS^q_{\Gamma}}(\TT_m) \given \mathrm{supp}(v_m) \subseteq \overline{\omega_\ell} \subseteq H^1_{\partial \omega_\ell}(\omega_\ell) \subseteq H_\Gamma^1(\Omega).
\end{equation*}
%
Since $\XX_\ell$ is a union of nested subspaces, $\XX_\ell\subseteq H_0^1(\Omega)$ is again a subspace. We note that $\XX_\ell \supseteq \XX_{\ell + 1}$ since $\omega_\ell \supseteq \omega_{\ell + 1}$. Hence, we may define the limit space
%
\begin{equation*}
 \XX_\infty 
 \coloneqq 
 \bigcap_{\ell \in \N_0} \overline{\XX_\ell}
 \subseteq
 H^1_{\partial \omega_j}(\omega_j)
 \subseteq
 H_{\Gamma}^1(\Omega)
 \quad \text{for all } j \in \N_0,
\end{equation*}
%
where the closures are taken in $H^1_{\partial \omega_\ell}(\omega_\ell)$. As an intersection of closed subspaces, $\XX_\infty \subseteq H_{\Gamma}^1(\Omega)$ is a closed subspace itself. Hence, there exists a unique $w_{\infty,0}^\exact \in \XX_\infty$ such that
%
\begin{equation} \label{eq:infprob}
 \dual{\nabla w_{\infty,0}^\exact}{\nabla v_\infty}_{L^2(\Omega)} 
 = 
 -\dual{\nabla \widehat{g}_\infty}{\nabla v_\infty}_{L^2(\Omega)} 
 \quad \text{for all } v_\infty \in \XX_\infty.
\end{equation}
%

\textbf{Step~2 (Weak convergence of certain subsequences)}.
Since $(\widehat{g}_{\ell})_{\ell \in \N_0}$ is a convergent sequence in $H^1(\Omega)$, there is a constant $C > 0$ such that $\norm{\nabla w_{\ell,0}^\exact}_{L^2(\Omega)} \leq \norm{\nabla \widehat{g}_{\ell}}_{L^2(\Omega)} \leq C$ for all $\ell \in \N_0$. Let $(w_{\ell_k,0}^\exact)_{k \in N_0}$ be an arbitrary subsequence of $(w_{\ell,0}^\exact)_{\ell \in \N_0}$. Since $(w_{\ell_k,0}^\exact)_{k \in \N_0}$ is also bounded in $H_{\Gamma}^1(\Omega)$, the Banach--Alaoglu theorem yields a further subsequence $(w_{\ell_{k_j},0}^\exact)_{j \in \N_0}$ which converges weakly to some $w_{\infty,0} \in H_{\Gamma}^1(\Omega)$. According to Mazur's theorem, the closed subspace $\XX_\infty$ is also weakly closed and hence contains the limit $w_{\infty,0} \in \XX_\infty$.

\textbf{Step~3 (Proof of \boldsymbol{$w_{\infty,0} = w_{\infty,0}^\exact$})}. We want to show that $w_{\infty,0} = w_{\infty,0}^\exact$. To ease notation, we abbreviate $w_{j,0}^\exact \coloneqq w_{\ell_{k_j},0}^\exact$ for all $j \in \N_0$. Let $\eps > 0$ and $v_\infty \in \XX_\infty$ be arbitrary but fixed. We denote by $R_j \colon H^1_{\partial \omega_j}(\omega_j) \to \SS^q_{\partial \omega_j}(\TT_j^\omega)$ the Ritz projector defined via
%
\begin{equation} \label{eq:orthproj}
 \dual{\nabla (R_j v)}{\nabla v_j}_{L^2(\omega_j)} 
 = 
 \dual{\nabla v}{\nabla v_j}_{L^2(\omega_j)} 
 \quad \text{for all } v \in H^1_{\partial \omega_j}(\omega_j) \text{ and all } v_j \in \SS^q_{\partial \omega_j}(\TT_j^\omega).
\end{equation}
%
Being the orthogonal projection with respect to the $H_{\partial \omega_j}^1(\omega_j)$-inner product, $R_j$ satisfies
%
\begin{equation} \label{eq:bestapprox}
 \norm{\nabla(v - R_j v)}_{L^2(\omega_j)} 
 = 
 \min_{v_j \in \SS^q_{\partial \omega_j}(\TT_j^\omega)} \norm{\nabla(v - v_j)}_{L^2(\omega_j)} 
 \quad \text{for all } v \in H^1_{\partial \omega_j}(\omega_j).
\end{equation}
%
For every $j \in \N_0$, we obtain
%
\begin{equation} \label{eq:probrep}
 \begin{split}
  &\abs{\dual{\nabla(w_{\infty,0} + \widehat{g}_\infty)}{\nabla v_\infty}_{L^2(\omega_\infty)}} \\
  &\qquad \leq 
  \abs{\dual{\nabla(w_{j,0}^\exact + \widehat{g}_j)}{\nabla (R_j v_\infty)}_{L^2(\omega_j)}} 
  + \abs{\dual{\nabla(w_{\infty,0} - w_{j,0}^\exact)}{\nabla v_\infty}_{L^2(\omega_j)}} \\
  &\qquad + \abs{\dual{\nabla \widehat{g}_\infty - \nabla \widehat{g}_j}{\nabla v_\infty}_{L^2(\omega_j)}} 
  + \abs{\dual{\nabla w_{j,0}^\exact}{\nabla (v_\infty - R_j v_\infty)}_{L^2(\omega_j)}} \\
  &\qquad + \abs{\dual{\nabla\widehat{g}_j}{\nabla (v_\infty - R_j v_\infty)}_{L^2(\omega_j)}}.
 \end{split}
\end{equation}
%
The first summand on the right-hand side of~\eqref{eq:probrep} equals zero by~\eqref{eq:dirichletzeroprob}. Since $\widehat{g}_j \to \widehat{g}_\infty$ strongly in $H^1(\Omega)$ and $w_{j,0}^\exact \rightharpoonup w_{\infty,0}$ weakly in $H^1_{\Gamma}(\Omega)$, there exists $j_0 \in N_0$ such that 
%
\begin{equation} \label{eq:strongweakesti}
    \abs{\dual{\nabla(w_{\infty,0} - w_{j,0}^\exact)}{\nabla v_\infty}_{L^2(\Omega)}} 
    + 
    \abs{\dual{\nabla \widehat{g}_\infty - \nabla \widehat{g}_j}{\nabla v_\infty}_{L^2(\Omega)}} 
    \leq
    \eps
    \quad \text{for all } j \geq j_0.
\end{equation}
%
The orthogonality \eqref{eq:orthproj} of the Ritz projector and the fact that $w_{j,0}^\exact \in \SS_{\partial \omega_j}^q(\TT_j^\omega)$ imply $\dual{\nabla w_{j,0}^\exact}{\nabla(v_\infty - R_j v_\infty)}_{L^2(\omega_j)} = 0$. It remains to estimate the last summand of $\eqref{eq:probrep}$. Let $m \geq j \geq j_0$ and consider the Scott--Zhang projector $P_j \colon H^1_{\Gamma}(\Omega) \to \SS_{\Gamma}^q(\TT_{j})$. Due to Lemma~\ref{lem:SZrest} and since $\mathrm{supp}(v_\infty) \subseteq \overline{\omega_j}$, there holds $\mathrm{supp}(P_jv_\infty) \subseteq \overline{\omega_j}$ and hence $P_jv_\infty \in \SS_{\partial \omega_j}^q(\TT_j^\omega)$. We thus obtain
%
\begin{equation} \label{eq:RitzSZ}
 \begin{split}
  \norm{\nabla(v_\infty - R_j v_\infty)}_{L^2(\omega_j)} 
  &= 
  \min_{v_j \in \SS_{\partial \omega_j}^q(\TT_j^\omega)} \norm{\nabla(v_\infty - v_j)}_{L^2(\omega_j)} \\
  &\leq 
  \norm{\nabla(v_\infty - P_m v_\infty)}_{L^2(\omega_j)} \\
  &\qquad+ \min_{v_j \in \SS_{\partial \omega_j}^q(\TT_j^\omega)} \norm{\nabla(P_m v_\infty - v_j)}_{L^2(\omega_j)} \\
  &\leq
  \norm{\nabla(v_\infty - P_m v_\infty)}_{L^2(\Omega)} + \norm{\nabla(P_m - P_j)v_\infty}_{L^2(\Omega)}.
 \end{split}
\end{equation}
%
We first consider the second term of the right-hand side of~\eqref{eq:RitzSZ}. By Lemma~\ref{lem:SZconv}, the sequence $(P_m v_\infty)_{m \in \N_0}$ is a Cauchy-sequence. This yields the existence of $j_1 \in \N_0$ such that 
%
\begin{equation*}
 \norm{\nabla(P_m - P_j)v_\infty}_{L^2(\Omega)} 
\leq
 \eps
 \quad \text{for all } m \geq j \geq j_1.
\end{equation*}
%
For the first summand on the right-hand side of~\eqref{eq:RitzSZ}, we again refer to Lemma~\ref{lem:SZrest} and note that because of $\mathrm{supp}(v_\infty) \subseteq \overline{\omega_m}$ for all $m \in \N_0$, it follows that 
%
\begin{equation*}
  \mathrm{supp}(P_mv_\infty) \subseteq \overline{\omega_m} \subset \overline{\omega_j}.
\end{equation*}
%
Hence, Lemma~\ref{lem:SZ} yields
%
\begin{equation*}
 \norm{\nabla(v_\infty - P_m v_\infty)}_{L^2(\Omega)} 
 =
 \norm{\nabla(v_\infty - P_m v_\infty)}_{L^2(\omega_j)}
 \leq 
 \const{C}{stab}\min_{\substack{v_m^j \in \SS_0^q(\TT_m) \\ \mathrm{supp}(v_m^j) \subseteq \omega_j}} \norm{\nabla(v_\infty - v_m^j)}_{L^2(\omega_j)}.
\end{equation*}
%
For given $j \geq j_1$, since $v_\infty \in \XX_\infty \subset \overline{\XX_m}$, there exists $m_j \geq m$ and $v_{m_j}^j \in \SS_{\Gamma}^q(\TT_{m_j})$ with $\mathrm{supp}(v_{m_j}^j) \subseteq \overline{\omega_j}$ such that
%
\begin{equation*}
 \norm{\nabla(v_\infty - v_{m_j}^j)}_{L^2(\omega_j)} 
 =
 \norm{\nabla(v_\infty - v_{m_j}^j)}_{L^2(\Omega)}
 \leq 
 \eps.
\end{equation*}
%
This yields
%
\begin{equation*}
 \norm{\nabla(v_\infty - R_jv_\infty)}_{L^2(\omega_j)} \leq (1 + \const{C}{stab})\eps \quad \text{for all } j \geq j_1.
\end{equation*}
%
In conclusion, we have that 
%
\begin{equation*}
 \abs{\dual{\nabla \widehat{g}_{j}}{\nabla(v_\infty - R_mv_\infty)}_{L^2(\omega_{j})}} 
 \leq 
 (1 + \const{C}{stab})\eps \sup_{\ell \in \N_0} \norm{\nabla \widehat{g}_{\ell}}_{L^2(\Omega)} 
 \quad \text{for all } j \geq j_1.
\end{equation*}
%
Together with~\eqref{eq:probrep}--\eqref{eq:strongweakesti} and the fact that $\norm{\nabla \widehat{g}_{\ell}}_{L^2(\Omega)} \lesssim 1$, this yields
%
\begin{equation*}
 \abs{\dual{\nabla(w_{\infty,0}^\exact + \widehat{g}_\infty)}{\nabla v_\infty}_{L^2(\omega_\infty)}} 
 \lesssim 
 \eps.
\end{equation*} 
%
Since $\eps > 0$ and $v_\infty \in \XX_\infty$ were arbitrary, we conclude that the right-hand side of~\eqref{eq:probrep} vanishes and hence
%
\begin{equation*}
 \dual{\nabla w_{\infty,0}}{\nabla v_\infty}_{L^2(\Omega)} 
 = 
 -\dual{\nabla \widehat{g}_{\infty}}{\nabla v_\infty}_{L^2(\Omega)}
 \quad \text{for all } v_\infty \in \XX_\infty.
\end{equation*}
%
Since~\eqref{eq:infprob} has a unique solution, we conclude $w_{\infty,0} = w_{\infty,0}^\exact$.


\textbf{Step~4 (Weak convergence of full sequence)}. Step~2 and~3 prove that any subsequence $(w_{\ell_k,0}^\exact)_{k \in \N_0}$ of $(w_{\ell,0}^{\exact})_{\ell \in \N_0}$ admits a weakly convergent subsequence $(w_{\ell_{k_j},0}^\exact)_{j \in \N_0}$ which converges to the unique limit $w_{\infty,0}^\exact$. By elementary calculus, it follows that indeed the full sequence $(w_{\ell,0}^\exact)_{\ell \in \N_0}$ satisfies weak convergence $w_{\ell,0}^\exact \rightharpoonup w_{\infty,0}^\exact$ in $H^1_{\Gamma}(\Omega)$.


\textbf{Step~5 (Strong convergence of full sequence)}. Since $\nabla \widehat{g}_{\ell} \to \nabla \widehat{g}_{\infty}$ in $L^2(\Omega)$ and $\nabla w_{\ell,0}^\exact \rightharpoonup \nabla w_{\infty,0}^\exact$ in $L^2(\Omega)$, it follows that
%
\begin{equation*}
 \begin{split}
 \norm{\nabla w_{\ell,0}^\exact}_{L^2(\Omega)}^2 
 &\eqreff{eq:dirichletzeroprob}{=} 
 -\dual{\nabla \widehat{g}_{\ell}}{\nabla w_{\ell,0}^\exact}_{L^2(\omega_\ell)}
 \xrightarrow{\ell \to \infty} 
 -\dual{\nabla \widehat{g}_\infty}{\nabla w_{\infty,0}^\exact}_{L^2(\Omega)} 
 \eqreff{eq:infprob}{=} 
 \norm{\nabla w_{\infty,0}^\exact}_{L^2(\Omega)}^2.
\end{split}
\end{equation*}
%
Recall that $\norm{\nabla(\cdot)}_{L^2(\Omega)}$ is an equivalent norm on $H_{\Gamma}^1(\Omega)$. Together with weak convergence $w_{\ell,0}^\exact \rightharpoonup w_{\infty,0}^\exact$ in $H_{\Gamma}^1(\Omega)$, convergence of the norm suffices for strong convergence
%
\begin{equation*}
 \lim_{\ell \to \infty} \norm{\nabla (w_{\infty,0}^\exact - w_{\ell,0}^\exact)}_{L^2(\Omega)} = 0.
\end{equation*}
%
In particular, Theorem~\ref{thm:extconv} yields strong convergence
%
\begin{equation*}
 \nabla w_{\ell}^\exact 
 = \nabla w_{\ell,0}^\exact + \nabla \widehat{g}_{\ell} 
 \xrightarrow{\ell \to \infty} 
 \nabla w_{\infty,0}^\exact + \nabla \widehat{g}_{\infty} 
 \eqqcolon \nabla w_{\infty}^\exact
 \quad \text{in } L^2(\Omega).
\end{equation*}
%
This concludes the proof.
\end{proof}

Recall the notation and assumptions from Section~\ref{section:mainresult}.
As in~\cite{Morin2008, Siebert2011, Gantner2021}, we define the set $\TT_\infty$ of all elements that remain unrefined after finitely many steps of Algorithm~\ref{algo:adap}, i.e.,
\begin{equation} \label{eq:Tinfty}
 \TT_{\infty} \coloneqq \bigcup_{\ell' \in \N_0} \bigcap_{\ell \geq \ell'} \TT_{\ell}.
\end{equation}
%and abbreviate $\TT_{\ell,\infty} \coloneqq \TT_{\ell} \cap \TT_{\infty}$. \\ \\
%
%We begin by collecting useful results. 
With Corollary~\ref{cor:gellconv} and Proposition~\ref{prop:auxconv}, we can adapt arguments of~\cite{Gantner2021} to derive the first convergence statement of Theorem~\ref{theorem:mainresult}, i.e., $\osc_\ell \to 0$ in~\eqref{eq:theorem:mainresult}.

\begin{proposition} \label{thm:eta2conv}
For any $\ell' \in \N_0$, Algorithm~\ref{algo:adap} guarantees
\begin{align} \label{eq:oscconv}
 \lim_{\ell' \leq \ell \rightarrow \infty} \eta_{\ell}(\TT_{\ell'} \cap \TT_\infty) = 0
 \quad \text{as well as} \quad
 \lim_{\ell \rightarrow \infty} \osc_{\ell} = 0.
\end{align}
\end{proposition}
%
\bigskip
%
\begin{proof}
The proof is split into six steps.

\textbf{Step~1 (Stability of $\boldsymbol{\osc_\ell}$).}
%
We show that, for all $k, \ell \in \N_0$ with $k > \ell$, 
\begin{subequations}\label{eq:stability:osc}
\begin{equation}
 \osc_{k}(\TT_k \cap \TT_{\ell}) 
 \leq 
 \osc_{\ell}(\TT_k \cap \TT_{\ell}) + a_{\ell,k},
\end{equation}
where 
\begin{equation}
 a_{\ell,k} 
 \coloneqq 
 \norm{h_k^{1/2} \nabla_\Gamma \bigl( (1-J_{\ell})(g - V\phi_{\ell}^\exact) - (1-J_k)(g-V\phi_k^\exact) \bigr)}_{L^2(\Gamma)}
 \xrightarrow{k,\ell \to \infty} 0.
\end{equation}
\end{subequations}
Let $\ell,k \in \N_0$ with $k > \ell$.
The triangle inequality proves that
\begin{align*}
 \osc_{k}(\TT_k \cap \TT_{\ell}) 
 &= 
 \Bigl( \sum_{T \in \TT_k \cap \TT_{\ell}} \norm{h_k^{1/2} \nabla_\Gamma (1 - J_k)(g - V \phi_k^\exact)}_{L^2(\partial T \cap \Gamma)}^2\Bigr)^{1/2} 
 \\&
 \leq 
 \Bigl( \sum_{T \in \TT_k \cap \TT_{\ell}} \norm{h_k^{1/2} \nabla_\Gamma (1 - J_\ell)(g - V \phi_\ell^\exact)}_{L^2(\partial T \cap \Gamma)}^2 \Bigr)^{1/2} 
 \\& \quad
 + \Bigl( \sum_{T \in \TT_k \cap \TT_{\ell}} \norm{h_k^{1/2} \nabla_\Gamma \bigl( (1 - J_\ell)(g - V \phi_\ell^\exact) - (1 - J_k)(g - V \phi_k^\exact)}_{L^2(\partial T \cap \Gamma)}^2 \Bigr)^{1/2} 
 \\&
 \leq 
 \osc_{\ell}(\TT_k \cap \TT_{\ell}) + a_{\ell,k}.
\end{align*}
We recall the inverse estimates
\begin{align}\label{eq:invest:1/2}
 \norm{h_k^{1/2} \nabla_\Gamma v_k}_{L^2(\Gamma)}
 \lesssim \norm{v_k}_{H^{1/2}(\Gamma)}
 \quad \text{for all } v_k \in \SS^q(\TT_k^\Gamma)
\end{align}
as well as 
\begin{align}\label{eq:invest:V}
 \norm{h_k^{1/2} \nabla_\Gamma V \psi_k}_{L^2(\Gamma)}
 \lesssim \norm{\psi_k}_{H^{-1/2}(\Gamma)}
 \quad \text{for all } \psi_k \in \PP^p(\TT_k^\Gamma),
\end{align}
where the hidden constants depend only on the polynomial degrees $p \in \N_0$, $q \in \N$, and $\kappa$-shape regularity of $\TT_k^\Gamma$; see~\cite[Proposition~5]{Aurada2015} and~\cite[Theorem~3.1]{Aurada2015a}, respectively.
With this and nestedness of the discrete spaces, we see that
\begin{align*}
 a_{\ell,k}
 &\le 
 \norm{h_k^{1/2} \nabla_\Gamma (J_{\ell}-J_k)g }_{L^2(\Gamma)}
 + 
 \norm{h_k^{1/2} \nabla_\Gamma ( V\phi_{\ell}^\exact - V\phi_k^\exact )}_{L^2(\Gamma)}
 \\& \quad
 + 
 \norm{h_k^{1/2} \nabla_\Gamma ( J_{\ell} V\phi_{\ell}^\exact - J_k V\phi_k^\exact )}_{L^2(\Gamma)}
 \\&
 \lesssim 
 \norm{(J_{\ell}-J_k)g }_{H^{1/2}(\Gamma)}
 + 
 \norm{\phi_{\ell}^\exact - \phi_k^\exact}_{H^{-1/2}(\Gamma)}
 + 
 \norm{J_{\ell} V\phi_{\ell}^\exact - J_k V\phi_k^\exact}_{H^{1/2}(\Gamma)}.
\end{align*}
Lemma~\ref{lem:SZconv} and continuity of the trace operator yield
\begin{equation*}
 \norm{(J_\ell-J_{k})g}_{H^{1/2}(\Gamma)} 
 \lesssim 
 \norm{(P_\ell - P_{k})u^\exact}_{H^1(\Omega)} 
 \xrightarrow{k, \ell \to \infty} 0.
\end{equation*}
Moreover, the $H^{1/2}(\Gamma)$-stability of $J_{\ell}$, Lemma~\ref{lem:SZconv} for $u_\infty = \widetilde V\phi_\infty^\exact$, and \textsl{a~priori} convergence~\eqref{eq:apriori:phi} together with continuity of $V$ yield
\begin{align*}
 &\norm{J_{\ell} V\phi_{\ell}^\exact - J_{\infty} V\phi_\infty^\exact}_{H^{1/2}(\Gamma)} 
 \leq 
 \norm{J_{\ell} V\phi_{\ell}^\exact - J_{\ell} V\phi_\infty^\exact}_{H^{1/2}(\Gamma)} 
 + 
 \norm{J_{\ell} V\phi_\infty^\exact - J_{\infty} V\phi_\infty^\exact}_{H^{1/2}(\Gamma)} 
 \\& \qquad
 \lesssim 
 \norm{V\phi_{\ell}^\exact - V\phi_\infty^\exact}_{H^{1/2}(\Gamma)}  
 + \norm{P_{\ell} u_{\infty} - P_{\infty} u_{\infty}}_{H^{1}(\Omega)} 
  \xrightarrow{\ell \to \infty} 0.
\end{align*}
Altogether, we thus conclude that $a_{\ell,k} \to 0$ as $k,\ell \to \infty$.

\textbf{Step~2 (Reduction of $\boldsymbol{\osc_\ell}$).}
We show that, for all $k, \ell \in \N_0$ with $k > \ell$,
\begin{align}\label{eq:reduction:osc}
 \osc_{k}(\TT_k \setminus  \TT_{\ell})
 \le 
 \const{\rho}{red} \, \osc_{\ell}(\TT_{\ell} \setminus \TT_k) + a_{\ell,k}
 \quad \text{with} \quad
 \const{\rho}{red} \coloneqq 2^{-1/(2d)}.
\end{align}
To this end, we note that $\bigcup (\TT_k \setminus \TT_{\ell}) = \bigcup (\TT_{\ell} \setminus \TT_k)$ and that for $T \in \TT_k \setminus \TT_{\ell}$ and $T' \in \TT_{\ell} \setminus \TT_k$ with $T \subset T'$, there holds $h_T \leq 2^{-1/d} h_{T'}$ due to bisection and $h_T = |T|^{1/d}$.
Arguing as for stability~\eqref{eq:stability:osc}, we obtain
\begin{align*}
 \osc_{k}(\TT_k \setminus  \TT_{\ell}) 
 &= 
 \Bigl(\sum_{T \in \TT_{k} \setminus \TT_{\ell}} h_T \norm{\nabla_\Gamma (1 - J_k)(g - V \phi_k^\exact)}_{L^2(\partial T \cap \Gamma)}^2\Bigr)^{1/2} 
 \\&
 = 
 \Bigl(\sum_{T' \in \TT_{\ell} \setminus \TT_k} \sum_{\substack{T \in \TT_k \setminus \TT_{\ell} \\ T \subset T'}} h_T \norm{\nabla_\Gamma (1 - J_k)(g - V \phi_k^\exact)}_{L^2(\partial T \cap \Gamma)}^2\Bigr)^{1/2}
 \\&
 \leq 
 \Bigl(\sum_{T' \in \TT_{\ell} \setminus \TT_k} \sum_{\substack{T \in \TT_k \setminus \TT_{\ell} \\ T \subset T'}} h_T \norm{\nabla_\Gamma (1 - J_{\ell})(g - V \phi_{\ell}^\exact)}_{L^2(\partial T \cap \Gamma)}^2 
 \Bigr)^{1/2} + a_{\ell,k}
 \\&
 \leq 
 2^{-1/(2d)} \Bigl(\sum_{T' \in \TT_{\ell} \setminus \TT_k} h_{T'} \sum_{\substack{T \in \TT_k \setminus \TT_{\ell} \\ T \subset T'}}  \norm{\nabla_\Gamma (1 - J_{\ell})(g - V \phi_{\ell}^\exact)}_{L^2(\partial T \cap \Gamma)}^2 \Bigr)^{1/2} + a_{\ell,k} 
 \\&
 = 2^{-1/(2d)} \, \osc_{\ell}(\TT_{\ell} \setminus \TT_k) + a_{\ell,k}.
\end{align*}

\textbf{Step~3 (Convergence $\boldsymbol{\osc_{\ell_k}(\MM_{\ell_k}) \to 0}$ along a subsequence).}
With reduction~\eqref{eq:reduction:osc}, the arguments from~\cite[Proof of Theorem~3.1, step 1--2]{Gantner2021} prove that there exists a subsequence $(\osc_{\ell_k})_{k \in \N_0}$ such that
\begin{equation} \label{eq:eta2fineconv}
 0 
 \le 
 \osc_{\ell_k}(\MM_{\ell_k}) 
 \le 
 \osc_{\ell_k}(\TT_{\ell_k} \backslash \TT_{\ell_{k+1}}) 
 \xrightarrow{k \to \infty} 0.
\end{equation}

\textbf{Step~4 (Convergence $\boldsymbol{\max_{T \in \MM_{\ell}} \eta_{\ell}(T) \to 0}$ along the full sequence).}
For $\ell \in \N_0$, let $T_{\ell} \in \MM_{\ell}$ such that $\eta_{\ell}(T_{\ell}) = \max_{T \in \MM_{\ell}} \eta_{\ell}(T)$.
Since $\MM_{\ell} \subseteq \TT_{\ell} \setminus \TT_{\infty}$, \cite[Corollary~4.1]{Morin2008} proves
\begin{equation*}
 |T_{\ell}| 
 = 
 \norm{h_{\ell}^d}_{L^{\infty}(T_{\ell})} 
 \leq 
 \norm{h_{\ell}}_{L^{\infty}(\bigcup (\TT_{\ell} \setminus \TT_{\infty}))}^d \stackrel{\ell \rightarrow \infty}{\longrightarrow} 0.
\end{equation*}
By Proposition~\ref{prop:auxconv}, there exists $w_\infty^\exact \in H^1(\Omega)$ such that $\norm{w_\infty^\exact - w_\ell^\exact}_{H^1(\Omega)} \xrightarrow{\ell \to \infty} 0$. Hence, absolute continuity of the $H^1$-seminorm with respect to the measure $|\cdot|$ concludes
\begin{equation} \label{eq:eta1fineconv}
 \max_{T \in \MM_{\ell}}  \eta_{\ell}(T)^2 
 =
 \eta_{\ell}(T_{\ell})^2 
 = 
 \norm{\nabla w_\ell^\exact}_{L^2(T_{\ell})}^2 
 \lesssim 
 \norm{\nabla w_\infty^\exact}_{L^2(T_\ell)}^2 + \norm{\nabla(w_\infty^\exact - w_\ell^\exact)}_{L^2(\Omega)}^2
 \xrightarrow{\ell \to \infty} 0.
\end{equation}

\textbf{Step~5 (Convergence $\boldsymbol{\osc_\ell \to 0}$ along the full sequence).}
From Step~3--4, we obtain 
\begin{equation*}
 \max_{T \in \MM_{\ell_k}} \big[ \eta_{\ell_k}(T)^2 + \osc_{\ell_k}(T)^2 \big]
 \le \max_{T \in \MM_{\ell_k}} \eta_{\ell_k}(T_{\ell_k})^2 + \osc_{\ell_k}(\MM_{\ell_k})^2
 \xrightarrow{k \to \infty} 0.
\end{equation*}
For all $\ell' \leq \ell_k$ and every $T \in \TT_{\ell'} \cap \TT_{\infty} \subseteq \TT_{\ell_k} \setminus \MM_{\ell_k}$, the marking strategy~\eqref{eq:marking} yields that
\begin{equation} \label{eq:2mark}
 \begin{split}
 \osc_{\ell_k}(T) ^2
 &\leq 
 \max_{T \in \TT_{\ell_k} \setminus \MM_{\ell_k}} \big[ \eta_{\ell_k}(T)^2 + \osc_{\ell_k}(T)^2 \big] 
 \\
 &\eqreff{eq:marking}\leq 
 M\Bigl(\max_{T \in \MM_{\ell_k}} \big[ \eta_{\ell_k}(T)^2 + \osc_{\ell_k}(T)^2 \big] \Bigr) 
 \stackrel{k \rightarrow \infty}{\longrightarrow} 0.
 \end{split}
\end{equation}
Since $\TT_{\ell'} \cap \TT_\infty$ is finite, this proves
\begin{equation} \label{eq:eta2nfineconv}
 \lim_{k \rightarrow \infty} \osc_{\ell_k}(\TT_{\ell'} \cap \TT_{\infty}) = 0 
 \qquad \text{for all } \ell' \in \N_0,
\end{equation}	
which verifies the claim of~\cite[Proof of Theorem~3.1, step 3]{Gantner2021} in the present setting.
With stability~\eqref{eq:stability:osc} and reduction~\eqref{eq:reduction:osc}, the arguments from~\cite[Proof of Theorem~3.1, step 4--5]{Gantner2021} conclude that indeed
\begin{equation} \label{eq:eta2conv}
 \lim_{\ell \rightarrow \infty} \osc_{\ell} = 0.
\end{equation}

\textbf{Step~6 (Convergence $\boldsymbol{\eta_\ell(\TT_{\ell'} \cap \TT_\infty) \to 0}$ along the full sequence).}
Let $\ell, \ell' \in \N_0$ with $\ell' \le \ell$.
Since marked elements are refined, it holds that $\TT_{\ell'} \cap \TT_{\infty} \subseteq \TT_{\ell} \setminus \MM_{\ell}$.
For all $T \in \TT_{\ell'} \cap \TT_{\infty}$, the convergences~\eqref{eq:eta1fineconv} and~\eqref{eq:eta2conv} prove
\begin{align*}
 0 \le \max_{T \in \MM_{\ell}} \big[ \eta_{\ell}(T)^2 + \osc_{\ell}(T)^2 \big]
 \le \max_{T \in \MM_{\ell}} \eta_{\ell}(T)^2 + \osc_{\ell}^2
 \xrightarrow{\ell \to \infty} 0.
\end{align*}
Thus, the marking strategy~\eqref{eq:marking} yields
\begin{equation*}
 \eta_{\ell}(T)^2 
 \leq 
 \max_{T \in \TT_{\ell} \setminus \MM_{\ell}} \big[ \eta_{\ell}(T)^2 + \osc_{\ell}(T)^2 \big]
 \eqreff{eq:marking}\leq
  M\Big(\max_{T \in \MM_{\ell}} \big[ \eta_{\ell}(T)^2 + \osc_{\ell}(T)^2 \big] \Big)
  \stackrel{\ell \rightarrow \infty}{\longrightarrow} 0.
\end{equation*}
Since $\TT_{\ell'} \cap \TT_\infty$ is finite, this gives
\begin{equation*}
 \lim_{\ell' \leq \ell \rightarrow \infty} \eta_{\ell}(\TT_{\ell'} \cap \TT_\infty) = 0
\end{equation*}
and concludes the proof.
\end{proof}

\begin{lemma}[Strong reliability] \label{lem:strongrel}
For all $\psi \in L^2(\Gamma)$ and $\ell \in \N_0$, there holds
\begin{equation}\label{eq:lem:strongrel}
 |\dual{V\phi^\exact - V\phi_{\ell}^\exact}{\psi}_{H^{1/2}(\Gamma) \times H^{-1/2}(\Gamma)}| 
 \le 
 \const{C}{rel}
 \Big( \osc_\ell \, \norm{\psi}_{L^2(\Gamma)} +
 \sum_{T \in \TT_{\ell}} \eta_{\ell}(T) \norm{\psi}_{L^2(\partial T \cap \Gamma)} \Big).
\end{equation}
The constant $\const{C}{rel} > 0$ depends only on $d$, $\Gamma$, and $\kappa$-shape regularity of $\TT_\ell$.
\end{lemma} 

\begin{proof}
The proof is split into three steps.

\textbf{Step~1:} 
Let $Q_\ell^\Gamma \colon L^2(\Gamma) \to \PP^0(\TT_\ell^\Gamma)$ and $Q_\ell^\Omega \colon L^2(\Omega) \to \PP^0(\TT_\ell)$ be the integral mean operators, i.e., the $L^2$-orthogonal projections onto the piecewise constants. For $F \in \TT_\ell^\Gamma$ and $T_F \in \TT_\ell$ with $F \subset \partial T$, the best approximation property of $Q_\ell^\Gamma$ with respect to $\norm{\cdot}_{L^2(F)}$ yields
\begin{align*}
 \norm{(1-Q_\ell^\Gamma) J_{\ell}(g - V\phi_{\ell}^\exact)}_{L^2(F)}
 = \norm{(1-Q_\ell^\Gamma) w_\ell^\exact}_{L^2(F)}
 \le \norm{(1-Q_\ell^\Omega) w_\ell^\exact}_{L^2(F)}.
\end{align*}
Moreover, the trace inequality and a Poincar\'e inequality prove
\begin{align*}
 \begin{split}
 \norm{(1-Q_\ell^\Omega) w_\ell^\exact}_{L^2(F)} 
% \le
% \norm{(1-Q_\ell^\Omega) w_\ell^\exact}_{L^2(\partial T_F)} 
% \nonumber
% \\& \quad
 &\lesssim 
 h_{T_F}^{-1} \norm{(1-Q_\ell^\Omega) w_\ell^\exact}_{L^2(T_F)} + \norm{\nabla (1-Q_\ell^\Omega) w_\ell^\exact}_{L^2(T_F)}
 \\&
 \lesssim 
 \norm{\nabla w_\ell^\exact}_{L^2(T_F)}
 =
 \eta_\ell(T_F),
 \end{split}
\end{align*}%
where the hidden constants depend only on $d$ and $\kappa$-shape regularity of $\TT_\ell$.

\textbf{Step~2:} With $Q_\ell^\Gamma$ from Step~1 and the local $L^2$-approximation property of the projector $J_{\ell}$, it holds that
\begin{align*}% \label{eq:rholegeta2}
 \begin{split}
 \norm{(1-Q_\ell^\Gamma)(1-J_{\ell})(g - V\phi_{\ell}^\exact)}_{L^2(\Gamma)}
 &\le 
 \norm{(1-J_{\ell})(g - V\phi_{\ell}^\exact)}_{L^2(\Gamma)}
 \\&
 \lesssim 
 \norm{h_{\ell} \nabla_\Gamma (1-J_{\ell})(g-V\phi_{\ell}^\exact)}_{L^2(\Gamma)}
 \lesssim \osc_{\ell};
 \end{split}
\end{align*}
see, e.g.,~\cite[Lemma~3]{Aurada2015}. The hidden constant depends only on $p$, $\Gamma$, and $\kappa$-shape regularity of $\TT_\ell^\Gamma$.

\textbf{Step~3:}
Let $\psi \in L^2(\Gamma)$. Since the dual pairing in $H^{1/2}(\Gamma) \times H^{-1/2}(\Gamma)$ extends the $L^2(\Gamma)$-inner product and $\eta_{\ell}(T) = 0$ for all $T \in \TT_{\ell} \setminus \TT_{\ell}^{\omega}$, the Galerkin orthogonality and the symmetry of the $L^2$-orthogonal projection prove
\begin{align*}
 &\dual{V\phi^\exact - V\phi_{\ell}^\exact}{\psi}_{H^{1/2}(\Gamma) \times H^{-1/2}(\Gamma)} 
 = \dual{V\phi^\exact - V\phi_{\ell}^\exact}{(1-Q_\ell^\Gamma)\psi}_{H^{1/2}(\Gamma) \times H^{-1/2}(\Gamma)}
 \\& \quad 
 = \dual{(1-Q_\ell^\Gamma)(g - V\phi_{\ell}^\exact)}{\psi}_{H^{1/2}(\Gamma) \times H^{-1/2}(\Gamma)}
 % = 
 % \dual{V\phi^\exact - V\phi_{\ell}^\exact}{\psi}_{L^2(\Gamma)} \\
% = 
% \sum_{F \in \TT_\ell^\Gamma} \dual{g - V\phi_{\ell}^\exact}{\psi}_{L^2(F)} 
% \\& \quad 
% = 
% \sum_{F \in \TT_\ell^\Gamma} \big( \dual{J_{\ell}(g - V\phi_{\ell}^\exact)}{\psi}_{L^2(F)} + \dual{(1-J_{\ell})(g - V\phi_{\ell}^\exact)}{\psi}_{L^2(F)} \big)
 \\& \quad 
 \leq 
 \sum_{F \in \TT_\ell^\Gamma} \big( \norm{(1-Q_\ell^\Gamma)J_{\ell}(g - V\phi_{\ell}^\exact)}_{L^2(F)} + \norm{(1-Q_\ell^\Gamma)(1-J_{\ell})(g - V\phi_{\ell}^\exact)}_{L^2(F)} \big) \norm{\psi}_{L^2(F)} 
% \\& \quad  
% \leq 
% \sum_{F \in \TT_\ell^\Gamma} \big( \norm{w_{\ell}|_{F}}_{L^2(F)} + \mu_{2,\ell}(T_F) \big) \norm{\psi}_{L^2(F)} 
% \\& \quad  
 %= \sum_{F \in \TT_\ell^\Gamma} \big( \norm{w_\ell^\exact}_{L^2(F)} + \norm{(1-J_{\ell})(g - V\phi_{\ell}^\exact)}_{L^2(F)} \big) \norm{\psi}_{L^2(F)} 
 \\& \quad  
 \le \Big( \sum_{F \in \TT_\ell^\Gamma} \norm{(1-Q_\ell^\Gamma)w_\ell^\exact}_{L^2(F)} \norm{\psi}_{L^2(F)} \Big)
 + \norm{(1-Q_\ell^\Gamma)(1-J_{\ell})(g - V\phi_{\ell}^\exact)}_{L^2(\Gamma)}  \norm{\psi}_{L^2(\Gamma)} 
 \\& \quad  
 \lesssim \Big( \sum_{F \in \TT_\ell^\Gamma} \eta_{\ell}(T_F) \norm{\psi}_{L^2(F)} \Big) + \osc_\ell \, \norm{\psi}_{L^2(\Gamma)}
 \le 
 \Big( \sum_{T \in \TT_\ell} \eta_{\ell}(T) \norm{\psi}_{L^2(T \cap \Gamma)} \Big) + \osc_\ell \, \norm{\psi}_{L^2(\Gamma)}.
% \\& \quad  
% \leq \sqrt{2} \sum_{T \in \TT_{\ell}} \mu_{\ell}(T) \, \norm{\psi}_{L^2(\partial T \cap \Gamma)} 
\end{align*}
This concludes the proof.
\end{proof}

By means of the foregoing lemma, we are able to adapt some arguments of~\cite{Siebert2011} to the present setting in order to prove $\norm{\phi^\exact - \phi_\ell^\exact}_{H^{-1/2}(\Gamma)} \to 0$.

\begin{proposition}\label{prop:convergence:norm}
Algorithm~\ref{algo:adap} guarantees that
\begin{equation}\label{eq:prop:convergence:norm}
 \lim_{\ell \rightarrow \infty} \norm{\phi^\exact - \phi_{\ell}^\exact}_{H^{-1/2}(\Gamma)} = 0.
\end{equation}
\end{proposition} 

\begin{proof}
The proof is split into four steps.

\textbf{Step~1.} 
Since $\phi_{\ell}^\exact$ converges strongly in $H^{-1/2}(\Gamma)$ to $\phi_\infty^\exact$, it remains to show that $\phi_\infty^\exact = \phi^\exact$. To this end, it suffices to show weak convergence $\phi_\ell^\exact \rightharpoonup \phi^\exact$ in $H^{-1/2}(\Gamma)$. Since $V$ is an isomorphism and $H^1(\Gamma)$ is densely contained in $H^{-1/2}(\Gamma)$, this is equivalent to 
\begin{equation*}
% \dual{V\phi^\exact - V\phi_\infty^\exact}{\psi}_{H^{1/2}(\Gamma) \times H^{-1/2}(\Gamma)} 
% = 
% 0 
 \dual{V\phi^\exact - V\phi_{\ell}^\exact}{\psi}_{H^{1/2}(\Gamma) \times H^{-1/2}(\Gamma)} \xrightarrow{\ell \to \infty} 0
 \qquad \text{for all } \psi \in H^1(\Gamma).
\end{equation*}
Let $\psi \in H^1(\Gamma)$.
%Since 
%\begin{equation*}
% \lim_{\ell \rightarrow \infty} \dual{V\phi_\infty^\exact - V\phi_{\ell}^\exact}{\psi}_{H^{1/2}(\Gamma) \times H^{-1/2}%(\Gamma)} = 0,
%\end{equation*}
%it remains to prove that
%\begin{equation*}
% \lim_{\ell \rightarrow \infty} \dual{V\phi^\exact - V\phi_{\ell}^\exact}{\psi}_{H^{1/2}(\Gamma) \times H^{-1/2}(\Gamma)} = 0.
%\end{equation*}
Let $Q_{\ell}^\Gamma \colon L^2(\Gamma) \rightarrow \PP^0(\TT_\ell^\Gamma)$ be the integral mean operator.
Then, Galerkin orthogonality, Lemma~\ref{lem:strongrel}, and a Poincar\'e-type inequality prove that
\begin{align}\label{eq:step0}
 \begin{split}
 &|\dual{V\phi^\exact - V\phi_{\ell}^\exact}{\psi}_{H^{1/2}(\Gamma) \times H^{-1/2}(\Gamma)}| 
 = |\dual{V\phi^\exact - V\phi_{\ell}^\exact}{\psi-Q_{\ell}^\Gamma\psi}_{H^{1/2}(\Gamma) \times H^{-1/2}(\Gamma)}| 
 \\& \quad
 \eqreff{eq:lem:strongrel}\lesssim 
 \osc_\ell \, \norm{\psi-Q_{\ell}^\Gamma\psi}_{L^2(\Gamma)} 
 + 
 \sum_{T \in \TT_\ell} \eta_{\ell}(T) \, \norm{\psi-Q_{\ell}^\Gamma\psi}_{L^2(\partial T \cap \Gamma)} 
 \\& \quad
 \lesssim
 \osc_\ell \, \norm{\psi}_{L^2(\Gamma)} 
 +
 \sum_{T \in \TT_\ell} h_T \, \eta_{\ell}(T) \, \norm{\nabla_\Gamma \psi}_{L^2(\partial T \cap \Gamma)}.
% \\& \quad
% \lesssim
% \osc_\ell \, \norm{\psi}_{L^2(\Gamma)} 
% +
% \sum_{T \in \TT_\ell} \big( \norm{w_\ell^\exact}_{L^2(T)} + h_T \norm{\nabla w_\ell^\exact}_{L^2(T)} \big) \, \norm{\nabla_\Gamma \psi}_{L^2(\partial T \cap \Gamma)}.
 \end{split}
\end{align}
Recall that $\osc_\ell \to 0$ as $\ell \to \infty$ according to Proposition~\ref{thm:eta2conv}. It therefore remains to prove that also the sum converges to zero as $\ell \to \infty$. To this end, let $\ell' \in \N_0$ and $\ell' \le \ell$. We split the sum into the two sums 
\begin{align}\label{eq:step1}
\begin{split}
 \sum_{T \in \TT_\ell} h_T \, \eta_{\ell}(T) \, \norm{\nabla_\Gamma \psi}_{L^2(\partial T \cap \Gamma)}
 &= \sum_{T \in \TT_{\ell'} \cap \TT_\infty} h_T \, \eta_{\ell}(T) \, \norm{\nabla_\Gamma \psi}_{L^2(\partial T \cap \Gamma)}
 \\& \quad
 + \sum_{T \in \TT_\ell \backslash (\TT_{\ell'} \cap \TT_\infty)} h_T \, \eta_{\ell}(T) \, \norm{\nabla_\Gamma \psi}_{L^2(\partial T \cap \Gamma)}
% &\sum_{T \in \TT_\ell} \big( \norm{w_\ell^\exact}_{L^2(T)} + h_T \norm{\nabla w_\ell^\exact}_{L^2(T)} \big) \, \norm{\nabla_\Gamma \psi}_{L^2(\partial T \cap \Gamma)}
% \nonumber
% \\& \quad
% \le 
% \sum_{T \in \TT_{\ell'} \cap \TT_\infty} \norm{w_\ell^\exact}_{L^2(T)} \norm{\nabla_\Gamma \psi}_{L^2(\partial T \cap \Gamma)}
% + 
% \sum_{T \in \TT_\ell \backslash (\TT_{\ell'} \cap \TT_\infty)} \norm{w_\ell^\exact}_{L^2(T)} \norm{\nabla_\Gamma \psi}_{L^2(\partial T %\cap \Gamma)}
% \\& \qquad
% \nonumber
% +
% \sum_{T \in \TT_{\ell'} \cap \TT_\infty} h_T \norm{\nabla w_\ell^\exact}_{L^2(T)} \norm{\nabla_\Gamma \psi}_{L^2(\partial T \cap \Gamma)}
% + 
% \sum_{T \in \TT_\ell \backslash (\TT_{\ell'} \cap \TT_\infty)} h_T \norm{\nabla w_\ell^\exact}_{L^2(T)} \norm{\nabla_\Gamma \psi}_{L^2(\partial T \cap \Gamma)}
\end{split}
\end{align}
and we consider each of these sums individually.

\textbf{Step~2.}
We consider the first sum on the right-hand side of~\eqref{eq:step1}.
Together with Proposition~\ref{thm:eta2conv}, the Cauchy--Schwarz inequality proves that
\begin{align}\label{eq:step2}
 \nonumber
 \sum_{T \in \TT_{\ell'} \cap \TT_\infty} 
 h_T \, \eta_{\ell}(T) \, \norm{\nabla_\Gamma \psi}_{L^2(\partial T \cap \Gamma)}
 %h_T \norm{\nabla w_\ell^\exact}_{L^2(T)} \norm{\nabla_\Gamma \psi}_{L^2(\partial T \cap \Gamma)}
% \norm{h_\ell}_{L^\infty(\Omega)} \, \norm{\nabla_\Gamma \psi}_{L^2(\Gamma)} \, \norm{\nabla w_\ell^\exact}_{L^2(\bigcup(\TT_{\ell'} \cap \TT_\infty))} 
% \\& \qquad
% = 
 &\le 
 \norm{h_\ell}_{L^\infty(\Omega)} \, \norm{\nabla_\Gamma \psi}_{L^2(\Gamma)} \, \eta_\ell(\TT_{\ell'} \cap \TT_\infty)
 \\&
 \lesssim 
 \eta_\ell(\TT_{\ell'} \cap \TT_\infty)
 \xrightarrow{\ell \to \infty} 0.
\end{align} 

\textbf{Step~3.}
We consider the second sum on the right-hand side of~\eqref{eq:step1}.
To show convergence, we first prove that $\bigcup[\TT_\ell \backslash (\TT_{\ell'} \cap \TT_\infty)] \subseteq \bigcup(\TT_{\ell'} \backslash \TT_\infty)$. To this end, let $T \in \TT_\ell \backslash (\TT_{\ell'} \cap \TT_\infty)$ and recall that $\ell \ge \ell'$. If $T \in \TT_{\ell'}$, then $T \in \TT_{\ell'} \backslash \TT_\infty$. If $T \not\in \TT_{\ell'}$, then there exists $T' \in \TT_{\ell'}$ with $T \subsetneqq T'$. This implies that $T' \not\in \TT_\infty$ and hence $T \subsetneqq T' \in \TT_{\ell'} \backslash \TT_\infty$. Overall, we confirm that 
\begin{align*}
 \bigcup(\TT_\ell \backslash (\TT_{\ell'} \cap \TT_\infty)) 
 \subseteq \bigcup(\TT_{\ell'} \backslash \TT_\infty)
\end{align*}
Second, we note that $h_\ell \le h_{\ell'}$ pointwise almost everywhere. 
By efficiency~\eqref{eq:efficiency} from Proposition~\ref{prop:efficiency} and the Céa lemma~\eqref{eq:cea}, it holds that 
%
\begin{equation*}
 \eta_\ell 
 = 
 \norm{\nabla w_\ell^\exact}_{L^2(\Omega)} 
 \eqreff{eq:efficiency}{\lesssim} 
 \norm{\phi^\exact - \phi_\ell^\exact}_{H^{-1/2}(\Gamma)} 
 \eqreff{eq:cea}{\lesssim} 
 \norm{\phi^\exact}_{H^{-1/2}(\Gamma)}.
\end{equation*} 
%

Hence, the convergence result from~\cite[Corollary~4.1]{Morin2008} leads to
\begin{align}\label{eq:step3}
 \nonumber
 &\sum_{T \in \TT_\ell \backslash (\TT_{\ell'} \cap \TT_\infty)} 
 %h_T \norm{\nabla w_\ell^\exact}_{L^2(T)} \norm{\nabla_\Gamma \psi}_{L^2(\partial T \cap \Gamma)}
 h_T \, \eta_{\ell}(T) \, \norm{\nabla_\Gamma \psi}_{L^2(\partial T \cap \Gamma)}
 \le
 \norm{h_\ell}_{L^\infty(\bigcup[\TT_\ell \backslash (\TT_{\ell'} \cap \TT_\infty)])} \, \norm{\nabla_\Gamma \psi}_{L^2(\Gamma)} \, 
 \eta_\ell
 %\norm{\nabla w_\ell^\exact}_{L^2(\Omega)}
 \\& \qquad 
 \lesssim
 \norm{h_\ell}_{L^\infty(\bigcup[\TT_\ell \backslash (\TT_{\ell'} \cap \TT_\infty)])}
 \le 
 \norm{h_{\ell'}}_{L^\infty(\bigcup(\TT_{\ell'} \backslash \TT_\infty))}
 \xrightarrow{\ell' \to \infty} 0.
\end{align}

\textbf{Step~4.} 
To formally conclude the proof, let $\eps > 0$. Recall from~\eqref{eq:step0}--\eqref{eq:step3} that
\begin{align*}
 &|\dual{V\phi^\exact - V\phi_{\ell}^\exact}{\psi}_{H^{1/2}(\Gamma) \times H^{-1/2}(\Gamma)}|
 \\& \quad
 \le 
 C \, \Big( 
 \norm{\psi}_{L^2(\Gamma)} \, \osc_\ell
 + \norm{\nabla_\Gamma \psi}_{L^2(\Gamma)} \, \eta_\ell(\TT_{\ell'} \cap \TT_\infty)
 + \norm{\nabla_\Gamma \psi}_{L^2(\Gamma)} \, \norm{h_{\ell'}}_{L^\infty(\bigcup(\TT_{\ell'} \backslash \TT_\infty))} \Big).
\end{align*}
We then choose $\ell' \in \N_0$ such that $C \, \norm{\nabla_\Gamma \psi}_{L^2(\Gamma)} \, \norm{h_{\ell'}}_{L^\infty(\bigcup(\TT_{\ell'} \backslash \TT_\infty))} \le \eps$. Finally, we may choose $\ell_0 \ge \ell'$ such that
$C \, \big[ 
 \norm{\psi}_{L^2(\Gamma)} \, \osc_\ell
 + \norm{\nabla_\Gamma \psi}_{L^2(\Gamma)} \, \eta_\ell(\TT_{\ell'} \cap \TT_\infty) \big]
 \le \eps$  for all $\ell \ge \ell_0$. Overall, we reveal that 
\begin{align*}
 |\dual{V\phi^\exact - V\phi_{\ell}^\exact}{\psi}_{H^{1/2}(\Gamma) \times H^{-1/2}(\Gamma)}| \le 2 \, \eps
 \quad \text{for all } \ell \ge \ell_0
\end{align*} 
 and hence conclude the proof.
\end{proof}

Finally, we are in the position to conclude also the proof of Theorem~\ref{theorem:mainresult}.

\begin{proof}[{\bfseries Proof of Theorem~\ref{theorem:mainresult}}]
The lower estimate in~\eqref{eq:theorem:mainresult} is the efficiency~\eqref{eq:efficiency} from Proposition~\ref{prop:efficiency}. The upper estimate in~\eqref{eq:theorem:mainresult} follows from the continuity of the single-layer potential $\widetilde{V} \colon H^{-1/2}(\Gamma) \to H^{1/2}(\Gamma)$ with $u^\exact - u^\exact_\ell = \widetilde{V}(\phi^\exact - \phi_\ell^\exact)$. According to 
%
\begin{equation*}
 (u^\exact - u^\exact_\ell)|_{\Gamma} 
 = 
 \bigl(\widetilde{V}(\phi^\exact - \phi^\exact_\ell)\bigr)|_{\Gamma} 
 = 
 V(\phi^\exact - \phi^\exact_\ell)
 \eqreff{eq:bie}{=}
 g - V\phi_\ell^\exact
\end{equation*}
%
and hence
%
\begin{equation*}
 \int_\Gamma (u^\exact - u_\ell^\exact) \d x
 \eqreff{eq:bie}{=}
 \dual{g - V\phi^\exact_\ell}{1}_\Gamma
 \eqreff{eq:weakdisc}{=}
 0,
\end{equation*}
%
a Poincaré-type inequality proves
%
\begin{equation*}
 \norm{u^\exact - u^\exact_\ell}_{H^1(\Omega)}
 \simeq 
 \norm{\nabla(u^\exact - u^\exact_\ell)}_{L^2(\Omega)} + \Bigl|\int_\Gamma (u^\exact - u^\exact_\ell) \d x \Bigr|
 =
  \norm{\nabla(u^\exact - u^\exact_\ell)}_{L^2(\Omega)}.
\end{equation*}
%
This the lower bound in~\eqref{eq:plainconv} with a Poincaré constant $\const{C}{P}$ depending only on $\Omega$. Together with~\eqref{eq:compupperbound}, which is the main result of~\cite{Kurz2020}, this proves the estimate of~\eqref{eq:plainconv}. Finally, error convergence~\eqref{eq:prop:convergence:norm} and efficiency~\eqref{eq:efficiency} prove 
%
\begin{equation*}
 \eta_\ell
 \eqreff{eq:efficiency}{\lesssim}
 \norm{\phi^\exact - \phi_\ell^\exact}_{H^{-1/2}(\Gamma)}
 \eqreff{eq:prop:convergence:norm}{\longrightarrow} 0
 \quad \text{as } \ell \to \infty.
\end{equation*}
%
Together with vanishing oscillations
%
\begin{equation*}
 \mathrm{osc}_\ell
 \eqreff{eq:oscconv}{\longrightarrow}
 0
 \quad \text{as } \ell \to \infty,
\end{equation*}
%
this concludes the proof of~\eqref{eq:plainconv}.
\end{proof}


\section{Proof of Theorem~\ref{thm:extconv} (lifting of discretized boundary residual)}
\label{section:extension}

\noindent A key difficulty in the analysis of Algorithm~\ref{algo:adap} is the behaviour of the discrete FEM solution $w_\ell^\exact$, since it is defined on the strip domain $\omega_\ell$, which changes adaptively in each step of Algorithm~\ref{algo:adap}. The goal of this section is to prove Theorem~\ref{thm:extconv}, which is crucial for the proof of Proposition~\ref{prop:efficiency} (efficiency) and Proposition~\ref{prop:auxconv} (convergence of functional upper bound).

\begin{lemma} \label{lem:discnorm}
Let $1 < r < \infty$ and $1/r + 1/r' = 1$. Then, there exists a constant $C > 0$ such that for all $T \in \TT_\ell$ and $f_\ell \in \SS^q(\TT_\ell^\Gamma)$, there holds that  
%
\begin{equation} \label{eq:liftcont}
 \norm{\widehat{f}_\ell}_{W^{1,r}(T)}^r 
 \leq 
 C(h_T^{-r/r'} \norm{f_\ell}_{L^r(\partial T \cap \Gamma)}^r + \abs{f_\ell}_{W^{1/r',r}(\partial T \cap \Gamma)}^r),
\end{equation}
%
where $\widehat{f}_\ell$ is the natural lifting of $f_\ell$ to $\Omega$; see~\eqref{eq:natext}. The constant $C$ depends only on $r$, $d$, $\kappa$-shape regularity of $\TT_\ell$, and $\mathrm{diam}(\Omega)$.      
\end{lemma}

\begin{proof}
The proof is split into 3 steps.

\textbf{Step~1 (Estimate of the discrete \boldsymbol{$W^{1,r}(T)$}-norm).} Let $v_\ell \in \SS^p(\TT_\ell)$ be arbitrary such that
%
\begin{equation*}
 v_\ell = \sum_{z \in \DD_\ell} \alpha_z \zeta_{\ell,z}.
\end{equation*}
%
Let $T \in \TT_\ell$ and $\DD_\ell(T)$ the local degrees of freedom on $T$. The affine diffeomorphism $\Phi_T \colon T_{\mathrm{ref}} \to T$, $\Phi_T(x) \coloneqq B_Tx + c_T$ with $|\mathrm{det}(B_T)| \simeq |T| \simeq h_T^d \simeq \norm{B_T}_{\mathrm{Frob}}^d \simeq \norm{B_T^{-1}}_{\mathrm{Frob}}^{-d}$ yields for $\widetilde{v}_{\ell,T} \coloneqq v_\ell \circ \Phi_T$ that
%
\begin{equation*}
 \norm{v_\ell}_{W^{1,r}(T)}^r 
 \simeq 
 h_T^d(\norm{\widetilde{v}_{\ell,T}}_{L^r(T_{\mathrm{ref}})}^r 
 + 
 \norm{(B_T^\intercal)^{-1}\nabla \widetilde{v}_{\ell,T}}_{L^r(T_{\mathrm{ref}})}^r)
\end{equation*} 
%
Recall the standard basis $(\zeta_j)_{j=1}^{n_{d}}$ of $\P^q(T_{\mathrm{ref}})$ from Section~\ref{section:preliminaries}. For $j \in \set{1, \ldots , n_{q,d}}$ let $z_j \in \DD_\ell(T)$ be the unique degree of freedom such that $\widetilde{\zeta}_j = \zeta_{z_j} \circ \Phi_T$. We can write $v_\ell|_T$ in the form
%
\begin{equation*}
 v_\ell|_T 
 = 
 \sum_{z \in \DD_\ell(T)} \alpha_z \zeta_{\ell,z}|_T,
\end{equation*}
%
which yields
%
\begin{equation*}
 \widetilde{v}_{\ell,T} 
 = 
 \sum_{j=1}^{n_{d}} \alpha_{z_j} \widetilde{\zeta}_j.
\end{equation*}
%
We obtain
%
\begin{equation*}
 \norm{\widetilde{v}_{\ell,T}}_{L^r(T_{\mathrm{ref}})} 
 \leq 
 \sum_{j = 1}^{n_d} \abs{\alpha_{z_j}} \norm{\widetilde{\zeta}_j}_{L^r(T_{\mathrm{ref}})} 
 \simeq
 \Bigl(\sum_{j = 1}^{n_{d}} \abs{\alpha_{z_j}}^r\Bigr)^{1/r} 
\end{equation*}
%
and
%
\begin{equation*}
 \begin{split}
  \norm{(B_T^\intercal)^{-1}\nabla \widetilde{v}_{\ell,T}}_{L^r(T_{\mathrm{ref}})} 
  &\lesssim 
  h_T^{-1} \sum_{j=1}^{n_{d}} \abs{\alpha_{z_j}} \norm{\nabla \widetilde{\zeta}_j}_{L^r(T_{\mathrm{ref}})} 
  \simeq 
  h_T^{-1} \Bigl(\sum_{j=1}^{n_{d}} \abs{\alpha_{z_j}}^r\Bigr)^{1/r}.
 \end{split}
\end{equation*}
%
This proves
%
\begin{equation} \label{eq:discvolnorm}
 \norm{v_\ell}_{W^{1,r}(T)}^r 
 \lesssim 
 h_T^d(1 + h_T^{-r}) \sum_{j = 1}^{n_{d}} \abs{\alpha_{z_j}}^r
 =
 h_T^d(1 + h_T^{-r}) \sum_{z \in \DD_\ell(T)} \abs{\alpha_{z}}^r.
\end{equation}

\textbf{Step~2 (Estimate of the discrete \boldsymbol{$W^{1/r',r}(F)$}-norm).}
Next, we aim to prove a similar estimate for the $W^{1/r',r}(\Gamma)$-norm. Let $f_\ell \in \SS^q(\TT_\ell^\Gamma)$ be arbitrary such that
%
\begin{equation*}
 f_\ell
 = 
 \sum_{z \in \DD_\ell(\Gamma)} \alpha_z \zeta_{\ell,z}|_\Gamma.
\end{equation*}
%
Let $F \in \TT_\ell^\Gamma$ and let $\DD_\ell(F)$ denote the local degrees of freedom on $F$. Let $T \in \TT_\ell$ with $F \subseteq \partial T$. Similar to Step 1, the diffeomorphism $\Psi_F \colon F_{\mathrm{ref}} \to F$, $\Psi_F(x) \coloneqq A_Fx + b_F$ with $\sqrt{\mathrm{det}(A_F^\intercal A_F)} \simeq |F| \simeq h_F^{d-1} \simeq \norm{A_F}_{\mathrm{Frob}}^{d-1} \simeq \norm{A_F^{-1}}_{\mathrm{Frob}}^{1-d}$ yields for 
%
\begin{equation*}
 \widetilde{f}_{\ell,F} 
 \coloneqq 
 f_\ell \circ \Psi_F 
 = 
 \sum_{j = 1}^{n_{d-1}} \alpha_{z_j} \widetilde{\zeta}_j|_{F_{\mathrm{ref}}}
\end{equation*} 
%
that
%
\begin{equation*}
 \norm{f_\ell}_{L^r(F)}^r 
 \simeq 
 h_F^{d-1} \norm{\widetilde{f}_{\ell,F}}_{L^r(F_{\mathrm{ref}})}^r
\end{equation*}
%
and, with $r/r' = r - 1$ and hence $2(d-1) - (d - 1 + r/r') = d-r$,
%
\begin{equation*}
 \begin{split}
  \abs{f_\ell}_{W^{1/r',r}(F)}^r 
  &= 
  \int_F \int_F \frac{\abs{f_\ell(x) - f_\ell(y)}^r}{\norm{x-y}^{d - 1 + r/r'}} \d x \d y 
  = 
  h_F^{2(d-1)} \int_{F_{\mathrm{ref}}} \int_{F_{\mathrm{ref}}} \frac{\abs{\widetilde{f}_{\ell,F}(x) - \widetilde{f}_{\ell,F}(y)}^r}{\norm{A_F(x - y)}^{d - 1 + r/r'}} \d x \d y \\
  &\simeq 
  h_F^{d-r} \int_{F_{\mathrm{ref}}} \int_{F_{\mathrm{ref}}} \frac{\abs{\widetilde{f}_{\ell,F}(x) - \widetilde{f}_{\ell,F}(y)}^r}{\norm{x-y}^{d-1 + r/r'}} \d x \d y 
  = 
  h_F^{d-r} \abs{\widetilde{f}_{\ell,F}}_{W^{1/r',r}(F_{\mathrm{ref}})}^r.
 \end{split}
\end{equation*}
%
Let $j_0 \in \set{1, \ldots , n_{d-1}}$. Note that 
%
\begin{equation*}
 \inf\set{\norm{v - \widetilde{\zeta}_{j_0}|_{F_{\mathrm{ref}}}}_{W^{1/r',r}(F_{\mathrm{ref}})} 
 \given 
 v \in \mathrm{span}\set{\widetilde{\zeta}_j|_{F_{\mathrm{ref}}} \given j \in \set{1, \ldots , n_{d-1}}  \setminus \set{j_0}}} \gtrsim 1.
\end{equation*}
%
If $\alpha_{z_{j_0}} \neq 0$, we obtain
%
\begin{equation*}
 \begin{split}
  1 
  &\lesssim 
  \Big\lVert\sum_{\substack{j = 1 \\ j \neq j_0}}^{n_{d-1}} (-\alpha_{z_j} / \alpha_{z_{j_0}}) \widetilde{\zeta}_j|_{F_{\mathrm{ref}}} - \widetilde{\zeta}_{j_0}\Big\rVert_{W^{1/r',r}(F_{\mathrm{ref}})}^r \\
  &= 
  \abs{\alpha_{z_{j_0}}}^{-r} \norm{\widetilde{f}_{\ell,F}}_{W^{1/r',r}(F_{\mathrm{ref}})}^r 
  \lesssim 
  \abs{\alpha_{z_{j_0}}}^{-r} (h_F^{1-d} \norm{f_\ell}_{L^r(F)}^r + h_F^{r-d} \abs{f_\ell}_{W^{1/r',r}(F)}^r)
 \end{split}
\end{equation*}
%
and hence
%
\begin{equation*}
 \abs{\alpha_{z_{j_0}}}^r 
 \lesssim 
 h_F^{1-d} \norm{f_\ell}_{L^r(F)}^r + h_F^{r-d} \abs{f_\ell}_{W^{1/r',r}(F)}^r.
\end{equation*}
%
Note that the latter estimate holds trivially if $\alpha_{z_{j_0}} = 0$.
Since $j_0 \in \set{1, \ldots, n_{d-1}}$ was arbitrary and $n_{d-1} \lesssim 1$, $\kappa$-shape regularity yields
%
\begin{equation} \label{eq:disctracenorm}
 \begin{split}
  \sum_{z \in \DD_\ell(F)} \abs{\alpha_z}^r 
  =
  \sum_{j = 1}^{n_{d-1}} \abs{\alpha_{z_j}}^r
  &\lesssim 
  h_F^{1-d} \norm{f_\ell}_{L^r(F)}^r 
  + 
  h_F^{r-d} \abs{f_\ell}_{W^{1/r',r}(F)}^r \\
  &\simeq 
  h_T^{1-d} \norm{f_\ell}_{L^r(F)}^r 
  + 
  h_T^{r-d} \abs{f_\ell}_{W^{1/r',r}(F)}^r
 \end{split}
\end{equation}

\textbf{Step~3 (Estimate of \boldsymbol{$W^{1,r}(T)$}-norm of the natural lifting).}
Let $f_\ell \in \SS^p(\TT_\ell^\Gamma)$ be such that
%
\begin{equation*}
 f_\ell = \sum_{z \in \DD_\ell(\Gamma)} \alpha_z \zeta_{\ell,z}|_{\Gamma}.
\end{equation*}
%
Denote by $\widehat{f}_\ell \in \SS^p(\TT_\ell)$ its natural lifting. Then, our previous considerations show
%
\begin{equation*}
 \begin{split}
  \norm{\widehat{f}_\ell}_{W^{1,r}(T)}^r 
  &\eqreff{eq:discvolnorm}{\lesssim} 
  h_T^d(1 + h_T^{-r}) \sum_{z \in \DD_\ell(T) \cap \DD_\ell(\Gamma)} \abs{\alpha_z}^r \\
  &\eqreff{eq:disctracenorm}{\lesssim} h_T^d(1 + h_T^{-r}) (h_T^{1-d} \norm{f_\ell}_{L^r(\partial T \cap \Gamma)}^r 
  + 
  h_T^{r-d} \abs{f_\ell}_{W^{1/r',r}(\partial T \cap \Gamma)}^r) \\
  &\lesssim
  h_T^{-r/r'} \norm{f_\ell}_{L^r(\partial T \cap \Gamma)}^r + \abs{f_\ell}_{W^{1/r',r}(\partial T \cap \Gamma)}^r.
 \end{split}
\end{equation*}
%
This concludes the proof.
\end{proof}

The following proposition states a uniform bound for the natural lifting of the discretized boundary residual $g_\ell$, which is imperative for the proof of Proposition~\ref{prop:efficiency}. To ease notation, we define the natural lifting of a discretized function $J_\ell f \in \SS^q(\TT_\ell)$ as $\widehat{J_\ell} f \coloneqq \widehat{J_\ell f}$.

\begin{proposition} \label{prop:extbound}
There exists $r_0 > 2$ such that for all $2 \leq r \leq r_0$ there exist $1/2 \leq s_r \leq 1$ and $C_r > 0$ such that
%
\begin{equation} \label{eq:boundarypoincare}
 \norm{ \nabla \widehat{J_\ell} (f - Q_\ell^\Gamma f)}_{L^r(\Omega)} 
 \leq 
 C_r \abs{f}_{H^{s_r}(\Gamma)}
 \quad \text{for any } f \in H^{s_r}(\Gamma).
\end{equation}
%
In particular, it holds that $s_r = 1/2$ for $r=2$ and
%
\begin{equation} \label{eq:boundarypoincare2}
\norm{\nabla \widehat{g}_\ell}_{L^2(\Omega)} \leq C_2 \abs{g - V \phi_\ell^\exact}_{H^{1/2}(\Gamma)} \leq C_2C_V \norm{\phi^\exact - \phi_\ell^\exact}_{H^{-1/2}(\Gamma)},
\end{equation}
%
where $C_V$ is the operator norm of $V \colon H^{-1/2}(\Gamma) \to H^{1/2}(\Gamma)$.
\end{proposition}

\begin{proof} The proof is split into $2$ steps.

\textbf{Step~1 (Proof of inverse inequalities).}
Given $F \in \TT_\ell^\Gamma$, $s \geq 0$, and $1 < \sigma,\nu < \infty$, we want to prove that there exists a constant $\const{C}{inv} > 0$ depending only on $\Omega$, $d$, $\kappa$-shape regularity of $\TT_\ell$, $q$, $\sigma$, $\nu$, $s$, but not on $F$ such that
%
\begin{equation} \label{eq:invineq}
 \norm{\varphi_\ell}_{W^{s,\sigma}(F)} \leq \const{C}{inv} h_F^{-s + (d-1)(1/\sigma - 1/\nu)} \norm{\varphi_\ell}_{L^\nu(F)}
 \quad \text{for all } \varphi_\ell \in \P^q(F).
\end{equation}
%
We transform $F$ to the reference facet $F_{\mathrm{ref}}$ by means of the affine diffeomorphism $\Psi_F \colon F_{\mathrm{ref}} \to F$, $\Psi(x) \coloneqq A_F x + b_F$ with $\sqrt{\mathrm{det}(A_F^\intercal A_F)} \simeq |F| \simeq h_F^{d-1} \simeq \norm{A_F}_{\mathrm{Frob}}^{d-1} \simeq \norm{A_F^{-1}}_{\mathrm{Frob}}^{1-d}$. Noting that $h_F \leq \mathrm{diam}(\Omega)$, we establish
\begin{equation*}
 \norm{\varphi_\ell}_{L^\sigma(F)}^\sigma
  \simeq
  h_F^{d-1} \norm{\varphi_\ell \circ \Psi_F}_{L^\sigma(F_{\mathrm{ref}})}^\sigma
  \lesssim
  h_F^{d-1 - s \sigma} \norm{\varphi_\ell \circ \Psi_F}_{L^\sigma(F_{\mathrm{ref}})}^\sigma
\end{equation*}
%
and
%
\begin{equation*}
 \begin{split}
  \abs{\varphi_\ell}_{W^{s,\sigma}(F)}^\sigma
  &\simeq
  \int_F \int_F \frac{\abs{\varphi_\ell(x) - \varphi_\ell(y)}^\sigma}{\abs{x-y}^{d-1 + s\sigma}} \d x \d y \\
  &=
  h_F^{2(d-1)} \int_{F_{\mathrm{ref}}} \int_{F_{\mathrm{ref}}} \frac{\abs{\varphi_\ell \circ \Psi_F(x) - \varphi_\ell \circ \Psi_F(y)}^\sigma}{\abs{A_F(x-y)}^{d-1 + s\sigma}} \d x \d y \\
  &\simeq
  h_F^{2(d-1) - (d - 1 + s \sigma)} \int_{F_{\mathrm{ref}}} \int_{F_{\mathrm{ref}}} \frac{\abs{\varphi_\ell \circ \Psi_F(x) - \varphi_\ell \circ \Psi_F(y)}^\sigma}{\abs{x-y}^{d-1 + s\sigma}} \d x \d y \\
  &=
  h_F^{d - 1 - s \sigma} \abs{\varphi_\ell \circ \Psi_F}_{W^{s,\sigma}(F_{\mathrm{ref}})}^\sigma.
 \end{split}
\end{equation*}
%
Since all norms are equivalent on the finite-dimensional space $\P^q(F_{\mathrm{ref}})$, we obtain
%
\begin{equation*}
 \begin{split}
  \norm{\varphi_\ell}_{W^{s,\sigma}(F)}^\sigma
  &\lesssim
  h_F^{d-1 - s \sigma} \norm{\varphi_\ell \circ \Psi_F}_{W^{s,\sigma}(F_{\mathrm{ref}})}^\sigma
  \simeq
  h_F^{d - 1 - s \sigma} \norm{\varphi_\ell\circ \Psi_F}_{L^\nu(F_{\mathrm{ref}})}^\sigma.
 \end{split}
\end{equation*}
%
With
%
\begin{equation*}
 \norm{\varphi_\ell \circ \Psi_F}_{L^\nu(F_{\mathrm{ref}})}^\nu
 \simeq
 h^{1-d} \norm{\varphi_\ell}_{L^\nu(F)}^\nu,
\end{equation*}
%
we obtain
%
\begin{equation*}
 \norm{\varphi_\ell}_{W^{s,\sigma}(F)}
 \lesssim
 h_F^{(d - 1)/\sigma - s} h_F^{(1 - d)/\nu } \norm{\varphi_\ell}_{L^\nu(F)}
 =
 h_F^{-s + (d-1)(1/\sigma - 1/\nu)} \norm{\varphi_\ell}_{L^\nu(F)}.
\end{equation*}
%
This concludes the proof of~\eqref{eq:invineq}.

\textbf{Step~2 (Proof of~(\ref{eq:boundarypoincare})).}

Let $\ell \in \N_0$. Note that $\widehat{J_\ell} f = 0$ if $T \in \TT_\ell$ satisfies $T \cap \Gamma = \emptyset$. Hence, Lemma~\ref{lem:discnorm} and~\eqref{eq:invineq} with $s = 1/r'$ and $\sigma = \nu = r$ yield
%
\begin{equation} \label{eq:liftingcont}
 \begin{split}
  &\norm{\nabla \widehat{J_\ell} (f - Q_\ell^\Gamma f)}_{L^r(\Omega)}^r 
  =
  \sum_{T \in \TT_\ell[\Gamma]} \norm{\nabla  \widehat{J_\ell} (f - Q_\ell^\Gamma f)}_{L^r(T)}^r \\
  &\qquad \eqreff{eq:boundarypoincare}{\lesssim}
  \sum_{T \in \TT_\ell[\Gamma]} \Bigl( h_T^{-r/r'} \norm{J_\ell (f - Q_\ell^\Gamma f)}_{L^r(\partial T \cap \Gamma)}^r + \abs{J_\ell (f - Q_\ell^\Gamma f)}_{W^{1/r',r}(\partial T \cap \Gamma)}^r \Bigr) \\
  &\qquad \eqreff{eq:invineq}{\lesssim}
  \sum_{T \in \TT_\ell[\Gamma]} h_T^{-r/r'} \norm{J_\ell (f - Q_\ell^\Gamma f)}_{L^r(\partial T \cap \Gamma)}^r
  = 
  \norm{h_\ell^{-1/r'} J_\ell (f - Q_\ell^\Gamma f)}_{L^r(\Gamma)}^r.
 \end{split}
\end{equation}
%
We define 
%
\begin{equation} \label{eq:srdef}
  s_r \coloneqq [r - 1 + (d-1)(r/2 - 1)]/r
  \quad \text{for any } r \geq 2
\end{equation}
%
and note that $s_2 = 1/2$. Let $r \geq 2$. We note that $r/r' = r - 1$ and use~\eqref{eq:invineq} with $s=0$, $\sigma = r$, and $\nu = 2$ to obtain
\begin{equation} \label{eq:longcomput}
 \begin{split}
  \norm{h^{-1/r'}_\ell J_\ell (f - Q_\ell^\Gamma f)}_{L^r(\Gamma)}^r 
  &=  
  \sum_{F \in \TT_\ell^{\Gamma}} h_F^{-r/r'} \norm{J_\ell (f - Q_\ell^\Gamma f)}_{L^r(F)}^r \\
  &\eqreff{eq:invineq}{\lesssim} 
  \sum_{F \in \TT_\ell^{\Gamma}} h_F^{1 - r} h_F^{(d-1)(1 - r/2)} \norm{J_\ell (f - Q_\ell^\Gamma f)}_{L^2(F)}^r \\
  &\eqreff{eq:srdef}{=} \sum_{F \in \TT_\ell^{\Gamma}} h_F^{-rs_r} \norm{J_\ell (f - Q_\ell^\Gamma f)}_{L^2(F)}^r \\
  &= \sum_{F \in \TT_\ell^\Gamma} \norm{h_\ell^{-s_r} J_\ell (f - Q_\ell^\Gamma f)}_{L^2(F)}^{r - 2} \norm{h_\ell^{-s_r} J_\ell (f - Q_\ell^\Gamma f)}_{L^2(F)}^2 \\
  &\leq
  \norm{h_\ell^{-s_r}J_\ell(f - Q_\ell^\Gamma f)}_{L^2(\Gamma)}^{r - 2} \sum_{F \in \TT_\ell^{\Gamma}} \norm{h_\ell^{-s_r} J_\ell (f - Q_\ell^\Gamma f)}_{L^2(F)}^2 \\
  &=
  \norm{h_\ell^{-s_r}J_\ell (f - Q_\ell^\Gamma f)}_{L^2(\Gamma)}^r.
 \end{split}
\end{equation}
%
Lemma~\ref{lem:SZ} and the properties~\eqref{eq:avgprop} of $Q_\ell^\Gamma$ yield
%
\begin{equation} \label{eq:avgapprox}
 \begin{split}
 &\norm{h_\ell^{-s} J_\ell(f - Q_\ell^\Gamma f)}_{L^2(\Gamma)}^2
 = 
 \sum_{F \in \TT_\ell^\Gamma} h_F^{-2s} \norm{J_\ell(f - Q_\ell^\Gamma f)}_{L^2(F)}^2 
 \eqreff{eq:SZtraceL2}{\lesssim}
 \sum_{F \in \TT_\ell^\Gamma} h_F^{-2s} \norm{f - Q_\ell^\Gamma f}_{L^2(\Gamma_\ell[F])}^2 \\
 &\qquad \lesssim
 \sum_{F \in \TT_\ell^\Gamma} h_F^{-2s} \norm{f - Q_\ell^\Gamma f}_{L^2(F)}^2
 \eqreff{eq:avgprop}{\lesssim}
 \sum_{F \in \TT_\ell^\Gamma} \abs{f}_{H^{s}(F)}^2 
 \leq \abs{f}_{H^{s}(\Gamma)}^2
 \quad \text{for all } 0 < s \leq 1.
 \end{split}
\end{equation}
%
It remains to verify that $0 < s_r \leq 1$. Indeed, elementary calculations show that $0 < s_r \leq 1$ if and only if $2 - 2/(d+1) < r \leq 2 + 2/(d-1)$. With $r_0 = 2 + 2/(d-1) > 2$, we are thus led to
%
\begin{equation*}
 \begin{split}
 \norm{\nabla \widehat{J_\ell} (f - Q_\ell^\Gamma f)}_{L^r(\Omega)} 
 \eqreff{eq:liftingcont}{\lesssim}
 \norm{h^{-1/r'}J_\ell (f - Q_\ell^\Gamma f)}_{L^r(\Gamma)} 
 &\eqreff{eq:longcomput}{\lesssim}
 \norm{h^{-s_r}J_\ell (f - Q_\ell^\Gamma f)}_{L^2(\Gamma)} \\ 
 &\eqreff{eq:avgapprox}{\lesssim}
 \abs{f}_{H^{s_r}(\Gamma)}.
 \end{split}
\end{equation*}
%
This proves~\eqref{eq:boundarypoincare}. 


\textbf{Step~3 (Proof of~(\ref{eq:boundarypoincare2})).}
By~\eqref{eq:weakdisc}, there holds $Q_\ell^\Gamma(g - V\phi_\ell^\exact) = 0$. Hence, we can apply~\eqref{eq:boundarypoincare} with $f = g - V\phi_\ell^\exact$ and $g_\ell = J_\ell f = J_\ell(f - Q_\ell^\Gamma f)$ for $r = 2$ and $s_r = 1/2$ to obtain~\eqref{eq:boundarypoincare2}. This concludes the proof.
\end{proof}

We now have all the ingredients to prove Theorem~\ref{thm:extconv}.

\begin{proof}[\textbf{Proof of Theorem~\ref{thm:extconv}}]
We define the limiting layer
%
\begin{equation*}
 \omega_\infty \coloneqq \bigcap_{\ell \in \N_0} \omega_\ell.
\end{equation*}
%
As our first step, we want to characterize the set $\omega_\infty$ in terms of the involved triangulations.

\textbf{Step~1 (Characterization of \boldsymbol{$\omega_\infty$}).} Recall the set $\TT_\infty$ of all elements which remain unrefined after a finite amount of steps; see~\eqref{eq:Tinfty}. We want to prove that 
%
\begin{equation} \label{eq:omegainfty}
 \omega_\infty 
 \subseteq 
 \bigcup \set{T \in \TT_\infty \given T \subset \overline{\omega}_\infty} 
 \eqqcolon
 \widetilde{\omega}_\infty
 \subseteq
 \overline{\omega}_\infty.
\end{equation}
%
The inclusion $\widetilde{\omega}_\infty \subseteq \overline{\omega}_\infty$ is obvious. In order to show the converse inclusion, let $x \in \omega_\infty$. We aim to prove that $x \in \widetilde{\omega}_\infty$. Since $x \in \omega_\ell = \Omega_\ell^{[k]}[\Gamma]$ for every $\ell \in \N_0$, there exists a sequence $(\widetilde{T}_\ell)_{\ell \in \N_0}$ with $x \in \widetilde{T}_\ell \in \TT_\ell^{(k)}[\Gamma]$ and $\widetilde{T}_{\ell + 1} \subseteq \widetilde{T}_\ell$ for all $\ell \in \N_0$. Furthermore, for all $\ell \in \N_0$, there exists $T_\ell \in \TT_\ell$ with $T_\ell \cap \Gamma \neq 0$ and $\widetilde{T}_\ell \in \TT_\ell^{[k]}[T_\ell]$. If $\widetilde{T}_\ell \in \TT_\infty$ for some $\ell \in \N_0$ (and hence $\widetilde{T}_\ell = \widetilde{T}_k$ for all $k \geq \ell$), then $x \in \widetilde{\omega}_\infty$. If $\widetilde{T}_\ell \notin \TT_\infty$ for all $\ell \in \N_0$, then $|\widetilde{T}_\ell| \xrightarrow{\ell \to \infty} 0$ by~\cite[Corollary 4.5]{Morin2008}. By use of $\kappa$-shape regularity, we obtain
%
\begin{equation*}
\mathrm{dist}(x,\Gamma) 
\leq 
\mathrm{dist}(x, \Gamma \cap \Omega_\ell^{[k]}(T_\ell)) 
\leq 
\mathrm{diam}(\Omega_\ell^{[k]}[T_\ell]) 
\simeq 
|\widetilde{T}_\ell|^{1/d} \xrightarrow{\ell \to \infty} 0.
\end{equation*}
%
This yields $x \in \Gamma$, contradicting $x \in \omega_\infty$ since $\omega_\infty \subseteq \Omega$ and $\Omega$ is open, i.e., $\Omega \cap \Gamma = \emptyset$. Hence,  the case that $\widetilde{T}_\ell \notin \TT_\infty$ for all $\ell \in \N_0$ cannot occur. This proves~\eqref{eq:omegainfty}.

\textbf{Step~2 (Construction of \boldsymbol{$\widehat{g}_\infty$}).}
By Lemma~\ref{lemma:apriori}, there exists $\phi_\infty^\exact \in H^{-1/2}(\Gamma)$ such that $\norm{\phi^\exact - \phi_\infty^\exact}_{H^{-1/2}(\Gamma)} \xrightarrow{\ell \to \infty} 0$. We define $g_{\infty,\ell} \coloneqq J_\ell(g - V\phi_\infty^\star)$ and denote by $\widehat{g}_{\infty,\ell}$ its discrete lifting. To construct $\widehat{g}_\infty \in H^1(\Omega)$, we first define $\widehat{g}_\infty|_{\Omega \setminus \omega_\infty} \coloneqq 0$. Second, since $\omega_\infty$ coincides with $\widetilde{\omega}_\infty$ up to a set of measure zero, it suffices to define $\widehat{g}_\infty|_T$ for all $T \in \TT_\infty$ such that $T \subseteq \overline{\omega}_\infty$. We note that
%
\begin{equation*}
 \TT_\infty = \displaystyle{\bigcup_{\ell \in \N_0} \TT_\ell^0},
 \quad \text{where }
 \TT_\ell^0 
 \coloneqq 
 \set{T \in \TT_\ell \given \TT_\ell[T] \subseteq \TT_\infty}
 \quad \text{for all } \ell \in \N_0;
\end{equation*}
%
see \cite[Section 4.1]{Morin2008}.
Let $T \in \TT_\infty$ with $T \subseteq \overline{\omega}_\infty$. Then, there is a smallest index $\ell_T \in \N_0$ such that $T \in \TT_{\ell_T}^0$. We define $\widehat{g}_\infty|_T \coloneqq\widehat{g}_{\infty,\ell_T}|_T$. Note that if $T \cap \Gamma = \emptyset$, then $\widehat{g}_\infty|_T = 0$. Furthermore, if $\ell_T \leq \ell$, then $\TT_{\ell_T}[T] = \TT_\ell[T]$. Since $J_\ell(g - V\phi_\infty^\exact)|_{\partial T \cap \Gamma}$ depends only on $(g - V\phi_\infty^\exact)|_{\Gamma_\ell[\partial T]}$ (see Lemma~\ref{lem:SZ}), this yields $\widehat{g}_{\infty,\ell}|_T = \widehat{g}_{\infty, \ell_T}|_T$. 

\textbf{Step~3 (\boldsymbol{$\widehat{g}_\infty$} is weakly differentiable)}. 
Let $\varphi \in C^{\infty}_0(\Omega)^d$. Then, integration by parts proves
%
\begin{equation*}
 \begin{split}
  &\dual{\widehat{g}_\infty}{\div \varphi}_{L^2(\Omega)} 
  = 
  \sum_{\substack{ T \in \TT_\infty \\ T \cap \Gamma \neq \emptyset}} \dual{\widehat{g}_\infty}{\div \varphi}_{L^2(T)} 
  = 
  \sum_{\substack{ T \in \TT_\infty \\ T \cap \Gamma \neq \emptyset}} \dual{\widehat{g}_{\infty,\ell_T}}{\div \varphi}_{L^2(T)} \\
  &\quad = 
  \sum_{\substack{T \in \TT_\infty \\ T \cap \Gamma \neq 0}} \dual{\widehat{g}_{\infty,\ell_T}}{\varphi \cdot n_T}_{L^2(\partial T \setminus \Gamma)} 
  - 
  \sum_{\substack{ T \in \TT_\infty \\ T \cap \Gamma \neq \emptyset}} \dual{\nabla \widehat{g}_{\infty,\ell_T}}{\phi}_{L^2(T)}. 
 \end{split}
\end{equation*}
%
It remains to show that the first sum on the right-hand side vanishes. Let $T_1,T_2 \in \TT_\infty$ with $T_1 \cap \Gamma \neq \emptyset \neq T_2 \cap \Gamma$ such that $F \coloneqq T_1 \cap T_2 \in \FF_\ell$ for some sufficiently large $\ell \in \N_0$ with $T_1,T_2 \in \TT_\ell$. Without loss of generality, it holds that $\ell_{T_1} \leq \ell_{T_2}$. Since $\TT_{\ell_{T_1}}[T_1] \subseteq \TT_\infty$ and $T_2 \in \TT_\infty$, with $T_1 \cap T_2 \in \FF_\ell$, it follows that $T_2 \in \TT_{\ell_{T_1}}[T_1] = \TT_{\ell_{T_2}}[T_1]$. Since $\widehat{g}_{\infty,\ell_{T_1}}$ depends only on the patch $\Omega_{\ell_{T_1}}[T_1]$ and $(g - V\phi_\infty^\exact)|_{\Gamma_{\ell_{T_1}}[T_1]}$, it follows that $\widehat{g}_{\infty,\ell_{T_1}}|_{T_1} =\widehat{g}_{\infty,\ell_{T_2}}|_{T_1}$. Because of $\widehat{g}_{\infty,\ell_{T_2}} \in H^1(T_1 \cup T_2)$, we obtain 
%
\begin{equation*}
 \dual{\widehat{g}_{\infty,\ell_{T_1}}}{\varphi \cdot n_{T_1}}_{L^2(F)} 
 = 
 \dual{\widehat{g}_{\infty,\ell_{T_2}}}{\varphi \cdot n_{T_1}}_{L^2(F)}
 = 
 -\dual{\widehat{g}_{\infty,\ell_{T_2}}}{\varphi \cdot n_{T_2}}_{L^2(F)}.
\end{equation*}
%
Since each interior facet is shared by precisely two elements, this guarantees that
%
\begin{equation*}
 \sum_{\substack{T \in \TT_\infty \\ T \cap \Gamma \neq \emptyset}} \dual{\widehat{g}_{\infty,\ell_T}}{\varphi \cdot n_T}_{L^2(\partial T \setminus \Gamma)} 
 = 
 0.
\end{equation*}
%
Therefore, $\widehat{g}_\infty$ is weakly differentiable with $\nabla \widehat{g}_\infty|_{\Omega \setminus \omega_\infty} = 0$ and $\nabla \widehat{g}_\infty|_T = \nabla\widehat{g}_{\infty,\ell_T}$ for all $T \in \TT_\infty$ with $T \subseteq \overline{\omega}_\infty$ for all $\ell \in N_0$.

\textbf{Step~4 (\boldsymbol{$\widehat{g}_{\infty,\ell} \to \widehat{g}_\infty$} in \boldsymbol{$H^1(\Omega)$})}.
Let $\eps > 0$. Since $L^2(\Gamma)$ is dense in $H^{-1/2}(\Gamma)$, there exists $\varphi_\eps \in L^2(\Gamma)$ with $\norm{(\phi^\exact - \phi_\infty^\exact) - \varphi_\eps}_{H^{-1/2}(\Gamma)} \leq \eps$. We start by showing the existence of $\ell_0 \in \N_0$ such that 
%
\begin{equation} \label{eq:intbound}
  \norm{\widehat{g}_{\infty,\ell} - \widehat{g}_\infty}_{L^2(\Omega \setminus \omega_\infty)} 
  \lesssim
  \eps
  \quad \text{for all } \ell \geq \ell_0.
\end{equation} 
%
We have
%
\begin{equation} \label{eq:intconv}
 \begin{split}
 &\norm{\nabla (\widehat{g}_{\infty,\ell} - \widehat{g}_\infty)}_{L^2(\Omega \setminus \omega_\infty)} 
 = 
 \norm{\nabla\widehat{g}_{\infty,\ell}}_{L^2(\omega_\ell \setminus \omega_\infty)} \\
 &\qquad \leq
 \norm{\nabla \widehat{J_\ell} (V\varphi_\eps - Q_\ell^\Gamma V \varphi_\eps)}_{L^2(\omega_\ell \setminus \omega_\infty)} + \norm{\nabla (\widehat{g}_{\infty,\ell} - \widehat{J_\ell} (V \varphi_\eps - Q_\ell^\Gamma \varphi_\eps))}_{L^2(\Omega)} 
 \end{split}
\end{equation}
%
We first consider the first summand of the right-hand side of~\eqref{eq:intconv}. Due to Proposition~\ref{prop:extbound}, there exists $r > 2$ and $1/2 < s_r \leq 1$ such that 
%
\begin{equation} \label{eq:phiepsesti}
 \norm{\nabla \widehat{J_\ell} (V\varphi_\eps - Q_\ell^\Gamma V \varphi_\eps)}_{L^r(\Omega)} 
 \eqreff{eq:boundarypoincare}{\lesssim} 
 \abs{V \varphi_\eps}_{H^{s_r}(\Gamma)} 
 \lesssim
 \norm{\varphi_\eps}_{H^{s_r - 1}(\Gamma)} 
 \lesssim 
 \norm{\varphi_\eps}_{L^2(\Gamma)}.
\end{equation} 
%
The H\"older inequality yields
%
\begin{equation*}
 \begin{split}
  \norm{\nabla \widehat{J_\ell} (V\varphi_\eps - Q_\ell^\Gamma V \varphi_\eps)}_{L^2(\omega_\ell \setminus \omega_\infty)} 
  &\leq 
  \abs{\omega_\ell \setminus \omega_\infty}^{1/2 - 1/r} \norm{\nabla\widehat{J_\ell} (V\varphi_\eps - Q_\ell^\Gamma V \varphi_\eps)}_{L^r(\omega_\ell \setminus \omega_\infty)} \\
  &\lesssim
  \abs{\omega_\ell \setminus \omega_\infty}^{1/2 - 1/r} \norm{\varphi_\eps}_{L^2(\Gamma)}.
 \end{split}
\end{equation*}
%
Since $\omega_\infty = \displaystyle{\bigcap_{\ell \in \N_0} \omega_\ell}$ and $\eps$ is fixed, there exists $\ell_0 \in \N_0$ such that $\abs{\omega_\ell \setminus \omega_\infty}^{1/2 - 1/r}\norm{\varphi_\eps}_{L^2(\Gamma)} \leq \eps$ for all $\ell \geq \ell_0$. For the second summand of~\eqref{eq:intconv}, we exploit $Q_\ell^\Gamma(V \phi^\exact - V\phi_\infty^\exact) = 0$ (see Lemma~\ref{lemma:apriori}) and apply Proposition~\ref{prop:extbound} with $r=2$ and $s_r = 1/2$ to obtain
%
\begin{equation} \label{eq:perturbation}
 \begin{split}
  &\norm{\nabla \widehat{g}_{\infty,\ell} - \widehat{J_\ell} (V \varphi_\eps - Q_\ell^\Gamma \varphi_\eps)}_{L^2(\Omega)}
  =
  \norm{\nabla \widehat{J_\ell}(V(\phi^\exact - \phi_\infty^\exact - \varphi_\eps) - Q_\ell^\Gamma V(\phi^\exact - \phi_\infty^\exact - \varphi_\eps))}_{L^2(\Omega)} \\
  &\qquad \eqreff{eq:boundarypoincare}{\lesssim} 
  \abs{V(\phi^\exact - \phi_\infty^\exact - \varphi_\eps)}_{H^{1/2}(\Gamma)} 
  \lesssim \norm{\phi^\exact - \phi_\infty^\exact - \varphi_\eps}_{H^{-1/2}(\Gamma)} \leq \eps.
 \end{split}
\end{equation}
%
Altogether, this yields~\eqref{eq:intbound}. Furthermore, we have that 
%
\begin{equation} \label{eq:omegainftyesti}
 \begin{split}  
  &\norm{\nabla(\widehat{g}_{\infty,\ell} - \widehat{g}_\infty)}_{L^2(\omega_\infty)}^2 
  = 
  \sum_{\substack{T \in \TT_\infty \\ T \cap \Gamma \neq \emptyset}} \norm{\nabla(\widehat{g}_{\infty,\ell} - \widehat{g}_\infty)}_{L^2(T)}^2 
  = 
  \sum_{\substack{T \in \TT_\infty \\ T \cap \Gamma \neq \emptyset \\ \ell_T > \ell}} \norm{\nabla (\widehat{g}_{\infty,\ell} - \widehat{g}_\infty)}_{L^2(T)}^2 \\
  &\qquad = 
  \sum_{\substack{T \in \TT_\infty \\ T \cap \Gamma \neq \emptyset \\ T \notin \TT_\ell^0}} \norm{\nabla (\widehat{g}_{\infty,\ell} - \widehat{g}_\infty)}_{L^2(T)}^2 
  \leq 
  \sum_{T \in \TT_\infty \setminus \TT_\ell^0} \norm{\nabla(\widehat{g}_{\infty,\ell} - \widehat{g}_\infty)}_{L^2(T)}^2 \\
  &\qquad \lesssim 
  \sum_{T \in \TT_\infty \setminus \TT_\ell^0} \norm{\nabla \widehat{g}_{\infty,\ell}}_{L^2(T)}^2 
  + 
  \sum_{T \in \TT_\infty \setminus \TT_\ell^0} \norm{\nabla \widehat{g}_\infty}_{L^2(T)}^2 \\
  &\qquad = \norm{\nabla \widehat{g}_{\infty,\ell}}_{L^2(\bigcup[\TT_\infty \setminus \TT_\ell^0])}^2 + \sum_{T \in \TT_\infty \setminus \TT_\ell^0} \norm{\nabla \widehat{g}_\infty}_{L^2(T)}^2.
 \end{split}
\end{equation}
%
Considering the first term right-hand side of~\eqref{eq:omegainftyesti}, we have
%
\begin{equation} \label{eq:omegainftyesti1}
 \begin{split}
  \norm{\nabla \widehat{g}_{\infty,\ell}}_{L^2(\bigcup[\TT_\infty \setminus \TT_\ell^0])}
  &\leq
  \norm{\nabla \widehat{J_\ell} (V\varphi_\eps - Q_\ell^\Gamma V \varphi_\eps)}_{L^2(\bigcup[\TT_\infty \setminus \TT_\ell^0])} \\
  &\qquad + \norm{\nabla (\widehat{g}_{\infty,\ell} - \widehat{J_\ell} (V \varphi_\eps - Q_\ell^\Gamma \varphi_\eps))}_{L^2(\Omega)} \\
  &\eqreff{eq:perturbation}{\lesssim}
  \norm{\nabla \widehat{J_\ell} (V\varphi_\eps - Q_\ell^\Gamma V \varphi_\eps)}_{L^2(\bigcup[\TT_\infty \setminus \TT_\ell^0])} + \eps.
 \end{split}
\end{equation}
%
H\"older's inequality together with~\eqref{eq:phiepsesti} yields
%
\begin{equation*}
 \begin{split}
  &\norm{\nabla \widehat{J_\ell} (V\varphi_\eps - Q_\ell^\Gamma V \varphi_\eps)}_{L^2(\bigcup[\TT_\infty \setminus \TT_\ell^0])} \\
  &\qquad \leq
  \big|\bigcup[\TT_\infty \setminus \TT_\ell^0]\big|^{1/2 - 1/r} \norm{\nabla \widehat{J_\ell} (V\varphi_\eps - Q_\ell^\Gamma V \varphi_\eps)}_{L^r(\bigcup[\TT_\infty \setminus \TT_\ell^0])} \\
  &\qquad \lesssim
  \big|\bigcup[\TT_\infty \setminus \TT_\ell^0]\big|^{1/2 - 1/r} \norm{\varphi_\eps}_{L^2(\Gamma)}.
 \end{split}
\end{equation*}
%
Since $\TT_\infty = \displaystyle{\bigcup_{\ell \in \N_0} \TT_\ell^0}$ and $\eps$ is fixed, there exists $\ell_1 \in \N_0$ such that $\Big| \displaystyle{\bigcup [\TT_\infty \setminus \TT_\ell^0]}\Big|^{1/2 - 1/r} \norm{\varphi_\eps}_{L^2(\Gamma)} \leq \eps$ for all $\ell \geq \ell_1$. Hence, we see 
%
\begin{equation*}
 \norm{\nabla \widehat{g}_{\infty,\ell}}_{L^2(\bigcup[\TT_\infty \setminus \TT_\ell^0])}
 \lesssim
 \eps 
 \quad \text{for } \ell \geq \max\set{\ell_0,\ell_1}.
\end{equation*}
%
The second term on the right-hand side of~\eqref{eq:omegainftyesti1} can be estimated analogously as in~\eqref{eq:perturbation}. It remains to estimate the second term on the right-hand side of~\eqref{eq:omegainftyesti}. Due to the definition of $\widehat{g}_\infty$, the lifting estimate~\eqref{eq:liftcont} of Lemma~\ref{lem:discnorm}, Lemma~\ref{lem:SZ}, and the properties~\eqref{eq:avgprop} of $Q_\ell^\Gamma$, we obtain
%
\begin{equation*}
 \begin{split}
  &\norm{\nabla \widehat{g}_{\infty}}_{L^2(T)}
  = 
  \norm{\nabla \widehat{g}_{\infty,\ell_T}}_{L^2(T)}
  \eqreff{eq:liftcont}{\lesssim} 
  h_T^{-1/2} \norm{g_{\infty,\ell_T}}_{L^2(\partial T \cap \Gamma)} + \abs{g_{\infty,\ell_T}}_{H^{1/2}(\partial T \cap \Gamma)} \\
  &\qquad \eqreff{lem:SZ}{\lesssim}
  h_T^{-1/2} \norm{g - V\phi_\infty^\exact}_{L^2(\Gamma_{\ell_T}[T])} + \abs{g - V\phi_\infty^\exact}_{H^{1/2}(\Gamma_{\ell_T}[T])}
  \eqreff{eq:avgprop}{\lesssim}
  \abs{g - V\phi_\infty^\exact}_{H^{1/2}(\Gamma_{\ell_T}[T])}.
 \end{split}
\end{equation*}
%
Therefore, $\kappa$-shape regularity establishes
%
\begin{equation*}
 \sum_{T \in \TT_\infty} \norm{\nabla \widehat{g}_\infty}_{L^2(T)}^2 
 \lesssim 
 \sum_{T \in \TT_\infty} \abs{g - V\phi_\infty^\exact}_{H^{1/2}(\Gamma_\ell[T])}^2 
 \lesssim 
 \abs{g - V\phi_\infty^\exact}_{H^{1/2}(\Gamma)}^2.
\end{equation*}
%
Since $\TT_\infty = \displaystyle{\bigcup_{\ell \in \N_0} \TT_\ell^0}$, we can choose $\ell_2 \in \N_0$ such that
%
\begin{equation*}
 \sum_{T \in \TT_\infty \setminus \TT_\ell^0} \norm{\nabla \widehat{g}_\infty}_{L^2(T)}^2
 \leq
 \eps
 \quad \text{for all } \ell \geq \ell_2.
\end{equation*}
%
Altogether, this proves $\norm{\nabla(\widehat{g}_{\infty,\ell} - \widehat{g}_\infty)}_{L^2(\Omega)} \lesssim \eps$ for all $\ell \geq \max\set{\ell_0,\ell_1,\ell_2}$ yielding $\widehat{g}_{\infty,\ell} \xrightarrow{\ell \to \infty} \widehat{g}_\infty$ and, in particular, $\widehat{g}_\infty \in H^1(\Omega)$.

\textbf{Step~5 (\boldsymbol{$\widehat{g}_{\ell} \to \widehat{g}_\infty$} in \boldsymbol{$H^1(\Omega)$})}. We have
%
\begin{equation*}
 \begin{split}
  \norm{\nabla(\widehat{g}_\ell - \widehat{g}_\infty)}_{L^2(\Omega)} 
  &\leq 
  \norm{\nabla(\widehat{g}_{\infty,\ell} - \widehat{g}_\infty)}_{L^2(\Omega)} 
  + 
  \norm{\nabla\widehat{J_\ell}V(\phi_\infty^\exact - \phi_\ell^\exact)}_{L^2(\Omega)}.
 \end{split}
\end{equation*}
%
The first term on the right-hand side converges to zero as $\ell \to \infty$ by Step~4. Note that $Q_\ell^\Gamma V (\phi_\infty^\exact - \phi_\ell^\exact) = 0$. For the second term, we thus argue as in Step~4, and exploit the \sl{a~priori} convergence of Lemma~\ref{lemma:apriori} to obtain that
%
\begin{equation*}
 \begin{split}
  &\norm{\nabla\widehat{J_\ell}V(\phi_\infty^\exact - \phi_\ell^\exact)}_{L^2(\Omega)}^2 = \sum_{\substack{T \in \TT_\ell \\ T \cap \Gamma \neq \emptyset}} \norm{\nabla\widehat{J_\ell}V(\phi_\infty^\exact - \phi_\ell^\exact)}_{L^2(T)}^2 \lesssim 
  \sum_{F \in \TT_\ell^\Gamma} \abs{ V(\phi_\infty^\exact - \phi_\ell^\exact)}_{H^{1/2}(\Gamma_\ell[F])}^2 \\
  &\qquad \lesssim \abs{V\phi_\infty^\exact - V\phi_\ell^\exact}_{H^{1/2}(\Gamma)}^2 \xrightarrow{\ell \to \infty} 0.
     \end{split}
    \end{equation*}
%
This concludes the proof.
\end{proof}

\section{Numerical experiments}
\label{section:numerics}


This section presents some numerical experiments in $2$D that illustrate the accuracy and performance of the proposed method. All computations are done by use of the MATLAB-toolboxes HILBERT from \cite{Aurada2014} for BEM with $p \in \set{0,1}$, \cite{Funken2011} for standard FEM for the functional upper bound~\eqref{eq:compupperbound} with $q \in \set{1,2}$, and \cite{Bahriawati2005} for mixed FEM for the functional lower bound~\eqref{eq:lower-bound} with $q = 1$. Throughout, we consider Algorithm~\ref{algo:adap} for uniform ($\theta = 1$) and adaptive ($0 < \theta < 1$) mesh refinement.  
