%%  Our construction works only if the obligation graph is saturated (in which case it resembles the augmented subset construction of~\cite{10.1109/LICS.2009.32}).
%%  If the obligation graph is not saturated,
%%  the inclusion $L^1 \subseteq L(\mc A^1_N)$ fails already on the first level,
%%  see Section~\ref{app:kindness-is-necessary} in the appendix.
%%\end{remark*}

\begin{corollary}
  For every weak alternating automaton $\mc A$:
  $L(\mc A^\ell_N) = L^\ell$,
  where $L^\ell$ is the language of the $\ell$th level of the COCOA for $L(\mc A)$.
\end{corollary}

\subsection{Procedure to construct the COCOA $(\mc A^1,\ldots,\mc A^k)$}

\begin{lemma}\label{lem:AlN-construction-time}
  For every weak alternating automaton $\mc A$ with $n$ states and a transition function representation that is at most exponential in $n$,
  for every $\ell \in \{1,\ldots,k\}$ where $k$ is the number of COCOA levels of $L(\mc A)$,
  the NCW automaton $\mc A^\ell_N$ can be constructed in $2^{2^{O(n)}}$ time.
\end{lemma}

\begin{proof}
  The lemma follows by observing that
  (1) $\mc A^i_N$ for each $i \in \{1,\ldots,\ell\}$ can be computed in doubly-exponential time,
  (2) there can be at most exponentially many such computations, and
  (3) repeating a doubly-exponential-time computation singly-exponentially many times still yields a doubly-exponential total time.
  The details follow.

  In this proof, ``the size of a structure'' means the number of states in the structure.
  First, we estimate the maximal sizes of the input structures to the definition of $\mc A^\ell_N$.
  The sizes of the canonical SLTMs (for $\mc A$ and $\bar{\mc A}$) are in $\twoexp$;
  the sizes of the saturated obligation graphs are also in $\twoexp$.
  Fix $i \in \{1,\ldots, \ell\}$.
  The size of $\mc A^\ell_N$ is bounded from above by $(M {\,\cdot\,} G)^\ell$,
  where $M$ is the largest among the sizes of the canonical SLTMs for $\mc A$ and $\bar {\mc A}$
    \footnote{\label{footnote:SLTMs-are-the-same}In fact,
    the canonical SLTMs for $\mc A$ and $\bar{\mc A}$ have the same structures (and the same number of states),
    and different labeling functions, but that is not important here.},
  $G$ is the largest among the sizes of the saturated obligation graphs for $\mc A$ and $\bar{\mc A}$.
  The number $\ell \leq k$, and $k$ is singly-exponential in $n$ by Fact~\ref{fact:cocoa-nof-levels}.
  Therefore, regardless of the value $\ell$,
  the size of $\mc A^\ell_N$ is in $\twoexp$,
  i.e.,
  $\exists c. \exists n_0. \forall n > n_0. \forall \ell \in \{1,\ldots,k\}{:}\,
   |\mc A^\ell_N| < 2^{2^{c n}}$.

  For every $\ell \in \{1,\ldots,k\}$, constructing $\mc A^\ell_N$
  from given $\mc A^{\ell-1}_N$, $\mc M$ and $\mc G$ corresponding to $\ell$,
  takes time polynomial in the total size of the the input structures.
  Since we established the upper bound on the input size that holds for all $\ell$,
  we get:
  $\exists \kappa. \exists n_0. \forall n > n_0. \forall \ell \in \{1,\ldots,k\}{:}$
  computing $\mc A^\ell_N$ from given $\mc A^{\ell-1}_N$, $\mc M$, and $\mc G$,
  takes time less than $2^{2^{\kappa n}}$.

  Finally, we compute $\mc A^\ell_N$ by 
  iteratively computing $\mc A^1_N,\ldots,\mc A^\ell_N$.
  For sufficiently large $n$,
  computing $\mc M$ and $\mc G$ (for $\mc A$ and $\bar{\mc A}$) takes time less than $2^{2^{b n}}$,
  computing $\mc A^i_N$ for $i \in \{1,\ldots,\ell\}$ takes time less than $2^{2^{\kappa n}}$,
  there are at most $2^{an}$ such computations,
  where $a,b,\kappa$ are constants,
  therefore the sum of all computation timings is doubly-exponential in $n$,
  and we are done.
\end{proof}


\begin{lemma}\label{lem:AlD}
  The following procedure constructs a deterministic transition-based co-B\"uchi automaton $\mc A^\ell_D$ for the language of the $\ell$th level of the COCOA of a given weak alternating automaton $\mc A$:
  construct $\mc A^\ell_N$ then determinize it into $\mc A^\ell_D$ using the Miyano-Hayashi's construction~\cite{MHConstruction}.
  For automaton $\mc A$ with $n$ states and transition relation at most exponential in $n$,
  the procedure runs in a triply-exponential time in $n$.
\end{lemma}
%%%This lemma follows by observing that,
%%%although the automaton $\mc A^\ell_N$ is of a doubly-exponential size,
%%%the doubly-exponentially contributing component (the SLTM) behaves deterministically,
%%%hence does not incur a blow up during Miyano-Hayashi-zation.

\begin{proof}
  Thanks to Lemmas~\ref{lem:Ll_includes_AlN}, \ref{lem:AlN_includes_Ll}, \ref{lem:AlN-construction-time},
  we only need to prove that applying the breakpoint construction to $\mc A^\ell_N$ takes a doubly-exponential time in $n$.
  %%By Lemma~\ref{lem:AlN-construction-time},
  %%we can construct $\mc A^\ell_N$ within required time bounds,
  %%and by Lemmas~\ref{lem:AlN_includes_Ll} and \ref{lem:Ll_includes_AlN},
  %%it has the language of the $\ell$th level of the COCOA.
  We first describe the breakpoint construction, then reason about the sizes.

  Applying the breakpoint construction to an NCW automaton $\mc A^\ell_N$ yields a deterministic automaton $\mc A^\ell_D$.
  The deterministic automaton $\mc A^\ell_D$ tracks all runs of $\mc A^\ell_N$ on a given word,
  by recording the current states of those runs in its current state.
  Additionally, the automaton $\mc A^\ell_D$ flags each run of $\mc A^\ell_N$ as accepting or rejecting:
  if the run visits only accepting transitions since the last breakpoint moment (described later),
  it is flagged as accepting, otherwise as rejecting.
  When all runs are marked as rejecting,
  the breakpoint moment happens,
  in which case all runs are reset back to accepting.
  The deterministic automaton $\mc A^\ell_D$ declares every transition when the breakpoint happens as a rejecting transition, otherwise it is an accepting transition.
  As a result, the run of the DCW $\mc A^\ell_D$ on a given word is accepting
  if and only if
  the NCW $\mc A^\ell_N$ has an accepting run for this word.
  For more details, see~\cite{MHConstruction}.

  We now reason about the size of $\mc A^\ell_D$.
  Notice that the automata $\mc A^\ell_N$ use the same SLTMs which behave deterministically.
  Thus, when $\ell > 1$,
  a state of $\mc A^\ell_N$ has the form $(q^S_L,q^S_{\bar L},v^1,\ldots,v^\ell)$,
  where:
  $q^S_L$ / $q^S_{\bar L}$ is a state of the canonical SLTM for $\mc A$ / $\bar {\mc A}$
    \footref{footnote:SLTMs-are-the-same},
  and $v^i$ is a vertex of the obligation graph $\mc G$ of [$\mc A$ for odd $i$ / $\bar {\mc A}$ for even $i$],
  for every $i \in \{1,\ldots,\ell\}$.
  When $\ell = 1$, a state has the form $(q^S_L,v^1)$.
  We call the part $\nu = (v^1,\ldots,v^\ell)$ the \emph{combined graph state} of $\mc A^\ell_N$,
  and denote the set of all combined graph states by $\mc{V}$,
  thus $\nu \in \mc{V} = \underbrace{V \x \tilde V \x \ldots}_{\ell \textit{ times}}$,
  where at odd positions we have the set of states of the obligation graph for $\mc A$ and at even -- for $\bar{\mc A}$.
  Applying the breakpoint construction yields a deterministic automaton with states of the form
  \begin{equation*}
  \big(q^S_L, q^S_{\bar L}, \{ \nu_1,\ldots,\nu_a \}, \{\tilde \nu_1,\ldots,\tilde \nu_b)\}\big)
    \in Q^S_L \x Q^S_{\bar L} \x 2^{\mc V} \!\x 2^{\mc V},
  \end{equation*}
  where
  the first set constist of the combined graph states that already visited an accepting state, and
  the second set consists of the combined graph states that are waiting for a visit to an accepting state.
  The sets $V$ and $\tilde V$ have sizes singly-exponential in $n$,
  there might exponentially many levels (Fact~\ref{fact:cocoa-nof-levels}),
  so the number of combined graph states is doubly-exponential in $n$.
  Therefore,
  after applying the breakpoint construction we can get an automaton $\mc A^\ell_D$ of size triply-exponential in $n$.
\end{proof}

We conclude with the main statement.

\begin{theorem}
  \label{thm:ltl-to-cocoa}
  The following procedure constructs the COCOA for a given LDL formula or a weak alternating automaton.
  First,
  convert the formula into a weak alternating automaton using Fact~\ref{fact:LDL-to-Weak}
  (skip this step if the automaton is given).
  Then, for increasing $\ell = 1, 2, \ldots$:
  construct an NCW $\mc A^\ell_N$ according to Definition~\ref{def:nondetAl};
  determinize the NCW $\mc A^\ell_N$ into a DCW $\mc A^\ell_D$ using the Miyano-Hayashi's construction; and
  turn $\mc A^\ell_D$ into the sought GFG-NCW $\mc A^\ell$ by applying the minimization-canonization algorithm of~\cite{DBLP:journals/lmcs/RadiK22}.
  The procedure stops at $\ell$ when $L(\mc A^{\ell+1}) = \emptyset$ and returns the COCOA $(\mc A^1,\ldots,\mc A^\ell)$.
  For an input formula of size $n$,
  and an input automaton $\mc A$ with $n$ states and a transition relation at most exponential in $n$,
  the procedure runs in triply-exponential time in $n$.
\end{theorem}

\begin{proof}
  By Fact~\ref{fact:LDL-to-Weak},
  a given formula $\psi$ can be converted into a weak alternating automaton $\mc A$ of size linear in $|\psi|$.
  By Lemma~\ref{lem:AlD},
  we can construct a DCW $\mc A^\ell$ with the language of $\ell$th level of the COCOA and within the required time bounds.
  The minimization-canonization algorithm of~\cite{DBLP:journals/lmcs/RadiK22} works in polynomial time in the input size and yields the sought $\mc A^\ell$.
  Since the number $\ell$ can be at most exponential in $|\psi|$ (Fact~\ref{fact:cocoa-nof-levels}),
  we are done.
\end{proof}


\subsection{Lower bound for translating from LDL to COCOA}

We now show that translating from LTL (hence LDL) to COCOA takes at least doubly-exponential time.
\begin{proposition}[lower bound]
  \label{prop:COCOA-lower-bound}
  Translating LTL to COCOA requires at least doubly-exponential time:
  there exists LTL formulas $\Phi_1,\Phi_2,\ldots$
  satisfying the following conditions for every number $n$.
  \li
  \- The size of the formula $\Phi_n$ is $O(n)$;
     it is defined over the set of APs of size $O(n)$.
  \- The COCOA recognizing $\Phi_n$ has a size at least $2^{2^n}$,
     where the COCOA size is defined as the total number of states on the individual levels.
  \il
\end{proposition}
The proof is based on the result~\cite{KR11} showing a family of LTL formulas $\Psi_1,\ldots,\Psi_n$ of stated sizes whose smallest deterministic co-B\"uchi automata have doubly-exponential sizes.
These DCWs turn out to be the smallest GFG-NCWs,
and hence their canonical GFG-NCWs also have doubly-exponentially many states.
The COCOA for $\neg \Psi_n$ then contains a single level automaton of doubly-exponential size.
See Section~\ref{proof:prop:COCOA-lower-bound} in the appendix for details.

\section{Translating LDL to Deterministic Parity Automata}

This section describes a procedure to translate a weak alternating automaton into a deterministic parity automaton.
The translation does not rely neither on Safra's\,\cite{DBLP:conf/focs/Safra88} nor Esparza/Kret{\'{\i}}nsk{\'{y}}/Sickert's\,\cite{DBLP:journals/jacm/EsparzaKS20} determinizations;
%and yields deterministic parity automata of asymptotically optimal size;
the produced parity automata accept words with their natural colors.
The idea is to combine deterministic co-B\"uchi automata $\mc A^\ell_D$ described in Section~\ref{sec:WAA-to-COCOA} into one product.
The color in a product transition is the largest $\ell$
such that all co-B\"uchi automata $\mc A^1_D,\ldots,\mc A^\ell_D$ make an accepting transition.
The idea first appeared in \cite{EK24} for translating COCOA into GFG alternating parity automata.

We first recall the definition of deterministic parity automata.
A \emph{deterministic parity automaton} $\mc A = (\Sigma, Q,q_0,\delta)$ over \emph{alphabet} $\Sigma$
consists of a set of \emph{states} $Q$, \emph{initial} state $q_0 \in Q$,
and \emph{transition function} $\delta : Q \x \Sigma \to \bbN \x Q$
that for every state and letter returns a transition \emph{color} and a successor state.
A \emph{run} on an infinite word $x_0 x_1 \ldots$ is an infinite sequence $(q_0,x_0,c_0,q_1) (q_1,x_1,c_1,q_2) \ldots$ such that
$(c_{i+1},q_{i+1}) = \delta(q_i,x_i)$ for every $i$.
Every word has a unique run in $\mc P$.
Given a word $w$,
the \emph{$\mc P$-assigned color} of $w$ is the minimal color appearing infinitely often in the run of $\mc P$ on $w$.
A word is \emph{accepted} by $\mc P$ if the $\mc P$-associated color is even (min-even acceptance).
A co-B\"uchi automaton $\mc C$ can be turned into a parity automaton
by assigning $1$ to the rejecting transitions of $\mc C$ and $2$ to the accepting transitions.

We now define the product.
Given a weak alternating automaton $\mc A$,
let $\mc A^\ell_D = (\Sigma, Q^\ell,q_0^\ell,\delta^\ell,F^\ell)$
be the deterministic co-B\"uchi automaton described in Section~\ref{sec:WAA-to-COCOA},
for every $\ell \in \{1,\ldots,k\}$,
where $k$ is the number of levels in the COCOA for $L(\mc A)$.
We define the following deterministic parity automaton $\mc P = (\Sigma, Q, q_0, \delta)$.
The set of states is $Q = Q^1 \x \ldots \x Q^k$ and the initial state is $q_0 = (q^1_0,\ldots,q^k_0)$.
For every state $(q^1,\ldots,q^k)$ and letter $x$,
the transition function $\delta$ maps $((q^1,\ldots,q^k),x)$ to $(c,(\delta^1(q^1,x),\ldots,\delta^k(q^k,x)))$,
where $c$ is the largest number (including $0$) such that for every $\ell\in \{1,\ldots,c\}$ the transition $q^\ell \trans{x} \delta^\ell(q^\ell,x)$ is accepting (belongs to $F^\ell$).

\begin{theorem}
  Fix a weak alternating automaton $\mc A$ with $n$ states (or an LDL formula $\psi$ of size $n$).
  \li
  \- The deterministic parity automaton $\mc P$ can be built in triply-exponential time
     by first building the automata $\mc A^1_D,\ldots,\mc A^k_D$ as described in Section~\ref{sec:WAA-to-COCOA} and then building their product.

  %\- $\mc P$ has $2^{2^{O(n)}}$ states.

  \- $\mc P$ assigns to a given word its natural color wrt.\ $L(\mc A)$ (or $L(\psi)$) (hence $L(\mc P) = L(\mc A)$).
  \il
\end{theorem}

\begin{proof}
  We show that for every word,
  the $\mc P$-assigned color equals the natural color of the word wrt.\ $L(\mc A)$.
  (Recall that the natural color of a word wrt.\ $L$ is the maximal level of the COCOA containing the word, and
   the word belongs to $L$ if and only if the natural color is even.)
  By Lemma~\ref{lem:AlD},
  the automaton $\mc A^\ell_D$ recognizes the language of the $\ell$th level of the COCOA for $L(\mc A)$.
  Consider a word $w$ with a natural color $c \in \{0,\ldots,k\}$ wrt.\ $L(\mc A)$.
  By definition of the natural color $c$,
  the word $w$ is accepted by $\mc A^\ell_D$ for all $\ell \in \{1,\ldots,c\}$
  and $w$ is rejected by $\mc A^{c+1}_D$ (when $c < k$).
  Thus, eventually the automata $\mc A^1_D,\ldots,\mc A^c_D$ take only accepting transitions,
  whereas $\mc A^{c+1}_D$ (when $c < k$) takes a rejecting transition infinitely often.
  By definition of product transitions,
  in the run of $\mc P$ on the word,
  the color $c$ appears infinitely often, and eventually no color below $c$ appears.
  Thus, the automaton $\mc P$ assigns the color $c$ to the word $w$.
  The other direction follows similarly from the definitions.

  We now evaluate the number of states in $\mc P$.
  The COCOA has $2^{O(n)}$ many levels (Fact~\ref{fact:cocoa-nof-levels}),
  and for each level a deterministic co-B\"uchi automaton of triply-exponential size can be computed in triply-exponential time (Lemma~\ref{lem:AlD}).
  Therefore, the product $\mc P$ has triply-exponentially many states and can be computed in triply-exponential time.
\end{proof}


