\section{Background}
\label{sec:background}
In this section, we review background concepts related to Differential Privacy. 
Readers familiar with these topics can skip it without losing continuity. 

\subsection{Differential Privacy}
Differential Privacy (DP) provides a rigorous framework to control the privacy risk to individuals in a dataset. 
It ensures that the output of a computation, e.g., an answer to a statistical query or inference from a machine learning model, is not significantly affected by the presence/absence of any one individual's data---commensurate to a parameter $\epsilon$.
Over the years, a few variants of the DP definition have been proposed, as reviewed next.

\begin{definition}[\bf Pure DP~\cite{dwork2006differential}]
    \label{def:puredp}
    A randomized mechanism $\mathcal{M} : \mathcal{D} \rightarrow \mathcal{R}$ satisfies \puredp if, for any two adjacent datasets $D, D' \in \mathcal{D}$ and $S \subseteq \mathcal{R}$, it holds:
    \begin{equation*}
        \Pr[\mathcal{M}(D) \in S]  \leq \mathrm{e}^\varepsilon \Pr[\mathcal{M}(D') \in S]
    \end{equation*}
\end{definition}
\noindent Pure DP is defined by a single $\varepsilon$ parameter describing the upper bound on the probability an adversary can distinguish between outputs on two adjacent inputs (cf.~Section~\ref{sec:adj_defns}).

\descr{Approximate DP.}
\approxdp is relaxation of Pure DP that introduces a ``failure probability'' $\delta$, i.e., the probability that the \puredp guarantee does not hold.

\begin{definition}[Approximate DP~\cite{dwork2006our}]
    \label{def:approxdp}
    A randomized mechanism $\mathcal{M} : \mathcal{D} \rightarrow \mathcal{R}$ satisfies \approxdp if, for any two adjacent datasets $D, D' \in \mathcal{D}$ and $S \subseteq \mathcal{R}$, it holds:
    \begin{equation*}
        \Pr[\mathcal{M}(D) \in S]  \leq e^\varepsilon \Pr[\mathcal{M}(D') \in S] + \delta
    \end{equation*}
\end{definition}

\descr{R{\'e}nyi DP (RDP).}
%
\rdp captures a collection of \approxdp guarantees in one definition to more tightly analyze privacy guarantees of DP mechanisms.

\begin{definition}[R{\'e}nyi divergence~\cite{renyi1961measures}]
    \label{def:rdiv}
    For any two probability distributions, $P$ and $Q$, the R{\'e}nyi divergence of order $\alpha > 1$ is:
    \begin{align*}
        D_\alpha(P, Q) & \triangleq \frac{1}{\alpha - 1} \log \mathbb{E}_{x \sim Q} \left(\frac{P(x)}{Q(x)}\right)^\alpha
    \end{align*}
    \mbox{and} %
    $D_1(P, Q) = \lim_{\alpha \rightarrow 1}D_\alpha(P, Q) = \mathbb{E}_{x \sim P}\log \left(\frac{P(x)}{Q(x)}\right)$.
\end{definition}

\begin{definition}[R{\'e}nyi DP~\cite{mironov2017renyi}]
    \label{def:rdp}
    A randomized mechanism $\mathcal{M} : \mathcal{D} \rightarrow \mathcal{R}$ satisfies \rdp if, for any two adjacent datasets $D, D' \in \mathcal{D}$, it holds:
    \begin{equation*}
        D_\alpha(\mathcal{M}(D), \mathcal{M}(D')) \leq \gamma
    \end{equation*}
    where $D_\alpha$ is the R{\'e}nyi divergence of order $\alpha \geq 1$.
\end{definition}
%

\descr{Functional DP (\fdp).}
%
\fdp uses the hypothesis testing interpretation of DP~\cite{kairouz2015composition} (reviewed in Section~\ref{sec:hypo_testing_defn}) to bound the type II error achievable by an adversary aiming to distinguish between the outputs of a DP mechanism on adjacent inputs at a significance level of $\alpha$.
%
A specific instantiation of \fdp is Gaussian Differential Privacy (aka \gdp), for $f = T(\mathcal{N}(0, 1), \mathcal{N}(\mu, 1))$.
%

\begin{definition}[Trade-off function~\cite{dong2019gaussian}]
    For any two probability distributions on the same space, $P$ and $Q$, the trade-off function $T(P, Q): [0, 1] \rightarrow [0, 1]$ is defined as:
    \begin{equation*}
        T(P, Q)(\alpha) \triangleq \inf_{\phi} \{\beta_\phi: \alpha_\phi \leq \alpha\}
    \end{equation*}
    with the infimum taken over all rejection rules $\phi$ for which $\alpha_\phi$ and $\beta_\phi$ are the type I and type II errors, respectively.
\end{definition}

\begin{definition}[Functional DP~\cite{dong2019gaussian}]
    \label{def:fdp}
    A randomized mechanism $\mathcal{M} : \mathcal{D} \rightarrow \mathcal{R}$ satisfies \fdp if, for any two adjacent datasets $D, D' \in \mathcal{D}$, and $\alpha \in [0, 1]$ it holds:
    \begin{equation*}
        T(\mathcal{M}(D), \mathcal{M}(D'))(\alpha) \geq f(\alpha).
    \end{equation*}
\end{definition}

%
%

\subsection{Adjacency}
\label{sec:adj_defns}
%
In the above DP definitions, the notion of adjacent (aka neighboring) datasets is deliberately left generic as it varies depending on the setting.
%
%
%
%
%
We now review three common notions of adjacency: %

\begin{itemize}
\item {\bf\em Add/Remove:} corresponds to inserting or deleting a record from the dataset. 
It is also referred to as ``unbounded DP'' since the dataset size is not the same, i.e., $|D| = |D'| \pm 1$.

\item {\bf\em Edit:} replacing one record with another. 
It is also referred to as ``bounded DP'', i.e., $|D| = |D'|$.
Guarantees under edit adjacency are typically twice as strong as add/remove as one edit corresponds to one remove and one add.

\item {\bf\em Zero-out~\cite{kairouz2021practical}:} introduced to bridge guarantees provided under the add/remove and edit adjacencies and simplify theoretical privacy analyses.
Two datasets are zero-out adjacent if exactly one record in one dataset is replaced with a special \emph{zero-out record}, $\bot$ in the other.
\end{itemize}

\subsection{Sub-Sampling}
A common technique used to amplify a mechanism's DP guarantees and/or make DP compatible with modern machine-learning techniques is known as \emph{sub-sampling}.
More precisely, a mechanism is run iteratively on small, randomly chosen subsets of the input dataset, resulting in substantially improved privacy guarantees compared to running the mechanism on the full dataset.
This is referred to as ``privacy amplification by sub-sampling''~\cite{chaudhuri2006random} and depends on the specific sub-sampling scheme used.
%
We now review four common ones: %

\begin{itemize}
\item {\bf\em Poisson:} at each iteration, each record is chosen with some sampling probability $q$.

\item {\bf\em Sampling w/ (or w/o) replacement:} a batch of $B$ records is chosen, at each iteration, by sampling uniformly at random w/ (or w/o) replacement.
For brevity, we denote these schemes as Sampling WR and WOR, respectively.

\item {\bf\em Shuffling:} the dataset is randomly permuted (shuffled) and then partitioned into $b$ batches of $B$ records.
The batches are iterated over in sequence until the final one is processed, and the dataset is randomly permuted again.

\item {\bf\em Balls-in-bins~\cite{choquette-choo2025nearexact,chua2025ballsandbins}:} each record is uniformly assigned to one of $b$ batches, then, the batches are processed in sequence for each iteration.
After the final batch is processed, the first one is processed again in a round-robin fashion.
\end{itemize}

\subsection{Hypothesis Testing Interpretation of DP}
\label{sec:hypo_testing_defn}
%
%

The notion of hypothesis testing interpretation of DP, introduced in~\cite{kairouz2015composition} for \approxdp, allows to evaluate a mechanism's privacy guarantees based on the difficulty an adversary faces in distinguishing between two adjacent datasets.
Given a random output from a mechanism $y \leftarrow \mathcal{M}(D^*)$ (where $D^* \in \{D, D'\}$ for adjacent $D, D'$), DP can be interpreted as inducing the following a hypothesis test:
\begin{align*}
    H_0: y \sim \mathcal{M}(D) \quad H_1: y \sim \mathcal{M}(D')
\end{align*}

\noindent{\bf Privacy Region.}
For a choice of rejection region $S$, i.e., $H_0$ is rejected if $y \in S$, the type I and type II errors are defined as $P_{\mathrm{FA}}(D, D', \mathcal{M}, S) = \Pr[\mathcal{M}(D) \in S]$ and $P_{\mathrm{MD}}(D, D', \mathcal{M}, S) = \Pr[\mathcal{M}(D') \notin S]$, respectively.
Thus, \approxdp bounds the type I and type II errors as per the following theorem:

\begin{theorem}[\cite{kairouz2015composition}]
    A randomized mechanism $\mathcal{M}: \mathcal{D} \rightarrow \mathcal{R}$ satisfies \approxdp if and only if the following conditions are satisfied for all adjacent datasets $D,D'$ and all rejection regions $S \subseteq \mathcal{R}$:
    \begin{align*}
        & P_{\mathrm{FA}}(D, D', \mathcal{M}, S) + \mathrm{e}^\varepsilon P_{\mathrm{MD}}(D, D', \mathcal{M}, S) \geq 1 - \delta\; \land \\
        & \mathrm{e}^\varepsilon P_{\mathrm{FA}}(D, D', \mathcal{M}, S) + P_{\mathrm{MD}}(D, D', \mathcal{M}, S) \geq 1 - \delta
    \end{align*}
\end{theorem}

This interpretation can also be operationalized, i.e., an analyst can pick a pair of adjacent datasets $D, D'$ and plot the type I and type II errors obtained for different rejection regions $S$.
This will form a ``privacy region'' defined by \approxdp, which %
is often used for DP auditing. 
%



%
%
%

\section{DP Auditing}
\label{sec:dp_audit_defn}
We now discuss the notion of DP auditing -- a set of empirical techniques involving an adversary instantiated against a DP mechanism to distinguish between the mechanism's outputs on adjacent datasets.
We discuss its two main motivating use cases and the desired properties we believe DP auditing algorithms should satisfy.

%
%
%
%

%
%
%
%
%
%
%

%
%

\subsection{Goals of DP Auditing}
\label{sec:goals_of_auditing}

Arguably, the two main goals of DP auditing include: 1) \emph{verifying} that the theoretical guarantees provided by DP are met in practice and 2) \emph{estimating} the actual privacy leakage observed from the mechanism empirically.


\subsubsection{Verifying Privacy Guarantees}

%
%
%
%
%
While the increased adoption of DP in real-world applications~\cite{abowd2022tda,apple2017learning,microsoftiom,mcmahan2022federated,tumult2025tumult,opendp2025opendp} is a promising development for privacy-enhancing technologies, it can often be difficult to implement DP correctly.
Bugs leading to unintended privacy leakage, in some cases completely breaking DP guarantees, have been found in many implementations~\cite{lyu2017understanding,zhang2016privtree,prngreuse,lokna2023group,annamalai2024what,annamalai2024shuffle,ganev2025elusive}.
For instance, Lyu et al.~\cite{lyu2017understanding} and Zhang et al.~\cite{zhang2016privtree} focus on the differentially private Sparse Vector Technique (SVT)~\cite{dwork2009complexity} and show, through manual analysis, that most of its implementations~\cite{roth2011lecture,dwork2014algorithmic,lee2014top,stoddard2014differentially,chen2015differentially,lyu2017understanding} are not differentially private at all.
%

Bugs in the implementation of machine-learning algorithms like Differentially Private Stochastic Gradient Descent (DP-SGD)~\cite{abadi2016deep,prngreuse,annamalai2024shuffle} and DP synthetic data~\cite{annamalai2024what,ganev2025elusive} have also been found through both manual and automated techniques.
However, manual analysis can be error-prone and may miss subtle implementation details, thus prompting the need to scale up automated approaches~\cite{annamalai2024what}.
%

\descr{Limitations of Static Analysis.}
Early work aiming to automatically verify DP guarantees in algorithms' implementations has used static code analysis tools, e.g., type checkers and specialized programming languages.
For example, Reed and Pierce~\cite{reed2010distance} present a type system that enables programmers to write privacy-safe programs by design.
Overall, a large body of work~\cite{barthe2012probabilistic,gaboardi2013linear,barthe2013verified,barthe2015higher,zhang2017lightdp,albarghouthi2017synthesizing,wang2019proving,wang2020checkdp} has focused on making type systems more expressive and efficient.

However, this approach faces some fundamental limitations.
%
First, type systems implicitly trust that some ``basic'' DP algorithms (e.g., Gaussian mechanism, Laplace mechanism) are implemented correctly by the underlying language.
As pointed out in~\cite{lokna2023group}, this may not necessarily be the case if, e.g., the noise addition mechanisms suffer from floating-point vulnerabilities~\cite{mironov2012significance}.
Second, these type systems require mechanisms to be implemented in a very specific language, thus, they are substantially limited to simple algorithms like SVT or Report Noisy Max~\cite{dwork2014algorithmic}. %
Specifically, they struggle to capture the complexities involved in algorithms like RAPPOR~\cite{erlingsson2014rappor} or DP-SGD~\cite{abadi2016deep}.
%

\descr{Enter DP Auditing.}
%
Rather than statically checking %
program specifications, %
DP auditing allows an auditor to run experiments and {\em statistically} refute the theoretical privacy guarantees provided by DP.
In other words, if the auditor fails, programmers and clients can be assured that the implementation satisfies the DP guarantees at some (possibly pre-defined) level of confidence---e.g., for more critical applications, the auditor can perform the test at 99.999\% confidence~\cite{tramer2022debugging} or 95\% for less critical applications~\cite{jagielski2020auditing}.

Overall, DP audits can offer more flexibility than static methods, accommodating more complex algorithms such as private machine learning pipelines~\cite{jagielski2020auditing}.
They are also easier to implement as they do not involve specific programming languages or typing rules.
%
%

%
%
%
%

\subsubsection{Empirical Privacy Estimation}

%
DP auditing can also be useful to provide precise estimates of the privacy leakage in different settings, e.g., vis-\`a-vis different real-world adversaries and/or attacks.

\descr{From Worst-Case to Real-World Adversaries.}
DP provides formal privacy guarantees against powerful theoretical adversaries that are conceivably not always realistic in practice.
In some cases, these strong adversarial assumptions may be needed to provide robust protections that hold in worst-case settings.
In other cases, this may instead be a direct consequence of limited known ways of proving privacy guarantees~\cite{nasr2021adversary}.
For instance, the privacy analysis of DP-SGD~\cite{abadi2016deep} assumes an adversary that has access not only to the final trained model but also to all intermediate models at each training step.
This assumption is not entirely realistic across the board as intermediate parameters are not usually released, %
but needed since theoretical privacy analysis capabilities in this threat model are limited~\cite{feldman2018privacy,chourasia2021differential,ye2022differentially}.
Therefore, DP auditing can be used to empirically estimate privacy leakage in real-world settings~\cite{jagielski2020auditing,annamalai2024s,annamalai2024nearly,nasr2025the,cebere2025tighter}.

In this context, an empirical estimate $\empeps$ can be derived experimentally and then compared against the theoretical bound $\varepsilon$.
This allows to investigate the {\em tightness} of theoretical guarantees~\cite{jagielski2020auditing,nasr2021adversary,nasr2023tight,annamalai2024nearly,mahloujifar2024auditing}, develop theoretical intuitions for improved privacy analyses~\cite{nasr2025the,cebere2025tighter}, and refute widely believed conjectures~\cite{annamalai2024s}.

\descr{Testing Resistance to Different Privacy Attacks.} 
Another use-case of DP auditing stems from its modularity.
DP auditing can be instantiated, e.g., on different adjacency definitions or DP variants or using different attacks.
While the DP definition directly maps to the notion of membership inference (MI), which we review in Section~\ref{sec:attack_defns}, DP guarantees can also be extended to and empirically verified against other attacks such as attribute inference (AI) and reconstruction attacks (Recon)~\cite{yeom2020overfitting,salem2023sok,hayes2023bounding}. 
%
Privacy analyses under more general privacy attacks may not always be optimal, thus, DP auditing can be used to investigate the tightness of the protections provided by DP against them~\cite{hayes2023bounding,mahloujifar2024auditing}.

\subsection{DP Auditing Algorithms}
We now present a formal definition of a DP auditing algorithm, which we use in our systematization to identify relevant papers in this area. %

To ease our definition, we first define an ordering over the space of possible DP guarantees $\mathcal{K}$:
\begin{definition}[Ordering of DP Guarantees]\label{def:dp_order}
    For $\kappa, \kappa' \in \mathcal{K}$, $\kappa \succeq \kappa'$ if $\mathcal{M}$ satisfies $\kappa'$-DP $\rightarrow$ $\mathcal{M}$ satisfies $\kappa$-DP.
\end{definition}
%
\noindent In Pure DP, $\mathcal{K} = \mathbb{R}^+ \cup \{0\}$, $\kappa = \varepsilon$, and the ordering follows the natural ordering of real numbers.

\begin{definition}[DP Auditing Algorithm]\label{def:dp_audit_alg}
    A DP auditing algorithm $\mathcal{A}_{\mathrm{DP}}$ takes in input a $\kappa$-DP mechanism $\mathcal{M}$, the claimed DP guarantees $\tilde{\kappa} \in \mathcal{K}$, and some additional hyper-parameters $\Theta$ and outputs $z \leftarrow \mathcal{A}_{\mathrm{DP}}(\mathcal{M}, \tilde{\kappa}; \Theta)$.\\[0.5ex]
    If $\mathcal{A}_{\mathrm{DP}}$ is used for verification, $z \in \{0, 1\}$ and $\mathcal{A}_{\mathrm{DP}}(\mathcal{M}, \tilde{\kappa}; \Theta) = 1$ if $\tilde{\kappa} \succeq \kappa$. If used for empirical estimation, $z \in \mathcal{K}$ and $\kappa \succeq \mathcal{A}_{\mathrm{DP}}(\mathcal{M}, \tilde{\kappa}; \Theta)$.
\end{definition}

This definition also encodes a notion of ``correctness'' for DP auditing algorithms, which informally states that the output of the algorithm agrees with the actual guarantees satisfied by the mechanism (i.e., if $\mathcal{M}$ satisfies $\kappa$-DP, the algorithm confirms this to be true as well).
However, this definition admits vacuous algorithms (e.g., an algorithm that always outputs `1'); thus, in Section~\ref{sec:desiderata}, we define additional desirable properties of DP auditing algorithms.

%
%
%

\begin{algorithm}[t]
    \small
    \caption{Prototypical Auditing Algorithm}\label{alg:audit_game}
    \begin{algorithmic}[1]
    \Require Mechanism, $\mathcal{M}$. DP Guarantee, $\kappa \in \mathcal{K}$. Data domain, $\mathcal{X}$. Number of runs, $n_{\mathrm{R}}$. Number of canaries, $n_{\mathrm{C}}$. Confidence level, $\alpha$. Privacy attack, $\mathcal{P}$. Evaluation function, $\zeta$.
    \LineComment \textbf{Adversary}
    \State \textbf{Pick dataset:} $D^- \in \mathcal{X}^*$
    \State \textbf{Pick canary distributions:} $\mathcal{C}$
    \State \textbf{Define auxiliary information:} \texttt{aux}
    \BlankLine

    \LineComment \textbf{Challenger}
    \State $Y = [\;]$
    \State $D_{\mathrm{C}} = [\;]$
    \For{$i \in [n_{\mathrm{R}}]$}
        \State $D_{\mathrm{C}}[i] \leftarrow \{x \sim \mathcal{C}[i] | i \in [n_{\mathrm{C}}]\}$
        \State $Y[i] \leftarrow \mathcal{M}(D^- \cup D_{\mathrm{C}}[i];$ \texttt{aux})
    \EndFor
    \BlankLine

    \LineComment \textbf{Adversary}
    \State $O = [\;]$
    \For{$i \in [n_{\mathrm{R}}]$}
        \State $O[i] \leftarrow \mathcal{P}(Y[i]; \mathcal{M}, D^-, \mathcal{C})$
    \EndFor
    \BlankLine

    \State \Return $z \leftarrow \zeta(O; \mathcal{M}, D_{\mathrm{C}}, \mathcal{C}, \alpha, \kappa)$
    \color{black}
    \end{algorithmic}
\end{algorithm}

\descr{Auditing Game.} A DP mechanism is typically audited vis-\`a-vis a \emph{privacy game} played between an \textit{Adversary} and a \textit{Challenger}.
Although this game can slightly vary depending on the auditing goal and threat model, we present the prototypical DP audit algorithm in Algorithm~\ref{alg:audit_game}.

First, the Adversary chooses an initial dataset in the data domain $D^-$
%
and distributions from which special data points used to audit the mechanism, i.e., \emph{canaries}, are sampled from. 
%
The Adversary can also provide additional ``auxiliary'' information to the mechanism if necessary.
%
%
%
Next, the Challenger runs the mechanism $n_{\mathrm{R}}$ times, each time sampling $n_{\mathrm{C}}$ fresh canaries from the canary distributions to form the input dataset.
The Challenger then sends the outputs back to the Adversary.
%
%
The Adversary post-processes the outputs of the mechanism, typically using a privacy attack $\mathcal{P}$.
This is because the outputs of the mechanism may be in an arbitrary domain $y \in \mathcal{Y}$, which can be difficult to design a decision function around (e.g., to decide if the mechanism satisfies the claimed guarantees).
Thus, the post-processing yields simple observations that can be easily analyzed.
%

Finally, the audit's outcome can be computed from the observations using an evaluation function $\zeta$, which outputs either a bit $z \in \{0, 1\}$ for the verification of a theoretical DP guarantee or $z \in \mathcal{K}$ for empirical privacy estimation.
This is typically done by relying on the hypothesis testing interpretation of DP discussed above.
In practice, the outcome of the audit is typically computed with a desired level of confidence $\alpha$, especially when refuting/confirming the claimed DP guarantees of the mechanism.

%

\subsection{Desiderata: The Gold Standard of DP Auditing}
\label{sec:desiderata}
%
%
%

%
Next, we define three key properties we believe audits should satisfy -- \emph{efficiency, end-to-end-ness, tightness}. %
We believe these properties are crucial for the widespread and rigorous adoption of DP auditing, especially in production systems.
As discussed later, achieving all three simultaneously mostly remains an open research problem.
%
%

\descr{Efficiency.}
For DP audits to be deployable in practice, they have to be computationally efficient.
Early work~\cite{ding2018detecting,bichsel2018dp} required implementations to be executed millions of times -- while this is achievable for simple mechanisms (e.g., Laplace and Gaussian mechanisms), it can be prohibitively expensive for complex mechanisms like DP-SGD~\cite{abadi2016deep}.
Therefore, recent work~\cite{steinke2023privacy,mahloujifar2024auditing,galen2024oneshot,xiang2025privacy} has focused on developing auditing techniques that only require implementations to be executed a handful of times, possibly even just once.

\begin{definition}[Efficient Audit]
    A DP auditing algorithm $\mathcal{A}_{\mathrm{DP}}(\mathcal{M}, \kappa; \Theta)$ is efficient if it requires the mechanism $\mathcal{M}$ to be run only a few times (typically once or twice).
\end{definition}
%
%

\descr{End-to-End.} DP audits should also apply to {\em end-to-end} privacy guarantees of the implementations; ideally, these should be run by simply providing inputs to the mechanism and observing its final output.
This is often referred to as ``black-box'' auditing~\cite{liu2019minimax} and reflects realistic threat models encountered in practical settings as opposed to worst-case threat models assumed by the privacy analysis of certain mechanisms.
For instance, the privacy analysis of the DP-SGD~\cite{abadi2016deep} algorithm assumes that all intermediate models are released, even though in practice only the final model may be accessible to the adversary.
Since ``black box'' may have different meanings in different areas (e.g., query-access to machine learning models~\cite{shokri2017membership} vs.~access to fixed generated synthetic data records~\cite{houssiau2022tapas}, etc.), we use the notion of ``end-to-end'' auditing to avoid confusion.

End-to-end audits are also broadly applicable to many mechanisms as they do not require access to \emph{how} they are implemented internally.
%
For example, although different DP mechanisms can be used to train private ML models (e.g., DP-SGD~\cite{abadi2016deep}, PATE~\cite{papernot2017semisupervised}, DP-ZO~\cite{tang2025private}), relying on one single auditing technique that takes in input the training dataset and observe the trained model's outputs would make it significantly easier to integrate auditing into different training pipelines.
Once again, this would also more closely match the capabilities of realistic adversaries. %
%
%

\begin{definition}[End-to-End Audit]
    A DP auditing algorithm $\mathcal{A}_{\mathrm{DP}}(\mathcal{M}, \kappa; \Theta)$ is end-to-end if it does not modify the mechanism $\mathcal{M}$ and performs the audit simply by observing the mechanisms output(s) on specific input(s).
\end{definition}

\descr{Tightness.}
Informally, a \emph{tight} audit means that the empirical audit is consistent with the theoretical privacy analysis.
More precisely, the empirical estimates obtained through auditing should not be far from the theoretical guarantees (e.g., $\empeps \approx \varepsilon$ and $\empdel \approx \delta$).

Moreover, when verifying DP guarantees, tight DP audits would ensure that implementations are successfully verified only if their actual privacy leakage is strictly lower than the theoretical DP bounds.
As a consequence, tight audits are needed in this context to reinforce their accuracy and provide strong confidence in the process.
%
By contrast, a \emph{loose} audit that successfully verifies implementations where the actual privacy leakage is, say, twice the theoretical upper bounds would inherently not be very useful to identify bugs. %
%
%
%

\begin{definition}[Tight Audit]
    A DP auditing algorithm $\mathcal{A}_{\mathrm{DP}}(\mathcal{M}, \kappa; \Theta)$ is tight if it it never underestimates the true privacy parameters, i.e., assuming $\mathcal{M}$ satisfies $\kappa$-DP, $\mathcal{A}_\mathrm{DP}(\mathcal{M}, \kappa; \Theta) = \kappa$ for estimation and $\forall \kappa' < \kappa\; \mathcal{A}_\mathrm{DP}(\mathcal{M}, \kappa'; \Theta) = 0$ for verification.
\end{definition}

