where
\begin{itemize}
\item $a_\xi \in [0 \dots \sum_{h=1}^{t}{(f(G_h)-1)]}$, for $\xi=1, \dots, t-1$;
\item $b_\xi \in [0 \dots f(G_h)-1]$, for $\xi=1, \dots, t$;
