\item $d_{\xi, \sigma} \in [0 \dots \delta_{v_\xi}-\sigma-1]$, for $\xi = 1, \dots, w$ and $\sigma = 1, \dots, b(v_\xi)-2$;
\item $p_\xi \in [0 \dots (\delta(P_\xi)-1)! - 1]$, for $\xi=1, \dots, y$;
