\subsection{Finite Element and Time Discretization} \label{sec:disc}

For the spatial discretization of the incompressible fluid flow problem, we use different pairs of mixed finite elements. 
We partition the domain with characteristic mesh size $h$ into tetrahedra or hexahedra. 
Let $\tau_h:=\tau_h(\Omega)$ denote the triangulation and $\mathcal{P}_k(T)$ and $\mathcal{Q}_k(T)$ polynomial spaces of linear and bi- or trilinear functions, respectively. 
For the partition into tetrahedral elements, we use continuous and either piecewise linear or quadratic functions for the velocity space
\begin{equation*}
	\mathbf{V}^{h}_{Pk} (\Omega) 
	=
	\Big  \{ 
		\mathbf{v}_h \in  \big(C(\Omega)\big)^{d} \cap \big(H^{1}(\Omega)\big)^{d} 
		: 
		\mathbf{v}_h|_{T} \in \big(\mathcal{P}_k(T)\big)^d\ \forall T \in \tau_h
	\Big\},\ k\in\{1,2\}.
\end{equation*}
Similarly, we can define the velocity space for hexahedral elements,
\begin{equation*}
	\mathbf{V}^{h}_{Qk} (\Omega) 
	=\Big \{ 
		\mathbf{v}_h \in \big(C(\Omega)\big)^{d} \cap \big(H^{1}(\Omega)\big)^{d} 
		: 
		\mathbf{v}_h|_{T} \in \big(\mathcal{Q}_k(T)\big)^d\ \forall T \in \tau_h 
	\Big\},\ k\in\{1,2\}. 
\end{equation*}
The continuous and piecewise linear pressure spaces for the different partitions are defined as
\begin{align*} 
Q^h_{P1}  (\Omega) &=\Big \{ q_h \in C(\Omega) \cap L^2(\Omega): q_h|_{T} \in \mathcal{P}_1(T)\ \forall T \in \tau_h\Big \},\\ 
Q^h_{Q1}  (\Omega) &=\Big \{ q_h \in C(\Omega) \cap L^2(\Omega): q_h|_{T} \in \mathcal{Q}_1(T)\ \forall T \in \tau_h\Big \}.
\end{align*}
Additionally, we consider the combination of Q2--P1-disc., where the pressure space consists of discontinuous piecewise linear functions:
\begin{equation*}
Q^h_{\text{P1-disc.}} (\Omega)  =\Big \{ q_h \in  L^2(\Omega): q_h|_{T} \in \mathcal{P}_1(T)\ \forall	T \in \tau_h\Big \}.
\end{equation*}
If the type of element is unspecified, we write $\mathbf{V}^h$ and $Q^h$ for the velocity and pressure space, respectively. 
Let $\mathbf{u}_h \in \mathbf{V}^{h}$ and $p_h \in Q^h$ be the approximations of the solutions $\mathbf{u}$ and $p$. 
Then the resulting variational formulation is as follows: Find $\mathbf{u}_h \in \mathbf{V}^{h}$ and $p_h \in Q^h$ such that 
\begin{align*}
\nu \!\int_\Omega \!\!\nabla \mathbf{u}_h \!:\!\nabla \mathbf{v}_h\dx 
+\!\! \int_\Omega \!((\mathbf{u}_h \cdot \nabla) \mathbf{u}_h) \cdot \mathbf{v}_h \dx 
-\!\! \int_\Omega \! p_h (\nabla \cdot \mathbf{v}_h)\dx 
&= \!\! \int_\Omega \!\mathbf{f} \cdot \mathbf{v}_h \dx 
&\forall \mathbf{v}_h \in \mathbf{V}^{h}, \\
\int_{\Omega} \! q_h (\nabla \cdot \mathbf{u}_h)\dx 
&= 0  
& \forall q_h \in Q^h.
\end{align*}
We denote by $\bm{\varphi}_1,\dots,\bm{\varphi}_{N_u}$ the finite element basis of $\mathbf{V}^{h}$ and by $\psi_1,\dots,\psi_{N_p}$ the basis of $Q^h$. Then, we can write
\begin{equation*}
\mathbf{u}_h(x) = \sum_{i=1}^{N_u} u_i \bm{\varphi}_i(x)\ \text{ and }\ p_h(x) = \sum_{i=1}^{N_p} p_i \psi_i(x).
\end{equation*}
We will also refer to the corresponding coefficient vectors of $\mathbf{u}_h(x)$ and $p_h(x)$ by $\mathbf{u}_h$ and $p_h$, respectively. 
We define the following matrix operators corresponding to the weak formulation,
\begin{align*}
A &= [a_{ij}], 
& \! B&=[b_{ij}], 
& \! N(\mathbf{u}_h) &= [n_{ij}(\mathbf{u}_h)], \\
a_{ij} &= \int_\Omega  \nabla \bm{\varphi}_i : \nabla \bm{\varphi}_j \dx, 
& \! b_{ij} &= -\!\int_\Omega \psi_i (\nabla \cdot \bm{\varphi}_j) \dx, 
& \! n_{ij}(\mathbf{u}_h) &= \int_\Omega ((\mathbf{u}_h \cdot \nabla) \bm{\varphi}_j)\cdot \bm{\varphi}_i\dx,
\end{align*}
and obtain with the discretization $\mathbf{f}_u$ of $\mathbf{f}$ the system of linear equations for the stationary Navier--Stokes equations,
\begin{equation}\label{Eq: NS Steady nonlinear}
\begin{bmatrix}
F_O(\mathbf{u}_h) & B^{T} \\
  B        & 0
\end{bmatrix}
\begin{bmatrix}
\mathbf{u}_h \\
p_h
\end{bmatrix}
=
\begin{bmatrix}
\mathbf{f}_u \\
0
\end{bmatrix},
\end{equation}
with $F_O(\mathbf{u}_h) = \nu  A +  N(\mathbf{u}_h)$. 
The resulting Picard iteration with the iterates $\mathbf{u}_h^k$ and $p_h^k$ reads \cite[p.~346]{Elman_fluid_book}
\begin{equation*}
\begin{bmatrix}
F_O(\mathbf{u}_h^k) & B^{T} \\
  B        & 0
\end{bmatrix}
\begin{bmatrix}
\mathbf{u}_h^{k+1} \\
p_h^{k+1}
\end{bmatrix}
=
\begin{bmatrix}
\mathbf{f}_u \\
0
\end{bmatrix},
\end{equation*}
defining the discretized Oseen problem. 
We apply the Newton method to solve the nonlinear problem:
\begin{equation*}
\begin{aligned}
&\text{Solve: } & \Jacobian(X^k) \delta X^{k} &= -\Residual(X^k), \\
&\text{Update: } & X^{k+1} &= X^k + \delta X^k,
\end{aligned}
\end{equation*}
where the $\delta$ notation is defined as $\delta X^k := X^{k+1}- X^k$. 
The Newton residual $\Residual$ for the stationary case is defined as
\begin{equation*}
\Residual_{\text{stat}}
\left(
\mathbf{u}_h^k,
p_h^k
\right)
= 
\begin{bmatrix}
F_O(\mathbf{u}_h^k) & B^{T} \\
  B        & 0
\end{bmatrix}
\begin{bmatrix}
\mathbf{u}_h^{k} \\
p_h^{k}
\end{bmatrix}
-
\begin{bmatrix}
\mathbf{f}_u \\
0
\end{bmatrix}.
\end{equation*}
We need to linearize \cref{Eq: NS Steady nonlinear} by adding an additional term $W(\mathbf{u}_h^k)$ to $F_O(\mathbf{u}_h^k)$ from the derivative of the convection term:
\begin{equation*}
W(\mathbf{u}_h^k)
= [w_{ij}(\mathbf{u}_h^k)],
\quad
w_{ij}(\mathbf{u}_h^k)
= \int_\Omega ((\bm{\varphi}_j \cdot \nabla) \mathbf{u}_h^{k})\cdot \bm{\varphi}_i \dx,
\end{equation*}
with the velocity solution from the previous $k$th Newton step $\mathbf{u}_h^{k}$. 
This leads to 
\begin{equation*}
\Jacobian
\left(
\mathbf{u}_h^k
\right)
\begin{bmatrix}
\delta \mathbf{u}_h^{k} \\
\delta p_h^{k}
\end{bmatrix} = 
\begin{bmatrix}
F_N(\mathbf{u}_h^{k})  & B^{T} \\
  B & 0 
\end{bmatrix}
\begin{bmatrix}
\delta \mathbf{u}_h^{k} \\
\delta p_h^{k}
\end{bmatrix}
=
-
\Residual_{\text{stat}}
\left(
\mathbf{u}_h^k,
p_h^k
\right),
\end{equation*}
%
with $F_N(\mathbf{u}_h^k) = F_O(\mathbf{u}^k_h) + W(\mathbf{u}_h^{k})$.
For transient problems we include the BDF-2 time discretization \cite{BDF2} and expand the system to 
%
\begin{equation}\label{Eq: Sys with BDF2}
    \Jacobian\!
    \left(
    \mathbf{u}_h^{k,n+1}
    \right)
    \!
    \begin{bmatrix}
    \delta \mathbf{u}_h^{k,n+1} \\
    \delta p _h^{k,n+1}
    \end{bmatrix}
=
    -\Residual_{\text{stat}}\!
    \left(
    \mathbf{u}_h^{k,n+1},
    p_h^{k,n+1}
    \right)
    + 
    \begin{bmatrix}
    \frac{2}{\Delta t} M_u \mathbf{u}_h^{n} - \frac{1}{2\Delta t}M_u \mathbf{u}_h^{n-1}\\
    0
    \end{bmatrix}\!,
\end{equation}
where $M_u$ is the velocity mass matrix, $\mathbf{u}_h^n$ and $\mathbf{u}_h^{n-1}$ are the solutions to the last two time steps, and 
\begin{equation*}
    \Jacobian\!
    \left(
    \mathbf{u}_h^{k,n+1}
    \right)
    =
    \begin{bmatrix}
    \frac{3}{2\Delta t_n} M_u +F_N(\mathbf{u}_h^{k,n+1}) & B^{T} \\
    B & 0 
    \end{bmatrix}.
\end{equation*}
%
The resulting saddle-point problem for the different discretizations has the generic form
\begin{equation}\label{Eq: Saddle point problem Navier Stokes}
	\mathcal{F} := \begin{bmatrix}
	F & B^{T} \\ B & -C 
	\end{bmatrix},
\end{equation}
where the fluid component $F$ depends on the underlying problem setting, and $C\neq 0$ in case of a discretization that is not inf-sup stable.

We focus on three-dimensional problems for which the P2--P1, Q2--Q1, and Q2--P1-disc. finite element pairs satisfy the inf--sup condition; cf. \cite{Boffi_MixedFE_2013}.
In case of the non inf-sup stable finite elements P1--P1 and Q1--Q1, the Bochev--Dohrmann stabilization \cite{Dohrmann_stabilization_2004} is used, which penalizes nonphysical pressure variations by inserting a pressure term into the conservation of mass equation (see \cite[Sect.~2]{Dohrmann_stabilization_2004} and \cite[Sect. 5.6.1]{diss_hochmuth_2020}). 
Its bilinear form reads
\begin{equation*}
C(p,q) = \frac{1}{\nu} \int_{\Omega} (p-\rho_0 p) ( q-\rho_0 q)\dx \quad \forall q \in L^2(\Omega),
\end{equation*}
where $\rho_0$ is an $L^2$-orthogonal projection onto the space $\mathcal{P}_0(\tau_h)$ of discontinuous, piecewise constant functions;
the projection is given by 
\begin{equation*}
(\rho_0 q)|_T = \left(\int_T 1\dx\right)^{-1} \int_T q \dx\quad\forall T\in\tau_h(\Omega),
\end{equation*}
which can be computed efficiently due to its independent definition on each element $T\in\tau_h(\Omega)$.

As a measure that indicates how much information travels through a computational grid cell in a unit of time, that is, which relates the velocity of transport, time step, and mesh resolution, we define a Courant(--Friedrichs--Lewy)-type number (CFL) for structured meshes as 
\begin{equation*}
\CFL(t) 
= \frac{u^h_\infty(t) \Delta t}{h}, 
\quad u^h_\infty(t)
=\max_{x^h\in\tau_h(\Omega)} \|\mathbf{u}_h(x^h,t)\|_2,
\end{equation*}
where $x^h$ is a finite element node. 
For an unstructured mesh, we take varying element sizes and shapes into account and use 
\begin{align*}
\CFL(t)
&= \max_{T\in\tau_h(\Omega)} \CFLinT(t), \\
	 \CFLinT(t) &= \frac{u^h_\infty(T,t) \Delta t}{d_I(T)}\quad\qquad \text{ with }
	 u^h_\infty(T,t) = \max_{x^h\in T} \|\mathbf{u}_h(x^h,t)\|_2,
\end{align*}
where $T\in\tau_h(\Omega)$ is a finite element, and $d_I(T)$ is the diameter of the largest incircle of~$T$. 

We will also use the average of $\CFLinT(t)$ over all elements $T\in\tau_h(\Omega)$, denoted by $\CFLavg(t)$. 
By $\CFL$ and $\CFLavg$, we refer to the corresponding maximum CFL number over time.
In case the CFL number is too large, instability or unphysical behavior may be encountered. 
Generally, implicit time stepping schemes are more stable with respect to the CFL number. 
High CFL numbers tend to be more demanding for preconditioners; see, for example, \cite[Fig.~9]{Cyr_teko_stabilized} and \Cref{figure: Iterations CFL comparison,figure: Iterations RE transient}.

