\section{Word languages and transductions}
\label{sec:prel}

We let $\mathcal{P}(X)$ the powerset of any set $X$. 

\paragraph{Words and languages} Given an alphabet $\Sigma$, a
$\Sigma$-word $u$ (or just word if $\Sigma$ is clear from the context) is a sequence of letters from
$\Sigma$. We denote by $\epsilon$ the empty word, and by $|u|$ the
length of a word $u$. In particular $|\epsilon|=0$. For all integers
$n\geq 0$, we let $\Sigma^n$ (resp. $\Sigma^{\leq n}$) be the set of
words of length $n$ (resp. at most $n$). We let $\pos(u) =
\{1,\dots,|u|\}$ be the set of \emph{positions} of $u$, and for all
$i\in\pos(u)$, $u[i]\in\Sigma$ is the $i$-th letter of $u$. We write
$\Sigma^*$ for the set of words over $\Sigma$, and $\Sigma^+$ for the
set of non-empty words. A word language over $\Sigma$ is a subset of
$\Sigma^*$. \emph{In this paper, we let $\sep$ be a symbol called
  separator, assumed to be distinct from any alphabet symbol.}



\paragraph{Convolution} Let $\Sigma_1,\Sigma_2$ be two alphabets,  $\ell\in\nat$
and $u_1\in\Sigma_1^\ell,u_2\in\Sigma_2^\ell$ be two words of length $\ell$. The \emph{convolution} of $u_1$ and $u_2$ is the word
of length $\ell$ over $\Sigma_1\times \Sigma_2$ denoted $u_1\otimes
u_2$, such that for all $1\leq i\leq \ell$, $(u_1\otimes u_2)[i] =
(u_1[i],u_2[i])$. 




\paragraph{Finite automata} A (non-deterministic) finite automaton (NFA) over an alphabet $\Sigma$ is denoted as a tuple $A=(Q, q_0, F, \Delta)$ where $Q$ is the set of states, $q_0$ the initial state, $F\subseteq Q$ the final states, and $\Delta\subseteq Q\times \Sigma\times Q$ the transition relation. We write $q\xrightarrow{u}_A q'$ when there exists a run of $A$ from state $q$ to state $q'$ on $u$, and denote by $L(A) = \{ u{\in}\Sigma^*\mid q_0\xrightarrow{u}_A q_f\in F\}$ the language recognized by $A$. When $A$ is a deterministic finite automaton (DFA), the transition relation is denoted by a (partial) function $\delta : Q\times \Sigma \partialf Q$.


\paragraph{Word transductions} A \emph{word transduction} (or just transduction for short) over $\Sigma,\Gamma$ two alphabets is a (partial) function $f : \Sigma^*\partialf \Gamma^*$. We denote by $\dom(f)$ its domain. Given two transductions
$f_1,f_2:\Sigma^*\partialf \Gamma^*$ with disjoint domains, we
let $f_1+f_2$ be the transduction of domain $\dom(f_1)\cup \dom(f_2)$
such that $(f_1+f_2)(u) = f_i(u)$ if $u\in \dom(f_i)$. 
Given $f : \Sigma^*\partialf \Gamma^*$, $g:\Gamma^*\partialf \Lambda^*$, we write $(g\ f) : \Sigma^*\partialf \Lambda^*$ the composition $g\circ f$. Given  $h:\Lambda^*\partialf \Delta^*$, $(h\ g\ f)$ stands for $(h\ (g\ f))$. For $u\in\Sigma^*$, we also write $(h\ g\ f\ u)$ for $(h\ g\ f)(u)$.

A transduction $f$ has \emph{exponential growth} if there exists $c\in\mathbb{N}$ such that for all $u\in\dom(f)$, $|f(u)|\leq 2^{c|u|}$ holds.
A transduction $f$ has \emph{polynomial growth} if there exists $c,k\in\mathbb{N}$ such that for all $u\in\dom(f)$, $|f(u)|\leq c|u|^k$ holds.

\begin{example}[Reverse and copy]
Let $\Sigma$ be an alphabet. The transduction $\rev:\Sigma^*\rightarrow\Sigma^*$ takes as input any word  
$u=\sigma_1\dots \sigma_n$ and outputs its reverse $\sigma_n\dots \sigma_1$,  for all
    $\sigma_i\in\Sigma$. The transduction $\textsf{copy}$ takes $u$ and returns $uu$. 
\end{example}



\begin{example}[Square]\label{ex:squareex}
    Let $\Sigma$ be an alphabet and $\underline{\Sigma} =
    \{\underline{\sigma}\mid \sigma\in\Sigma\}$. Given a word $u=\sigma_1\dots\sigma_n$ and
    a position $i\in\pos(u)$, we let $\textsf{under}_i(u) =\sigma_1\dots
    \sigma_{i{-}1}\underline{\sigma_i}\sigma_{i+1}\dots \sigma_n$.
The transduction
    $\square:\Sigma^*\rightarrow (\Sigma\cup\underline{\Sigma})^*$ is
    defined as
    $\square(u) = \textsf{under}_1(u)\dots \textsf{under}_{|u|}(u)$.
    For example $\square(abc) =
    \underline{a}bca\underline{b}cab\underline{c}$.
\end{example}


\begin{example}[Map]\label{ex:map}
Let $\Sigma$ be some alphabet and $|\not\in \Sigma$ be some
    separator symbol. Let $\Sigma_\sep = \Sigma\cup \{\sep\}$. 
Let $f : \Sigma^*\partialf\Gamma^*$. The transduction $\map\ f:\Sigma_|^*\partialf \Sigma_|^*$ takes any input word of the
    form $u = u_1\sep u_2\sep\dots \sep u_n$ where $u_i\in\Sigma^*$ for all
    $i\in\{1,\dots,n\}$, and returns $f(u_1)\sep f(u_2)\sep\dots
    \sep f(u_n)$ (if all the $f(u_i)$ are defined, otherwise $(\map\ f)(u)$ is undefined.
\end{example}



\paragraph{Sequential and rational transductions} Sequential transductions are transductions recognized by sequential transducers. A \emph{sequential transducer} over some alphabets $\Sigma$ and $\Gamma$ (not necessarily disjoint), is a pair $T = (A, \out)$ where $A = (Q,q_0,F,\delta)$ is a DFA over $\Sigma$ and $\out : \dom(\delta)\rightarrow \Gamma^*$ is a total function. We write $q\xrightarrow{u/v}_T q'$ whenever there exists a sequence of states $q_1=q, q_2,\dots, q_{n+1} = q'$ such that
$q_1\xrightarrow{u[1]}_A q_2\dots q_n\xrightarrow{u[n]}_A q_{n+1}$
where $n=|u|$, and $v = \out(q_1,u[1])\dots \out(q_n,u[n])$. The
transduction $f_T$ recognized by $T$ is defined for all $u\in L(A)$ by
$f_T(u) = v$ such that $q_0\xrightarrow{u/v} q_f\in F$. Note that
$\dom(f_T) = L(A)$. We denote by $\SEQ$ the class of sequential
transductions. Like sequential transducers, a (non-deterministic, functional)
\emph{finite state transducer}\footnote{This class is also called
  real-time finite state transducers in the literature.}
  is defined as a pair $T = (A,\out)$ but
$A$ can be non-deterministic, with the \emph{functional} restriction: for all words
$u\in L(A)$, the
outputs of all the accepting runs over $u$ are all equal. With this
restriction, $T$ recognizes a transduction $f_T$. A \emph{rational}
transduction is a transduction $f_T$ for some $T$, and we denote by
$\RAT$ the class of rational transductions~\cite{DBLP:books/ems/21/HarjuK21}.

\paragraph{Regular and polyregular transductions} The class of
regular (resp. polyregular) transductions is defined as the smallest class of
transductions which is closed under composition of transductions and
\map, and contains the sequential transductions, \textsf{copy} and \rev (resp. the sequential
transductions, \rev and
\square)~\cite{DBLP:conf/icalp/BojanczykS20,DBLP:polyreg}. We denote by \textsf{PolyReg} the class of polyregular transductions.




\section{\MSO set interpretations, properties and limitations}
\label{sec:msosi}
\subsubsection{\MSO set interpretations}

\paragraph{Signatures, formulas and structures} 
A \emph{relational signature} (or simply signature) is a set $\sign$ of symbols together with a function $\arity: \sign\rightarrow \nat$.

We consider a set of \emph{first-order variables} denoted by lower case letter $x,y,z,\ldots$ as well as a set of \emph{second-order variables} denoted by upper case letter $X,Y,Z\ldots$.
The \MSO-formulas over signature $\sign$, denoted by $\MSO [\sign] $
are given by the following grammar $\phi::=$
$$\exists x \phi \mid \exists X \phi \mid  \phi\wedge \phi \mid \neg \phi \mid X(x) \mid R(x_1,\ldots,x_r)$$

%$$\exists x \phi\ |\ \exists X \phi\ |\ \forall x \phi\ |\ \forall X \phi \ |\ \phi\wedge \phi \ |\ \phi\vee\phi\ |\ \neg \phi\ |\ X(x)\ |\ R(x_1,\ldots,x_r)$$


where $x,x_1,\ldots, x_r$ are first-order variables, $X$ is a second-order variable and $R\in \sign$ with $\arity(R)=r$.
We denote by $\FO[\sign]$ the formulas which don't use second-order variables.


A \emph{relational structure} $u$ over signature $\sign$ is a set $U$ called the \emph{universe} of the structure, together with, for each symbol $R\in\sign$ of arity $r$, an \emph{interpretation} denoted $R^u$ which is a subset of  $U^r$.

\paragraph{Regularity preserving} A function from $\sign$-structures to $\signout$-structures is called \emph{regularity preserving} if the inverse image of an $\MSO[\signout]$ definable set is $\MSO[\sign]$ definable. We say that a class of functions is regularity preserving if all functions in the class are.

\paragraph{Word structures} The \emph{word signature over $\Sigma$} is the tuple $S_\Sigma =
((\sigma(x))_{\sigma\in \Sigma}, \leq(x,y))$ where $\sigma(x)$ are unary
predicate symbols and $\leq(x,y)$, usually written $x\leq y$, is a
binary predicate symbol. Any word $u$ can be naturally associated with
an $S_\Sigma$-structure $\tilde{u} = (U,(\sigma^{\tilde{u}})_{\sigma\in\Sigma},\leq^{\tilde{u}})$ where
$U = \pos(u)$, $\sigma^{\tilde{u}}$ is a set of positions labeled $\sigma$, for
all $\sigma\in\Sigma$, and $\leq^{\tilde{u}}$ is the natural (linear) order on
$\pos(u)$.  We write $u$ instead of $\tilde{u}$ if it is clear from the
context that $u$ is an $S_\Sigma$-structure. A \emph{word structure} over $\Sigma$ is an
$S_\Sigma$-structure isomorphic to some $\tilde{u}$. 
Note that being a word structure is \FO definable.

