\subsubsection{Automatic transductions}
We describe an automata-based presentation of \MSOSI, which we call \emph{automatic transductions}. This presentation has two main advantages: firstly it is more amenable to efficient processing, as it is based on automata instead of \MSO. Secondly it makes the connection between automatic structures and set interpretations more obvious.



 \begin{definition}
 An automatic transduction (\AT for short) from $\Sigma^*$ to $\signout$-structures is described as a tuple $T=(\Sigma,B,\aut_\dom,\aut_\univ, (\aut_R)_{R\in \sign})$
 where:
 \begin{itemize}
 \item $B$ is a finite alphabet describing a work alphabet
 \item $\aut_\dom$ is an automaton over $\Sigma$ recognizing the domain of the transduction,
 \item $ A_\univ$ is an automaton over $\Sigma\times B$ describing the possible configurations,
 \item for each $R\in \sign$ of arity $r$, $\aut_R $ is an automaton over $\Sigma\times B^r$ describing tuples of the relation $R$.
 \end{itemize}


 \noindent\emph{Semantics} Given a word $u\in \Sigma^*$, the output $\signout$-structure $v=f_T(u)$ is defined, whenever $u\in L(\aut_\dom)$, as follows:
 \begin{itemize}
     \item its universe is the set $V=\set{x\in B^*|\ u\otimes x\in L(\aut_\univ)}$,
     \item a predicate symbol $R\in \signout$ of arity $r$ is interpreted as:

     $R^v=\set{(x_1,\ldots, x_r)\in V^r|u\otimes x_1\otimes \ldots \otimes x_r\in L(\aut_R)}$.
 \end{itemize}

  \end{definition}


\begin{remark}~


\begin{itemize}
    \item Automatic transductions are essentially identical to \MSOSI, except restricted to input word structures, where one can leverage the classical equivalence between \MSO and automata.

    \item Automatic transductions can be naturally generalized to work over input structures such as $\omega$-words, trees and infinite trees, giving rise the notions of $\omega$-automatic, tree-automatic and $\omega$-tree-automatic transductions.
    Note that an $\omega$-automatic structure is precisely an $\omega$-automatic transduction whose domain is a single infinite word $a^\omega$.
    \end{itemize}
\end{remark}

\subsubsection{Transduction/structure correspondence}
\label{subsec:msosi}
Here we give a rather natural correspondence between word-to-word automatic transductions and automatic $\omega$-words.

We use definitions inspired from \cite{DBLP:journals/ita/Barany08}. We extend the convolution operation to words of different lengths by adding a padding symbol $\pad$ to the right of the shortest word until the lengths match.

\begin{definition}

An \emph{automatic structure} over the signature $\signout$ is given by a tuple $S=(B,\aut_\univ,(\aut_R)_{R\in  \sign})$, $\aut_\univ$ is an automaton over alphabet $B$ and for $R\in \sign$ of arity $r$, $\aut_{R}$ is an automaton over the alphabet $(B{\cup}\set{\pad})^r$. The structure $u$ associated with $S$ has universe $U=L(\aut)$, the interpretation of $R\in \sign$ is the set $R^u=\set{(x_1,\ldots,x_r)\in V^r|\ x_1\otimes \cdots \otimes x_r\in L_R}$.
An automatic structure which is an $\omega$-word structure over some alphabet is called an automatic $\omega$-word.
\end{definition}


\paragraph{Length monotonous} An automatic presentation of an $\omega$-word is \emph{length monotonous} if shorter words always appear before longer words with respect to the linear order. It turns out that any automatic $\omega$-word can be presented in a length monotonous way: this is done by adding an extra padding letter $\sharp$, and padding any word $v$ with enough symbols so that it is longer than any word appearing before in the order. The proof of this is rather simple and left to the reader. In the following, we shall assume that all automatic presentations of $\omega$-words are length monotonous.

Given a total transduction over a unary alphabet $f:a^*\rightarrow \Sigma^*$, we define its \emph{product} $\Pi f=f(\varepsilon)\cdot f(a)\cdot f(aa)\cdots$. Note that $\Pi f$ may be a finite word.

\begin{proposition}\label{prop:corr}
    There is a one-to-one correspondence between length monotonous automatic presentations of $\omega$-words and total automatic transductions from finite words over a unary alphabet to finite words. Moreover, when an automatic $\omega$-word $w$ corresponds to a function $f$, then $w=\Pi f$.
\end{proposition}
\begin{proof}
    Let $S=(\aut_\univ,(\aut_\sigma)_{\sigma\in \Sigma},\aut_{\leq})$ be a length monotonous automatic presentation of a word $w$.
    Since $S$ is length monotonous, we only care about the part of $\aut_{\leq}$ which reads letters over $B\times B$, and we define $\aut_{\leq}'$ the automaton obtained by removing transitions which use a $\pad$ padding symbol.

    We define the automatic transduction over $\set{a}$, $T=(\top,\aut_\univ,(\aut_\sigma)_{\sigma\in \Sigma},\aut_{\leq}')$ realizing a transduction $f$. By construction, $w=\Pi f$.

    Conversely, let $T=(\top,\aut_\univ,(\aut_\sigma)_{\sigma\in \Sigma},\aut_{\leq})$ realize a total transduction $f:\set{a}\rightarrow \Sigma^*$. If $\aut_{\leq}$ is over $B\times B$, we extend it to an automaton $\aut_{\leq}$ in a length monotonous way to convolutions of words of possibly different lengths.
    Again by construction the automatic $\omega$-word $w$ presented by $S=(\aut_\univ,(\aut_\sigma)_{\sigma\in \Sigma},\aut_{\leq}')$ satisfies $w=\Pi f$.

    The two constructions are indeed inverse of each other.
\end{proof}

We can now prove that if Conjecture~\ref{conj:mso} holds then Conjecture~\ref{conj:automso} also holds.


\begin{corollary}\label{coro:conje}
    If word-to-word \MSOSI are regularity preserving, then automatic $\omega$-words have a decidable \MSO theory\footnote{One could actually prove the stronger implication that any automatic $\omega$-word has a canonical presentation, as in \cite{DBLP:journals/ita/Barany08}.}.
\end{corollary}
\begin{proof}
    Assume that word-to-word \MSOSI are regularity preserving.
    Let $u\in \Sigma^\omega$ be an automatic $\omega$-word and let $L\subseteq \Sigma^\omega$ be a regular language.
    We define $f:\set{a}^*\rightarrow \Sigma^*$ the automatic transduction given by Proposition~\ref{prop:corr}.


    Let $\aut$ be a Büchi automaton recognizing $L$, let $Q$ be the set of states, $q_0$ the initial state and $F\subseteq Q$ be the set of accepting states.
    For $p,q\in Q$, we define $L_{p,q}^1$ the set of finite words which have a run from $p$ to $q$ visiting at least one final state and $L_{p,q}^0$ the set of finite words which have a run from $p$ to $q$ visiting no final state.
    We define a formula which starts with a block of existential quantification over variables $X_p^b$ with $p\in Q$ and $b\in \set{0,1}$. 
    The idea is that an integer $x$ will belong to $X_p^b$ if there is a run of $\aut $ over $\Pi_{i\leq x}f(a^i)$ which ends in state $p$ and sees at least $b$ final state \emph{after} having read  $\Pi_{i< x}f(a^i)$.
    The formula will be a conjunction of four parts: firstly all the $X_p^b$'s are pairwise disjoint. Secondly there is a $p$ and an infinite set of positions $x$ such that $X_p^1(x)$ holds.
    The third part is here to ensure that for the minimal $x$, if $X_p^b(x)$ then $f(a^1)\in L_{q_0,p}^b$ can reach state $p$ by visiting at least $b$ final states. It is a conjunction for all $p\in Q$, $b\in \set{0,1}$ of $\forall x\  (X_p^b(x)\wedge \forall y\ x\leq y) \rightarrow f(a)\in L_{q_0,p}^b$. Here $f(a)\in L_{q_0,p}^b$ is simply a boolean which can be computed.
    The last part of the formula will be the conjunction for all $p,q\in Q$, $b,c\in \set{0,1}$ of $\forall x\ X_p^b(x)\wedge X_q^c(x+1) \rightarrow f(a^x)\in L_{p,q}^c$.
    The fact that $f(a^x)\in L_{p,q}^c$ is definable in \MSO comes from the assumption that \MSOSI are regularity preserving.


    We have transferred an \MSO property of $u$ to an \MSO property of $(\nat,<)$, which is decidable.
\end{proof}



\section{Lexicographic transductions}\label{sec:lex}

As we have seen in the latter section, we do not know whether $\MSOSI$
are regularity preserving, and as a consequence of
Corollary~\ref{coro:conje}, proving that it enjoys this property
would prove a long-standing conjecture of the theory of automatic
structures. In this section, we introduce a subclass of \MSOSI transductions which
enjoys this property, called
\emph{lexicographic transductions}.

\subsubsection{Definition of lexicographic transductions}

We first define this class in
terms of closure of basic transductions, called \emph{simple
  transductions}, under a \emph{lexicographic map} operation. The
connection with \MSOSI is done at the end of this section (paragraph~\ref{subsec:lexaut}), via a
corresponding subclass of automatic transductions. 

\paragraph*{Simple transductions}
A  \emph{regular constant} (partial) transduction of type $\Sigma^*\partialf \Gamma^*$ can be
denoted by an expression of the form $L\ch w$, where $L$ is a
regular language over $\Sigma$ and $w$ is a word in $\Gamma^*$, such that for
all $u\in\Sigma^*$, $(L\ch w)(u)$ is defined only if $u\in L$, by
$(L\ch w)(u) = w$. 
A \emph{simple transduction}\footnote{It is a restriction of the known class of
  \emph{recognizable transduction} to output words of length at most $1$.} $f$ is a finite union of regular constant transductions whose codomain only contains words of length at most $1$.
A simple transduction $f:\Sigma^*\partialf \Gamma^*$ is denoted by $f=\sum_{i=1}^n L_i\ch w_i$ such that
 $L_1,\dots,L_n\subseteq \Sigma^*$ are pairwise disjoint regular languages, and $w_1,\dots,w_n\in\Gamma^{\leq 1}$.
%A \emph{simple expression} from $\Sigma^*$ to $\Gamma^*$ is an expression of the form $f=\sum_{i=1}^n L_i\ch w_i$ where $L_1,\dots,L_n\subseteq \Sigma^*$ are pairwise disjoint    regular languages, and $w_1,\dots,w_n\in\Gamma^{\leq 1}$. %Abusing notations we identify simple expressions and the associated function, also denoted by $f$.
    %Then the semantics of $f$, which we also denote by $f$ abusing notations, is $f(u)=w_i$ if $u\in L_i$.

\begin{comment}

\begin{lemma}
A function $f:\Sigma^*\partialf \Gamma^*$ is simple if and only if there exist 
 $L_1,\dots,L_n\subseteq \Sigma^*$ pairwise disjoint    regular languages, and $w_1,\dots,w_n\in\Gamma^{\leq 1}$ such that:
    $f=\sum_{i=1}^n L_i\ch w_i$
\end{lemma}

\begin{proof}
    The right-to-left implication is direct. From left-to-right, given
    a simple function of finite codomain $C =
    \{w_1,\dots,w_n\}\subseteq\Gamma^{\leq 1}$, we
    have $f = \sum_{i=1}^n (f^{{-}1}(\{w_i\}))\ch w_i$, and the sets
    $f^{{-}1}(\{w_i\})$ are regular, as sequential
    functions preserve regular languages under inverse. 
\end{proof}

\end{comment}


\paragraph*{Lexicographic enumerators}

\begin{comment}

An ordered alphabet is a pair
$(B,<_B)$ such that $B$ is a finite set and $<_B$ is a linear order
over $B$. The order $<_B$ is lexicographically
extended to words of equal length, where the most significant
bit is rightmost: for all $n$ and all $u,v\in \Sigma^n$,
$u<_B^{lex} v$ if there exists a position $i\in \pos(u)$ such that
$u[i]<_B v[i]$ and for all $i<j\leq n$, $u[j]=v[j]$. Note that
$<_B^{lex}$ is a partial order, which is total if restricted to words
of equal length. We let $\suc_B^{lex}$ the successor relation induced by $<_B^{lex}$. 
\end{comment}
    An ordered alphabet is a pair $\ordera=(B,\order)$ such that $B$ is finite set and $\order$ is a linear order over $B$.
The order $\order$ is extended lexicographically (using the same notation) to words  of same length over $B$, with most significant letter to the right: for all $n$ and all $u,v\in B^n$, $u\order v$ if there exists a position $i\leq n$ such that
$u[i]\order v[i]$ and for all $i<j\leq n$, $u[j]=v[j]$. Note that $\order$ is a total order over $B^n$, for all $n$. We denote $\suc_\ordera:B^*\partialf B^*$ the successor function on $B^*$ induced by $\order$.


We recall that $|$ is a fixed
separator symbol. The \emph{$\ordera$-lexicographic enumerator} is the
function $\lexenum_{\ordera}$:
$$
\begin{array}{llllllll}
   \bigcup_{\Sigma,\Gamma\text{ alphabets}} & \Sigma^* & \rightarrow & ((\Sigma\times
                                                        B)^*|)^* \\
   & w & \mapsto & (w\otimes u_1)|(w\otimes
u_2)|\dots | (w\otimes u_k)
  \end{array}
$$
where $|w| = |u_1|=\dots=|u_k|$, $u_1$ is minimal for $\order$, $u_k$
is maximal for $\order$ and for all $1\leq i<k$, $u_{i+1} =
\suc_\ordera(u_i)$. Note that $k = |B|^{|w|}$.

\begin{example}
Let $\Sigma=\{a,b\}$ let $\ordera=(B,\order)$ be a finite order with $B=\{0,1\}$ and $0\order 1$. 
For all $\sigma\in\Sigma$ and $b\in B$, we write
    $\mm{\sigma}{b}$ instead of $(\sigma,b)$ and $\mm{\Sigma}{b}$
  to denote the set of pairs $(\sigma,b)$ for all $\sigma\in \Sigma$. Then
$\lexenum_{\ordera}(abb) =$
$$
\mm{a}{0}\mm{b}{0}\mm{b}{0}|
\mm{a}{1}\mm{b}{0}\mm{b}{0}|
\mm{a}{0}\mm{b}{1}\mm{b}{0}|
\mm{a}{1}\mm{b}{1}\mm{b}{0}|
\mm{a}{0}\mm{b}{0}\mm{b}{1}|
\mm{a}{1}\mm{b}{0}\mm{b}{1}|
\mm{a}{0}\mm{b}{1}\mm{b}{1}|
\mm{a}{1}\mm{b}{1}\mm{b}{1}
$$
\end{example}


\paragraph*{MapLex combinator} Let $\ordera=(B,\order)$ be an ordered alphabet. We define the function
$$
\begin{array}{llllll}
\maplex_{\ordera} & : & \bigcup_{\Sigma,\Gamma\text{ alphabets}}((\Sigma\times B)^*\rightarrow \Gamma^*)\rightarrow \Sigma^*\rightarrow \Gamma^*\\
\end{array}
$$
such that for all $\Sigma,\Gamma$ alphabets, all $f:(\Sigma\times B)^*\rightarrow \Gamma^*$  and
$u\in\Sigma^*$, 
$$
\maplex_{\ordera}\ f\ u\ =\ f(v_1)f(v_2)\dots f(v_k)
$$
where $\lexenum_{\ordera}(u) = v_1|v_2|\dots |v_k$.
Note that $u$ is in the domain of $\maplex_{\ordera}\ f$ if and only if $v_1,\ldots,v_k$ are all in the domain of $f$.
We write $\maplex$ when $\order$ is clear from the
context.  \todo{encore utile?}


\begin{definition}[Lexicographic transductions]
Lexicographic transductions, denoted by  $\LEX$, are defined inductively by $\LEX_0$ the class of simple transductions and $\LEX_{k+1}=\set{\maplex_{\ordera}\  f| f\in \LEX_k,\ \ordera\ \text{ordered alphabet}}$.

\end{definition}


\begin{example}[Identity and Reverse]
Take $\ordera=(B,\order)$ and $\ordera'=(B,\order')$ with $B=\{0,1\}$, $0\order 1$, and $1\order'
    0$.  
  For all $\sigma\in\Sigma$, let $L_\sigma =
  \pp{\Sigma}{0}^*\pp{\sigma}{1}\pp{\Sigma}{0}^*$ and $L_\epsilon=(\Sigma\times B)^*\setminus(\bigcup_\sigma L_\sigma)$.
    $$
    \begin{array}{rcl}
      \textsf{id} & = & \maplex_{\ordera}\ (L_\epsilon\ch \epsilon +
    \sum_{\sigma\in \Sigma}L_\sigma\ch \sigma) \\ 
    \rev & = & \maplex_{\ordera'}\ (L_\epsilon\ch \epsilon +
    \sum_{\sigma\in \Sigma}L_\sigma\ch \sigma)
      \end{array}
      $$

This is illustrated below on input $abc$, with the output of the simple function below every word of the enumeration.
\renewcommand{\arraystretch}{1.5}
      $$      
