\underbrace{\mm{a}{1}\mm{b}{0}\mm{c}{0}}_{a}|
\underbrace{\mm{a}{0}\mm{b}{1}\mm{c}{0}}_{b}|
\underbrace{\mm{a}{1}\mm{b}{1}\mm{c}{0}}_{\epsilon}|
\underbrace{\mm{a}{0}\mm{b}{0}\mm{c}{1}}_{c}|
\underbrace{\mm{a}{1}\mm{b}{0}\mm{c}{1}}_{\epsilon}|
\underbrace{\mm{a}{0}\mm{b}{1}\mm{c}{1}}_{\epsilon}|
\underbrace{\mm{a}{1}\mm{b}{1}\mm{c}{1}}_{\epsilon}
\\
\rev&\underbrace{\mm{a}{1}\mm{b}{1}\mm{c}{1}}_{\epsilon}|
\underbrace{\mm{a}{0}\mm{b}{1}\mm{c}{1}}_{\epsilon}|
\underbrace{\mm{a}{1}\mm{b}{0}\mm{c}{1}}_{\epsilon}|
\underbrace{\mm{a}{0}\mm{b}{0}\mm{c}{1}}_{c}|
\underbrace{\mm{a}{1}\mm{b}{1}\mm{c}{0}}_{\epsilon}|
\underbrace{\mm{a}{0}\mm{b}{1}\mm{c}{0}}_{b}|
