Several other examples are given in Section~\ref{sec:examples}.


\begin{lemma}\label{lem:regdomlex}
    For all $f\in\LEX$, its domain $\dom(f)$ is regular.
\end{lemma}
\begin{proof}
    Observe that any \LEX transduction $f:\Sigma^*\partialf
    \Gamma^*$ is equal to $\maplex_{\ordera_1}\ (\maplex_{\ordera_2} \dots\ (\maplex_{\ordera_n}\ s)\dots)$
    for some $n\geq 0$, some ordered alphabets $(\ordera_i=(B_i,\order_i))_i$ and some simple
    transduction $s : (\Sigma\times B_1\times \dots\times
    B_n)^*\partialf \Gamma^*$. Then, $f$ is defined on
    $u\in\Sigma^*$ iff for all $1\leq i\leq n$ and all $b_i\in
    B_i^{|u|}$, $s(u\otimes b_1\otimes\dots
    \otimes b_n)$ is defined. Now, observe that $\dom(f)$ is the
    complement of the $\Sigma$-projection of the complement of $\dom(s)$. This entails
    the result as $\dom(s)$ is regular and regular languages are
    closed under morphisms (and complement). 
\end{proof}


\subsubsection{Presentation as automatic transductions}
\label{subsec:lexaut}

%Section~\ref{sec:examples} provides a series of examples of
%lexicographic transductions. The next paragraph establishes their connection
%with automatic transductions. 

We give an alternative presentation in terms of automatic transductions. Let $k\ge 1$ be a positive integer, and
%
%\paragraph{Lexicographic automatic transductions}
     $\overline \ordera =((B_1,\order_1),\ldots,(B_k,\order_k))$ be a $k$-tuple of ordered alphabets and let $B=B_1\times \cdots \times B_k$.
    We define the associated \emph{$k$-lexicographic order} for words
    of the same length over $B^*$ by $u\order_{\overline \ordera} v$ if
    $u=u_1\otimes \cdots \otimes u_k$, $v=v_1\otimes \cdots \otimes
    v_k$, and there is $i\in \set{1,\ldots, k}$ such that $u_i
    \order_{i} v_i$ and for all $j<i$, $u_j=v_j$.


\begin{definition}
   Let $\overline \ordera=((B_1,\order_1),\ldots,(B_k,\order_k))$ be a $k$-tuple of ordered alphabets, let $B=B_1\times \cdots \times B_k$ and let $\order_{\overline \ordera}$ be the associated $k$-lexicographic order.

    A \emph{$k$-lexicographic automatic transducer} over the alphabet $B$ is an automatic transducer with work alphabet $B$ such that the order is exactly $\order_{\overline \ordera}$. A transduction is said \emph{$k$-lexicographic automatic} if it can be defined
    by a $k$-lexicographic automatic transducer. We denote by $\AT_{k\text{-}\LEX}$ the class of $k$-lexicographic automatic transductions and by $\AT_\LEX$ the union of these, which we call lexicographic automatic transductions.
\end{definition}

The next proposition is rather immediate (Appendix.~\ref{app:atklex2klex}).

\begin{restatable}[$\AT_{k\text{-}\LEX} = \LEX_k$]{proposition}{atklextoklex}
\label{prop:atklex2klex}
    For all $k\geq 1$, a transduction is $k$-lexicographic iff it is $k$-lexicographic automatic.
\end{restatable}



Now, we make a connection between $k$-lexicographic automatic
transductions and $k$-lexicographic automatic $\omega$-words. As a consequence
of the latter proposition and known results from the literature of
automatic words, this connection allows us to prove that
$k$-lexicographic transductions form a strict hierarchy (Corollary~\ref{coro:stricthierarch}).


\begin{definition}
 Let $\overline \ordera=((B_1,\order_1),\ldots,(B_k,\order_k))$ be a $k$-tuple of ordered alphabets, let $B=B_1\times \cdots \times B_k$ and let $\order_{\overline \ordera}$ be the associated $k$-lexicographic order.
A \emph{$k$-lexicographic automatic presentation} of a word is an automatic presentation over the alphabet $B_1\times \cdots \times B_k$. such that the order over $B^*$ is exactly  the length monotonous extension of $\order_{\overline \ordera}$.


\end{definition}

Our definition differs slightly from the one of \cite{DBLP:journals/ita/Barany08}, where instead of considering a product of  $k$ alphabets, the author considers positions modulo $k$. There is however a simple correspondence between the two definitions which is made clear by the normal form lemma in \cite[Lemma~4.5]{DBLP:journals/ita/Barany08}.

\begin{proposition}\label{prop:lex-corr}
    For all $k\geq 1$, there is a one-to-one correspondence between $k$-lexicographic automatic presentations of $\omega$-words and total $k$-lexicographic automatic transductions from finite words over a unary alphabet to finite words. Moreover, when an automatic $\omega$-word $w$ corresponds to a function $f$, then $w=\Pi f$.
\end{proposition}
\begin{proof}The proof is the same as the proof of Proposition~\ref{prop:corr}. The constructions of the order automata  (which amounts to allowing words of different lengths or not) preserve the property of being $k$-lexicographic.
\end{proof}

As a consequence, we can show that the $\AT_{k\text{-}\LEX}$ form a strict hierarchy:
\begin{corollary}\label{coro:strictAT}
    For all $k\geq 1$, $\AT_{k\text{-}\LEX}\subsetneq \AT_{k+1\text{-}\LEX}$.
\end{corollary}
\begin{proof}
    This is a consequence of Proposition~\ref{prop:lex-corr} and the strictness of the hierarchy of $k$-lexicographic automatic $\omega$-words given in \cite[Theorem~6.1]{DBLP:journals/ita/Barany08}
\end{proof}

\begin{corollary}\label{coro:stricthierarch}
    For all $k\geq 1$, $\LEX_k\subsetneq \LEX_{k+1}$.
\end{corollary}
\begin{proof}
    From Corollary~\ref{coro:strictAT} and
    Propositions~\ref{prop:lex-corr},\ref{prop:atklex2klex}.
\end{proof}




