\begin{example}[Morphisms]\label{ex:morphisms}
    Let $\phi_a : u\in\{a,b\}^*\rightarrow a^*$ be the morphism
    defined by $\phi_a(a) = a$ and $\phi_a(b) = \epsilon$. We have
    $\phi_a\in \LEX_1$.  It suffices to take $B = \{0,1\}$ with $0\order
    1$. Then, let $L_a = \pp{\Sigma}{0}^*\pp{a}{1}\pp{\Sigma}{0}^*$, and $L_\epsilon = \overline{L_a}$. Then:
    $$
    \phi_a\ =\ \maplex\ (L_a\ch a+L_{\epsilon}\ch
    \epsilon)
    $$
    More generally, if $\psi : \Sigma^*\rightarrow \Gamma^*$ is an
    arbitrary morphism, we show that $\psi\in \LEX_1$. Note that $\psi$
    may transform a single letter into several
    letters, while simple transductions output at most one letter. To
    overcome this difference, we consider a larger linearly
    ordered set. Let $M = \text{max}_{\sigma\in\Sigma}
    |\psi(\sigma)|$. If $M = 0$, then $\psi$ is the constant transduction
    which outputs $\epsilon$, so $\psi\in\LEX_0$. Otherwise, 
    let $\ordera_M=(B_M,<)$ with $B_M=\{0,1,\dots,M\}$ naturally ordered. Let $I :
    \Gamma\rightarrow 2^{\Sigma\times \mathbb{N}}$ such
    that for all $\gamma\in \Gamma$, $I(\gamma)$ is
    the set of pairs $(\sigma,i)$ such that $\psi(\sigma)[i] = \gamma$. 
    Note that for all $\gamma\in\Gamma$,
    $I(\gamma)\subseteq \Sigma\times \{1,\dots,M\}$. Define $L_\gamma$ as the set
    given by the regexp 
    $$
    \bigcup_{(\sigma,i)\in I(\gamma)} \pp{\Sigma}{0}^*\pp{\sigma}{i}\pp{\Sigma}{0}^*
    $$
and $L_\epsilon$ the complement of the union of all $L_\gamma$. Then
$$
\psi\ =\ \maplex_{\ordera_M}\ (L_\epsilon\ch \epsilon\ +\ \sum_{\gamma\in\Gamma}L_\gamma\ch \gamma).
$$
\end{example}

Using similar ideas, the latter example can be generalized to sequential transductions (see Appendix~\ref{app:seqlex}).

\begin{restatable}{lemma}{seqlex}
\label{lem:seqlex}
    $\SEQ\subseteq \LEX_1$.
\end{restatable}

\begin{example}[Domain restriction]\label{ex:domrestrict}Let $k\geq 0$.
Given $f:\Sigma^*\rightarrow \Gamma^*$ a transduction in $\LEX_k$ and $L\subseteq \Sigma^*$ a regular language, the transduction $f$ restricted to $L$, written $f_{|L}:u\mapsto f(u)$ if $u\in \dom(f)\cap L$ is in $\LEX_k$.
We show this inductively on $k$: it is clear for $f\in \LEX_0$. Assume $f=\maplex_{\lambda}\ g$ with $\lambda=(B,\order)$ and let $\pi_\Sigma:(\Sigma\times B)^*\rightarrow \Sigma^*$ be the natural projection morphism.
Then $f_{|L}=\maplex_\lambda\ g_{|\pi_\Sigma^{{-}1}(L)}$, which proves that $\LEX_k$ is closed under domain restriction.
\end{example}



\begin{example}[List of prefixes]
Let $\pref : \Sigma^*\rightarrow \Sigma^*$ such that $\pref(u) =
v_1v_2\dots v_k$ where each $v_1,\dots,v_k$ are successive prefixes of
$u$ of decreasing length. For example, $\pref(abcd) =
abcd.abc.ab.a$. We show that $\pref\in \LEX_1$. We take $\ordera=(B,\order)$ with $B =
\{0,1\}$ with $0\order 1$. Consider a fixed word $1^j$ for some $j$, and
some $i\geq 0$. Let $W_{i,j}$ be the set of words of length $i+j$ in the language
$1^*0^+1^j$. We have $|W_{i,j}| = i$ and all the words in $W_{i,j}$ are
lexicographically ordered as
$0^i1^j\order 10^{i{-}1}1^j\dots\order 1^{i{-}1}01^j$. Moreover,
lexicographically, all words in $W_{i,j}$ are smaller than those in
$W_{i,j+1}$. From this observation, we define the following simple
transduction: if the $B$-annotation of the input word $u$ is in $1^*0^+1^*$,
then the simple transduction produces the label of $u$ aligned with the
leftmost $0$, otherwise it outputs $\epsilon$. E.g., suppose the input word is
$abc$. The lexicographic enumeration together with the production
(above the arrows) is:
$$
000\xrightarrow{a} 100\xrightarrow{b} 010\xrightarrow{\epsilon} 110\xrightarrow{c}
001\xrightarrow{a} 101\xrightarrow{b} 011\xrightarrow{a} 111 \xrightarrow{\epsilon}
$$
More generally, let $L_\sigma =
\pp{\Sigma}{1}^*\pp{\sigma}{0}\pp{\Sigma}{0}^*\pp{\Sigma}{1}^*$ and 
$L_{\epsilon}$ the complement of $\bigcup_\sigma L_\sigma$. Then
$$
\pref\ =\ (\maplex_\ordera\ (L_\epsilon\ch \epsilon\ +\
\sum_{\sigma\in\Sigma}(L_\sigma\ch \sigma+L_{\epsilon}\ch \epsilon))
$$

Now, consider the transduction $\pref_\#$ which also adds a separator
between prefixes. 
For example $\pref_\#(abc) = abc\# ab\# c\#$. To account
for this separator, we take $\ordera'= (\{0,1,2\},<)$ with the natural
order. Note that the lexicographic successor of any annotation of the
form $2^i01^j$ is the annotation in $0^i1^{j+1}$. Also note that for
all $n$,  there are exactly
$n$ annotations of length $n$ in $2^*01^*$. The simple transduction we now
define produces the separator $\#$ on those annotations. On
annotations which contains only $0$ and $1$, it behaves as the simple
transduction of $\pref$. On all other annotations, it outputs $\epsilon$. 
Formally, let $L_\# = \pp{\Sigma}{2}^*\pp{\Sigma}{0}\pp{\Sigma}{1}^*$, and for all $\sigma$, $L_\sigma$ is
defined as before, and finally $L_\epsilon$ is the complement of the
union of all those languages. Then:
$$
\pref_\#\ =\ (\maplex_{\ordera'}\ (L_\#\ch\#\ +\ \sum_{\sigma\in\Sigma}
L_\sigma\ch\sigma\ +\ L_\epsilon\ch\epsilon)
$$
To conclude, we have shown that $\pref,\pref_\#\in\LEX_1$. 
\end{example}



