\subsubsection{Proof of Theorem~\ref{thm:precompose}}\label{app:precompose}

\precompose*

We first need the
following intermediate lemma:
\begin{lemma}\label{lem:sumclosure}
    Let $f,g:\Sigma^*\rightarrow \Gamma^*$ be two lexicographic
    transductions of level $k_f$ and $k_g$ respectively, such that $\dom(f)\cap \dom(g)=\varnothing$. Then $f+g$
    is lexicographic of level $\text{max}(k_f,k_g)$. 
\end{lemma}
\begin{proof}
    The proof is done by induction on the levels. We only show the
    induction step. Suppose that $f = \maplex_{(B_1,\order_1)}\ f'$ and
    $g=\maplex_{(B_2,\order_2)}\ g'$ for some $B_1,B_2$ disjoint and $f',g'$
    lexicographic.
    Then, let $\ordera=(B,\order)$ with $B = B_1\cup B_2$ ordered by
    $b\order c$ if $b,c\in B_1$ and $b\order_1 c$,  or $b,c\in B_2$ and $b\order_2 c$, or $b\neworder c$ where $\neworder$
    is an arbitrary linear order of $(B_1\times B_2)\cup (B_2\times
    B_1)$. Then, $f+g = \maplex_{\ordera} (f'|_{(\Sigma\times
      B_1)^*}+g'|_{(\Sigma\times B_2)^*} + C\ch \epsilon)$ where $C =
    ((\dom(f)\cup \dom(g))\otimes B^*)\setminus ((\Sigma\times B_1)^*\cup
    (\Sigma\times B_2)^*)$.  We can conclude by induction hypothesis
    and the fact that $k$-lexicographic transductions are closed under
    regular domain restriction, for any fixed $k$. 
\end{proof}


\begin{proof}[Proof of Theorem~\ref{thm:precompose}]   

    Any rational transduction $g$ can be decomposed as $g = h\circ e$
    where $h$ is a morphism and $e$ is a letter-to-letter rational
    transduction, in the sense that any transition outputs exactly one
    letter. This is easily seen: if $g$ is defined as a finite
    transducer, $e$ outputs the sequence of transitions, and $h$
    computes locally every output of the transitions. So, it suffices
    to show that $\LEX$ is closed under pre-composition by a
    morphism, and by a letter-to-letter rational transduction. 

    \vspace{2mm}
    \emph{Closure under morphism} Let $\psi : \Gamma\rightarrow
    \Lambda^*$ be a morphism. We show that $f\circ \psi\in \LEX$. We
    do it by induction on the level $k$ of $f$. If $f$ is simple,
    then $f\circ \psi$ is also simple. Otherwise, $f = \maplex_{\ordera}\
    f'$ for some $\ordera=(B,\order)$ and $f'$. We extend $\ordera$ into $\ordera'=(B',\order')$ with $B' = (\Lambda\times
    B)^{\leq M}$, where $M =
    \text{max}_{\gamma\in\Gamma}|\psi(\gamma)|$, and order it as
    follows: for all $v_1\otimes b_1, v_2\otimes b_2\in B'$, 
    $v_1\otimes b_1\order' v_2\otimes b_2$ if $v_1=v_2$ and $b_1\order b_2$, or $v_1\order_{\Lambda} v_2$ for $\order_{\Lambda}$ an arbitrary linear order. Then, let $L$ be
    the set of words in $(\Gamma\times
    (\Lambda\times B)^{\leq M})^*$, of the form
    $(\gamma_1,v_1\otimes b_1)\dots (\gamma_n,v_n\otimes b_n)$
    such that $v_i = \psi(\gamma_i)$ for all $i=1,\dots,n$. Define
    $f''$ the transduction which takes any word in $L$ and returns $f'((v_1\dots v_n)\otimes (b_1\dots b_n))$, otherwise it returns $\epsilon$. By definition of
    $f''$ and $\order_{B'}$, we have:
    $$
    f\circ \psi\ =\ \maplex_{\ordera'}\ f''
    $$
    We conclude by proving that $f''\in \LEX$. 
    It is a consequence of
    the fact that $(1)$ $f'' =  (f'\circ \pi)|_L + C\ch \epsilon$,
    where $C = (\Gamma\times (\Lambda\times B)^{\leq M})^*\setminus L$
    and $\pi$ is the
    morphism which maps any pair $(\gamma,v\otimes b)\in\Gamma\times
    (\Lambda\times B)^{\leq M}$ to $v\otimes b$, $(2)$
    the induction hypothesis, which implies that $(f'\circ \pi)\in \LEX$, $(3)$
    lexicographic transductions are closed under regular domain
    restriction (see Example~\ref{ex:domrestrict}) and $(4)$
    lexicographic transductions are closed under sum by Lemma~\ref{lem:sumclosure}. This does not change the level. 

    \vspace{2mm}
    \emph{Closure under letter-to-letter rational transductions} Let $g$
    be a letter-to-letter rational transduction, given by a finite
    transducer $(A,\out)$, where $A$ is a non-deterministic finite
    automaton with set of transitions $\Delta$, and
    $\out:\Delta\rightarrow \Lambda$ is a morphism. We show that
    $(f\circ g)\in \LEX$. Without loss of generality, we assume that $f=\maplex_{\ordera}\ f'$
    for some $\ordera=(B,\order),f'$ and $f' : (\Lambda\times B)^*\rightarrow \Gamma^*$ lexicographic. Then, $B$ is extended
    into $B' = B\times \Delta$, ordered as $(b_1,\delta_1)\order'
    (b_2,\delta_2)$ if $b_1\order b_2$ or $b_1=b_2$ and $\delta_1\order_\Delta
    \delta_2$ for $\order_\Delta$ an arbitrary order.


    Let $L\subseteq (\Gamma\times B')^*$ be the set of words
    $(\gamma_1,b_1,\delta_1)\dots (\gamma_n,b_n,\delta_n)$ such that
    $\delta_1\dots\delta_n$ is an accepting run of $A$ on
    $\gamma_1\dots\gamma_n$. Clearly, $L$ is regular. Then,
    $f\circ g = \maplex_{B'}\ (f'\circ \out\circ \pi_\Delta)|_L$
    where $\pi_\Delta$ is the $\Delta$-projection morphism.  The
    result follows as lexicographic transductions are closed under
    morphism and regular domain restriction. This does not change the level.
    \end{proof}








