\title{Optimization for Semantic-Aware Resource Allocation under CPT-based Utilities
}

\author{\IEEEauthorblockN{Symeon Vaidanis$^*$,  Photios A. Stavrou$^*$, and Marios Kountouris${^*}^{\dagger}$}\\
