	\section{Methodology}\label{Methodology}    

            \begin{algorithm}[htbp]
            \caption{Annotated Point Cloud Generation Pipeline}
            \label{alg:pipeline_hybrid}
            \begin{algorithmic}[1]
            \State \textbf{Input:} A set of 3D model files $\mathcal{F} = \{f_1, f_2, \dots, f_m\}$; Sampling density $\rho_{\text{base}}$ (points per unit area).
            \State \textbf{Output:} A set of annotated point clouds $\mathcal{P}_{\text{set}}$.

            \Statex
            \Statex
            \State \textbf{Initialization:}
            \State $\mathcal{P}_{\text{set}} \leftarrow \emptyset$; Constant $\theta \leftarrow 1000$.
            \State \Comment{\textbf{Stage 0: Global Semantic Pre-processing}}
            \State $D_s \leftarrow \text{BuildGlobalSemanticMap}(\mathcal{F})$ \Comment{Scan all files to create a global name-to-ID map}

            \Statex
            \For{each file $f \in \mathcal{F}$}
                \State \Comment{\textbf{Stage 1: Model Loading}}
                \State $\mathcal{G} \leftarrow \text{LoadMeshFromFile}(f)$ \Comment{Parse file into a structured model object}
                \State $P_c \leftarrow \emptyset$ \Comment{Initialize point cloud for the current model}
                \State $C_k \leftarrow \text{InitializeInstanceCounters}()$ \Comment{Initialize counters for each semantic class}

                \Statex
                \For{each sub-mesh $\mathcal{M} \in \mathcal{G}$}
                    \State \Comment{Assign semantic instance label to the current sub-mesh}
                    \State $\sigma \leftarrow \text{GetSemanticName}(\mathcal{M})$
                    \State $s \leftarrow D_s[\sigma]$
                    \State $c \leftarrow C_k.\text{increment}(\sigma)$ \Comment{Get and update index for this class}
                    \State $k \leftarrow s \times \theta + c$ \Comment{Form a unique numeric instance ID}
                    \State $\text{SetLabelsForObject}(\mathcal{M}, s, k)$ \Comment{Store labels with the sub-mesh's faces}

                    \Statex
                    \Comment{\textbf{Stage 2: Point Cloud XYZ Coordinate Generation}}
                    \State $A_{\mathcal{M}} \leftarrow \text{CalculateSurfaceArea}(\mathcal{M})$ \Comment{See Eq.~\ref{eq:total_area} and Eq.~\ref{eq:triangle_area}}
                    \State $N_{\mathcal{M}} \leftarrow \lfloor A_{\mathcal{M}} \times \rho_{\text{base}} \rfloor$ \Comment{See Eq.~\ref{eq:num_points}}

                    \For{$i = 1$ to $N_{\mathcal{M}}$}
                        \State $T \leftarrow \text{SelectTriangleWeightedByArea}(\mathcal{M})$ \Comment{Select a host triangle $T$ from sub-mesh $\mathcal{M}$}
                        \State $(\alpha, \beta, \gamma) \leftarrow \text{GenerateRandomBC}()$

                        \State $p_i \leftarrow \alpha v_1 + \beta v_2 + \gamma v_3$ \Comment{See Eq.~\ref{eq:barycentric_pos}}

                        \Statex
                        \Comment{\textbf{Stage 3 \& 4: Attribute Inheritance \& Interpolation}}
                        \State $(u_i, v_i) \leftarrow \text{InterpolateUVs}(T, \alpha, \beta, \gamma)$ \Comment{See Eq.~\ref{eq:uv_interp}}
                        \State $c_i \leftarrow \text{SampTexFUV}(\text{GetTextureFor}(T), (u_i, v_i))$

                        \State $\mathbf{n}' \leftarrow \text{InterpolateNormals}(T, \alpha, \beta, \gamma)$ \Comment{See Eq.~\ref{eq:normal_interp}}
                        \State $\mathbf{n}_i \leftarrow \text{normalize}(\mathbf{n}')$ \Comment{See Eq.~\ref{eq:normalize}}

                        \State $s_p, k_p \leftarrow \text{GetLabelsFromTriangle}(T)$ \Comment{Inherit pre-assigned labels}

                        \State Append $(p_i, c_i, \mathbf{n}_i, s_p, k_p)$ to $P_c$
                    \EndFor
                \EndFor

                \Statex
                \State Append $P_c$ to $\mathcal{P}_{\text{set}}$
                \Statex
            \EndFor

            \State \textbf{return} $\mathcal{P}_{\text{set}}$
            \end{algorithmic}
            \end{algorithm}

