            \centering
            \caption{Symbol and Function Definitions for Algorithm \ref{alg:pipeline_hybrid}}
            \label{tab:symbol_function_definitions_final}
            \begin{tabularx}{\textwidth}{lX}
            \toprule
            \textbf{Symbol / Function} & \textbf{Description} \\
            \midrule
            \multicolumn{2}{l}{\textbf{State Variables \& Data Structures}} \\
            $\mathcal{F}$ & A set of input 3D model files (e.g., in .obj format). \\
            $\rho_{\text{base}}$ & The base sampling density (points per unit area), used to determine the number of points for each sub-mesh. \\
            $\mathcal{P}_{\text{set}}$ & The final output set containing all generated annotated point clouds. \\
