\section{Extending the Variation Range of the \etam}\label{sec:extension}

In this section, we will show that the range of adversarial variations of the
\etam\ can be increased substantially, without sacrificing 
faithfulness with respect to the SPF problem. The crucial idea of
our extension is to introduce $T$-dependent bounds in the variation range
$[-\etm(T), \etp(T)]$,
which coincide with the original bounds $[-\etmmin,\etpmin]$ only
for two very small values of $T$, which are quite insensitive 
to delay fluctuations.

Let $\Delta$ be the up-time of the critical pulse train identified in \cite{FMNNS18:DATE} (which is determined by the fixed point of $f(.)$ given
in \cref{eq:delta-new}) and $\dmin>0$ be the unique minimum
delay value of a strictly causal\footnote{Where $\dup(0)>0$ and $\ddo(0)>0$.} 
\idm\ channel,
defined by
\begin{equation}
  \dup(-\dmin) = \dmin = \ddo(-\dmin)\label{eq:dmin}
\end{equation}
according to~\cite[Lem.~3]{FNNS20:TCAD}. 

\begin{definition}\label{def:eta}
For some given constants
	\begin{equation}
		\rhp \geq 0, \rhm \geq 0\tag{C2}\label{eq:constraintc2}
	\end{equation}
some $\etpinf\geq \etpmin$, $\etminf \geq \etmmin$,
some $\oDelta$ satisfying $\oDelta \geq \dup(-\oDelta) + \rho^+ \cdot (\oDelta - \Delta) + 
	\etpmin$, 
%	where $\Delta$ denotes the fixed point of $f(.)$ in \cref{eq:delta-new}, 
and 	$\Delta' = \dup(-\Delta) + \etpmin - \Delta$, let	

	\begin{equation}
		\etp(T) =
		\begin{cases}
			\etpinf  & 
			\text{for}\ T < -\overline{\Delta},\\
			\rhp \cdot (-T - \Delta) + \etpmin & 
			\text{for}\ -\oDelta \leq T \leq -\Delta,\\
			\etpinf & 
			\text{for}\ T > -\Delta,\label{eq:etapdef}
		\end{cases}
	\end{equation}

	\begin{equation}
		\etm(T) =
		\begin{cases}
			\etminf  & 
			\text{for}\ T < -\Delta',\\
			\rhm \cdot (-T + \Delta') + \etmmin & 
			\text{for}\ - \Delta' \leq T  
			< 0,\\
			\etminf & 
			\text{for}\ T \geq 0.\label{eq:etamdef}
		\end{cases}
	\end{equation}
\end{definition}

\cref{fig:boundcomp} shows the comparison of the old and the new bounds for the 
\etam. Note carefully that the only values of $T$
for which the bounds could not be enlarged are $-\Delta$ and
$-\Delta'$, i.e., the up-time and the
down-time of the critical infinite pulse train
identified in \cite{FMNNS18:DATE}.
For the inverter used in \cref{sec:results}, the actual values are 
		$\etpmin \approx \etmmin \approx \SI{63}{\fs}, 
		\etpinf \approx \etminf \approx \SI{1.47}{\ns}, 
		\Delta \approx \SI{191}{\fs}, 
		\Delta' \approx \SI{63}{\fs}$ and 
		$\oDelta = \SI{230}{\fs}$.
\ifthenelse{\boolean{conference}}{}{Both $\etpinf$ and $\etminf$ are hence approximately $20$ 
times larger than the original bounds $\etpmin$ and $\etmmin$ here.}

