We define the gain $\delta$ of communication rule $I$ for a certain type $v_b$ provided they bid $b$ as the difference between the buyer's expected utility with and without additional information from the seller such that
%
\begin{equation}
    \begin{aligned}
        \delta(I&(b), v_b) \\
        &= \mathbb{E}_{\mathcal{M}, \mathcal{X}} \left[ u_b^{+} (\sigma(\theta_m^b), x) \right] - \mathbb{E}_{\mathcal{X}} \left[ u_b^{+} (\sigma(v_{b}), x) \right],
    \end{aligned} 
    \label{eq:gain-communication-rule}
\end{equation}
%
which is determined by the quality of the buyer’s private information. 
Lastly, we assume that $v_{b}$ provides no additional information about the distribution of messages conditioned on the state, i.e., the buyer's private signal $s_{b} \in \mathcal{S}_{b}$ and the message received from the seller $m \in \mathcal{M}$ are independent conditioned on the state, meaning they draw their information from independent sources.

In summary, we have reduced the mechanism design problem to finding a menu consisting of: (i) a single-dimensional allocation function, namely, the informativeness of the messages given the bid, $I: \mathcal{B} \rightarrow \mathbb{R}_{[-1, 1]}$; and (ii) a transfer function $t: \mathcal{B} \rightarrow \mathbb{R}$, specifying how much the buyer should pay for this information.

\paragraph{Feasible Menus.}
The use of monetary transfers leads to several key distinctions compared to pure information design. First, the buyer’s willingness to participate depends not only on the gain of the purchased communication rule but also on its price.
%
\begin{definition}[Individual Rationality]
     A mechanism is \textit{individually rational} if the buyer is guaranteed at least as much expected utility as not participating, provided they report their true type, which, for every $v_{b} \in \mathcal{V}_{b}$, implies
     \begin{equation*}
        \delta(I(v_b), v_b) \geq t(v_b). 
   \end{equation*}
\end{definition}
%
The transfers also affect incentive compatibility.
%
\begin{definition}[Truthfulness] \label{def:truthfulness}
   A mechanism is \textit{truthful} if, assuming it is \textit{obedient} as defined below, for every $v_{b} \in \mathcal{V}_{b}$ and $b \in \mathcal{B}$, it holds that
    \begin{equation*}
       \delta(I(v_b), v_b) - t(v_b) \geq \delta(I(b), v_b) - t(b).
   \end{equation*}
   %
\end{definition}

Each truthfully reported type also has to be willing to follow the recommended action.
%
\begin{definition}[Obedience] \label{def:obedience}
     A mechanism is \textit{obedient} if the buyer's best response is the seller's action recommendation, provided they report their type truthfully, such that for every $a_{b} \in \mathcal{A}_{b}$ and $v_{b} \in \mathcal{V}_{b}$, it holds that
     \begin{equation*}
       \mathbb{E}_{\mathcal{M}, \mathcal{X}} \left[ u_{b}^{+} (\sigma(\theta_{m}^{v_{b}}), x)  \right] \geq \mathbb{E}_{\mathcal{M}, \mathcal{X}} \left[ u_{b}^{+} (a_{b}, x)  \right].
    \end{equation*}
\end{definition}

Any obedient mechanism induces a distribution of actions that is Bayes correlated equilibrium \citep{bergemann2016bayes}. Both truthfulness and obedience together make the mechanism robust to double-deviations, where the buyer misreports their private type \textit{and} deviates from the seller’s recommendation. 
Therefore, together these constraints form incentive compatibility.
%
\begin{definition}[Incentive Compatibility]
   A mechanism is \textit{incentive compatible} if
   \begin{align*}
    \mathbb{E}_{\mathcal{M}, \mathcal{X}} \left[ u_b^{+} (\sigma(\theta_m^{v_b}), x)  \right] - \ & t(v_b) \\
    &\geq \mathbb{E}_{\mathcal{M}, \mathcal{X}} \left[ u_b^{+} (a_b, x)  \right] - t(b),
   \end{align*}
   %
   for every $a_b \in \mathcal{A}_b$, $v_{b} \in \mathcal{V}_{b}$ and $b \in \mathcal{B}$.
\end{definition}

Satisfying these individual rationality and incentive compatibility constraints limits the space of feasible menus available to the seller. In the next section, we formulate the seller's objective and incorporate these constraints to fully characterize the optimal mechanism design problem.

\section{Profit-Maximizing Mechanism} \label{sec:optimal-mechanism}
To derive the seller's objective, we first return to the value of a communication rule to simplify the expressions for the buyer's gain and the seller's cost. This allows us to finally design and analyze the optimal mechanism, first considering a simpler setting with two buyer types before generalizing to a continuous type space.

\paragraph{The Buyer's Gain.}
With the dominant strategy in (\ref{eq:optimal-strategy}), the expected value of the nonnegative term of the buyer's utility function before any information sharing reduces to
%
\begin{equation}
    \mathbb{E}_{\mathcal{X}} \left[ u_b^{+} (\sigma(v_{b}), x) \right] = \left(v_{b} \vee (1-v_{b}) \right), 
    \label{eq:value-no-information}
\end{equation}
%
and similarly, after purchasing a communication rule,
%
\begin{align*}
    \mathbb{E}_{\mathcal{M}, \mathcal{X}}  \big[ u_b^{+} (\sigma(&\theta_m^b, x) \big] = \\
    &\sum_{m \in \mathcal{M}} p(m; b, v_b) \left( \theta_m^b \vee (1-\theta_m^b) \right).
    %&= v_{b} I(b) + \mathbb{P}(\{m_1\} \vert X = 1; m). \label{eq:value-communication-rule-expanded}
\end{align*}
%
where $a \vee b = \max(a, b)$.
Next, we use these expressions to simplify the characterization of the informativeness of a communication rule.
%
\begin{proposition}
\label{prop:concentrated-communication-rules}
    Every communication rule in the optimal menu will reveal at least one of the states with certainty.
\end{proposition}
\begin{proof} 
    Provided in Appendix~\ref{app:concentrated-communication-rules}.
\end{proof}

\begin{figure}[!t]
  \begin{center}
    \includegraphics[width=\columnwidth]{boundary.pdf}
  \end{center}

  \caption{Feasible region of $I_0 (b)$ and $I_1 (b)$. The ceiling of the feasible region is highlighted in red.}
  \label{fig:concentrated-communication-rules}
\end{figure}

To provide intuition for this proof let $I_0 (b) = P (m_0 \vert X = 0; b)$ and $I_1 (b) = P (m_1  \vert X = 1; b)$ fully define a communication rule as in Table~\ref{tab:binary-communication-rule}, with $I_0 (b), I_1 (b) \in \mathbb{R}_{[0, 1]}$. By Proposition~\ref{prop:direct-communication-rules}, $I_0 (b) + I_1 (b) \geq 1$, for which the feasible region is plotted in Figure~\ref{fig:concentrated-communication-rules}. It follows that in the optimal mechanism, all feasible objective values with corresponding solution $(I_0^\ast, I_1^\ast)$ define a level set which contains a solution $(I_0^\prime, I_1^\prime)$ on the ceiling of the feasible region, on which either measure is always $1$, revealing the corresponding state with certainty. It is this line that describes the informativeness $I(b) \in \mathbb{R}_{[-1, 1]}$ of the communication rule.
%different types rank partially informative communication rules differently
%
\begin{corollary} \label{corr:value-communication-rule-cases}
    From Proposition~\ref{prop:concentrated-communication-rules}, the gain $\delta$ of a communication rule $I(b)$ to type $v_b$ provided they report $b$ as described in (\ref{eq:gain-communication-rule}) can be written as
    \begin{equation}
        \begin{aligned}
             \delta(I(b), v_b) &= 1 - \left(v_b \vee (1-v_b)\right) \\
             &\quad - I(b) \left( \Ind{I(b) \geq 0} - v_b \right).
            \label{eq:gain-communication-rule-expanded}
        \end{aligned}
    \end{equation}
\end{corollary}
%
%
\begin{figure}[!t]
  \begin{center}
    \includegraphics[width=\columnwidth]{value_of_experiments.pdf}
  \end{center}

  \caption{Gain as a function and buyer types, as described in (\ref{eq:gain-communication-rule-expanded}), for $I=0$ (solid), $I=1/2$ (dashed) and $I=-1/2$ (dotted).}
  \label{fig:value-communication-rule}
\end{figure}
%
This expression matches that for the buyer's valuation in \citet{bergemann2018design}, as dominant strategies ensure that selling information to a competitor only affects $u_b^{+}$ and $u_s^{-}$, the latter of which we later show only appears in the objective function. To remain self-contained, Figure~\ref{fig:value-communication-rule} shows the gains from several communication rules, illustrating how the value of information varies with the buyer's type. Observe that:
(i) the fully informative communication rule is the most valuable for every type, with $\delta(I, v_b) = 1/2$; 
(ii) the type with the highest willingness to pay is that which is least informed (i.e, $v_{b} = 1/2$) and those with the lowest willingness to pay are those that are most informed (i.e, $v_{b} \in \{0, 1\}$); 
and (iii) the distance $|v_b - 1/2|$ alone is not a sufficient statistic for the value of information, as asymmetries arise based on interim beliefs. 

These observations imply that these information commodities are inherently two-dimensional, comprising both \textit{quality} and \textit{value}; accuracy is only valuable so long as it changes the buyer's action. This distinction has been well studied in the field of predictive analytics, including in meteorological forecasting \citep{murphy1993good}. It implies that a direct communication rule yields a nonnegative gain: the message either (i) changes the buyer’s best response, leading to a weak utility increase; or (ii) leaves the action unchanged, resulting in zero value. \textit{Hereafter, we consider only truthful mechanisms with $b=v_b$.}
We hence obtain: $-1 \leq I(v_b) \leq v_b / (1-v_b)$ if $v_{b} \leq 1/2$ and $-(1-v_b)/v_b \leq I(v_b) \leq 1$ if $v_{b} > 1/2$. Hence, communication rules $I(v_{b})\in\{-1,1\}$ indeed reveal no information, as the types able to receive these would already take the recommended action without additional information. 

%In canonical mechanism design terms, $I$ acts as a social choice function, implementable only if truth-telling is a Bayesian Nash equilibrium in the direct mechanism.
%Given the seller's ex-post utility $u_s (\boldsymbol{a}, x; \tau)$ described in (\ref{eq:utility-function}), their \textit{ex-ante} cost associated with a particular communication rule and buyer type is the expected externality incurred when the buyer chooses the correct action, which we write as:
\paragraph{The Seller's Cost.}
For a given communication rule, the seller's cost is the expected externality incurred when the buyer chooses the correct action, which can be written as:%
\begin{equation}
    \begin{aligned}
        c (I (v_b)&; \tau) \\
        &= \mathbb{E}_{\mathcal{R}, \mathcal{X}} \left[ u_s^{-} (\sigma(\theta_{r}^{v_b}), x; \tau)\right] \\
        &= \tau v_s + \tau (1-2v_s)(1-v_s) \\
        &\quad - \tau (1 - 2v_s) I (v_b) \left(v_s + \Ind{I (v_b) \geq 0} \right),
    \label{eq:expected-externality}
    \end{aligned}
\end{equation}
%
for which a full derivation is provided in Appendix~\ref{app:optimal-mechanism-continuous}.

\paragraph{Mechanism Design.}
The objective of the mechanism is to maximize the seller's expected profit, i.e., the expected revenue from the transfer minus the expected cost, with the expectation taken over the type space of the buyer. 

\begin{proposition}[Optimal Mechanism] \label{prop:optimal-mechanism-general} The optimal mechanism maximizes the seller's profit subject to individual rationality and incentive compatibility, which can be expressed as the following mathematical program:
%
\begin{subequations}
    \label{eq:optimal-mechanism-general}
    \begin{align} 
        \max_{I, t} \quad & \mathbb{E}_{\mathcal{V}_{b}} [ t(v_b) -  c (I (v_b); \tau) ] \label{eq:expected-profit} \\
        \textrm{s.t.} \quad 
        & I(v_b) \in \mathbb{R}_{[-1, 1]}, \, t(v_b) \in \mathbb{R}_{\geq 0} \label{eq:variable-bounds} \\
        %& t(v_b) \in \mathbb{R}_{\geq 0} \quad && \forall v_b \in \mathcal{V}_b \label{eq:transfer-bounds} \\
        & \delta(I(v_b), v_b) - t(v_b) \geq 0 \label{eq:participation} \\
        & \delta(I(v_b), v_b) - t(v_b) \geq \delta(I(b), v_b) - t(b) \label{eq:incentive}
    \end{align}
\end{subequations}
%
where (\ref{eq:expected-profit}) is the expected profit, (\ref{eq:variable-bounds}) encodes the bounds on the allocations and transfers, and (\ref{eq:participation}) and (\ref{eq:incentive}) encode individual rationality and incentive compatibility, respectively. Each constraint is defined for every $v_b \in \mathcal{V}_b$, as well as every $b \in \mathcal{B}$ for the incentive constraint (\ref{eq:incentive}).
\end{proposition}
%
We note that, it is the inclusion of the cost described in (\ref{eq:expected-externality}) in the objective that generalizes existing works by allowing us to model the purchase of information from a competitor as opposed to a third party.
In the following, we solve this problem for binary types to build intuition into the optimal menu, then generalize to continuous type spaces.

\subsection{Binary Type Space}
Suppose $\mathcal{V}_b = \{v_b^l, v_b^h\}$, with the high type $v_b^h$ assigning a higher valuation to the fully informative communication rule than the low type, such that $\delta(0, v_b^h) > \delta(0, v_b^l)$. Without additional information, each type chooses the action that matches the state with the highest prior probability, meaning in this case the high type places lower prior probability on the state they deem most likely. In other words, the high type has lower precision (i.e., is less well informed), where we define the precision of a type as it's distance from $1/2$, such that $\vert v_b^h - 1/2 \vert < \vert v_b^l - 1/2 \vert$. We denote the probability of the high type as $\phi = P(v_b^h)$. 

\begin{corollary} \label{corr:optimal-mechanism-binary} From Proposition~\ref{prop:optimal-mechanism-general}, with binary types the the mechanism design problem in (\ref{eq:optimal-mechanism-general}) reduces to:
\begin{subequations}
    \label{eq:optimal-mechanism-binary}
    \begin{align} 
        \label{eq:binary-objective-function} 
        \max_{I^k, t^k} \quad & \phi (t^h - c^h) + (1 - \phi) (t^l - c^l)\\
        \textrm{s.t.} \quad 
        %& I^l \in \mathbb{R}_{[-1, 1]}, \, I^h \in \mathbb{R}_{[-1, 1]}, \, t^l \in \mathbb{R}_{\geq 0}, \, t^h \in \mathbb{R}_{\geq 0} \\
        & I^k \in \mathbb{R}_{[-1, 1]}, \, t^k \in \mathbb{R}_{\geq 0} \\
        & \delta(I^k, v_b^k) - t^k \geq 0 \label{eq:participation-binary} \\
        & \delta(I^k, v_b^k) - t^k \geq \delta(I^{k^\prime}, v_b^k) - t^{k^\prime} \label{eq:incentive-binary}  
    \end{align}
\end{subequations}   
%
where $I^k = I(v_b^k)$, $t^k = t(v_b^k)$ and $c^k = c(I^k)$ denote the allocation, transfer and externality cost for type $k \in \{l, h\}$, respectively, and the objective in (\ref{eq:binary-objective-function}) denotes the expected profit. Constraints (\ref{eq:incentive-binary}) and (\ref{eq:participation-binary}) are the incentive and individual rationality constraints, respectively. Constraints are defined for every $k \in \{l, h\}$, as well as every $k^\prime \in \{l, h\}$ where $k \neq k^\prime$ for the incentive constraint (\ref{eq:incentive-binary}).
\end{corollary}
%
We now distinguish between congruent and noncongruent types; two types are congruent if they would select the same action without additional information.

\paragraph{Congruent Types.}
