\subsection{Continuous Type Space}
We now generalize to a type space that is continuous on the unit interval, such that the distribution $F(v_b)$ has support on $\mathcal{V}_b = \mathbb{R}_{[0, 1]}$ with density $p(v_b)$. To obtain analytical insights, we begin with a key result from prior work, which extends \citet{myerson1981optimal}'s finding that incentive compatibility and individual rationality can be summarized by simpler, more compact constraints on the allocation $I(v_b)$ with transfers $t(v_b)$ pinned down by the utility of the lowest type. We then generalize this work by incorporating the seller’s expected cost into the objective and derive closed-form results.

\begin{proposition}[\citealp{bergemann2018design}]  \label{prop:necessary-and-sufficient-conditions}
    Individual rationality and incentive compatibility hold as long as $I(v_b)$ is non-decreasing and $\int_{\mathcal{V}_b} I(v_b) dv_b = 0$.
\end{proposition}
\begin{proof}
    Provided in Appendix~\ref{app:necessary-and-sufficient-conditions} (Sections~\ref{app:necessary-conditions} and \ref{app:sufficient-conditions}).
\end{proof}

\begin{corollary} \label{corr:transfer-function}
    From Proposition~\ref{prop:necessary-and-sufficient-conditions}, the transfer function can be derived using \citet{milgrom2002envelope}'s envelope theorem to be:
    \begin{align}
        t(v_b) = I (v_b) \left(v_b - \Ind{I (v_b) \geq 0} \right) - \int_{0}^{v_b}  I (z) d z.
        \label{eq:transfer-function}
    \end{align}
\end{corollary}

Following \citet{myerson1981optimal}, we can use integration by parts to eliminate the integral in (\ref{eq:transfer-function}) when computing $\mathbb{E}_{\mathcal{V}_b}[t(v_b)]$. Then, using the expression for the expected cost described in (\ref{eq:expected-externality}), we re-write the problem in (\ref{eq:optimal-mechanism-general}) as follows.

\begin{corollary} \label{corr:optimal-mechanism-continuous}
    From Proposition~\ref{prop:necessary-and-sufficient-conditions}, the mechanism design problem in (\ref{eq:optimal-mechanism-general}) reduces to:
    \begin{subequations}
        \begin{align} 
            \max_{I} \quad &  \mathbb{E}_{\mathcal{V}_b} \left[ J(I, v_b) \right] \\
            \textrm{s.t.} \quad 
            & \int_{\mathcal{I}} I(v_b) dv_b = 0 \label{eq:integral-constraint}\\
            & \frac{d}{d v_b} I (v_b ) \geq 0 \label{eq:monotonicity-constraint}
        \end{align}
        \label{eq:optimal-mechanism-continuous}
    \end{subequations} 
    %
    where (\ref{eq:monotonicity-constraint}) encodes the monotonicity constraint and 
    \begin{equation}
        \begin{aligned}
             J(I, v_b)  = I(v_b) & \big( v_b  + \frac{F(v_s)}{p(v_s)} + \tau v_s (1 - 2v_s) \\
                &+ \Ind{I(v_b) \geq 0} \left(\tau (1 - 2v_s)^2  - 1\right)\big). \label{eq:integrand}
                %- \tau \left(v_s - (1 - v_s) (1 - 2 v_s) \right) constant \\
        \end{aligned}
    \end{equation}
\end{corollary}

This formulation bears similarities to \citet{myerson1981optimal}'s single item auction, where the problem is reduced to virtual surplus maximization subject to monotonic allocations.
%The key difference is that, whilst the equality constraint (\ref{eq:integral-constraint}) can be dealt with using standard Lagrange methods, the virtual values are a function $I$, rather than being constant in this decision variable.
The virtual value function is defined as the partial derivative of the integrand in (\ref{eq:integrand}) with respect to $I$, given by
%
\begin{align*}
    \pi (I, v_b) &= \frac{\partial}{\partial I} J(I, v_b) \\
    %&= F(v_b) + p(v_b) \Big(\tau v_s (1 - 2 v_s) \\
    %&\quad - \Ind{I(v_b) \leq 0}  \left(2 \tau v_s (1 - 2 v_s) + 1\right) + v_b \Big),
    &=\pi^+ (v_b) + \Ind{I(v_b) \leq 0} \left( \pi^- (v_b) - \pi^+ (v_b) \right),
\end{align*}
%
where
%
\begin{equation*}
    \pi^- (v_b) =  p(v_b) \left(\tau v_s (1 - 2 v_s) + v_b \right) + F(v_b),
\end{equation*}
%
and
%
\begin{equation*}
    \pi^+ (v_b) = p(v_b) \left(\tau (1 - v_s) (1 - 2 v_s) + v_b - 1\right) + F(v_b),
\end{equation*}
%
where the negative $\pi^-$ and positive $\pi^+$ parts represent the marginal benefit to the seller in terms of profit, albeit ignoring the constraint (\ref{eq:integral-constraint}), of increasing the allocation of each type from $-1$ to $0$ and from $0$ to $1$, respectively. 
Hereafter, we assume the virtual value function is non-decreasing in $v_b$, which places a regularity condition on the type distribution. 
This is a common assumption as it holds for several familiar distributions, including the uniform, exponential, and Gaussian distributions. 
%
