\section{Proof of Proposition~\ref{prop:direct-communication-rules}}
\label{app:direct-communication-rules}
%In direct menus, a communication rule $I \in \mathcal{I}$ is designed for each type $v_b \in \mathcal{V}_b$. 
Suppose that the set of messages the seller can send to the buyer was $\mathcal{M} = \cup_{\mathcal{A}_b} \mathcal{M}^{a_b}$, where $\mathcal{M}^{a_b}$ is the subset of messages that incite type $v_{b}$ to choose action $a_b \in \mathcal{A}_b$. Further, consider an alternative message space $\mathcal{R} = \cup_{\mathcal{A}_b} \{ r^{a_b} \}$, such that $\vert \mathcal{R} \vert = \vert \mathcal{A}_b \vert$, and each message $r^{a_b}$ inciting type $v_b$ to choose a different action. 

In summary, for each action, set $\mathcal{M}$ contains many messages that incite that action, whilst set $\mathcal{R}$ contains only one.
%
\begin{lemma} \label{lemma:garbling}
    The distributions over $\mathcal{M}$ and $\mathcal{R}$ are such that $p(r^{a_b} \vert x; v_b)$ is a garbling of $p(m^{a_b} \vert x; v_b)$.
\end{lemma}
\begin{proof}
    If $p(r^{a_b} \vert x; v_b)$ is a garbling of $p(m^{a_b} \vert x; v_b)$, there must exist a function $g : \mathcal{R} \times \mathcal{M}^{a_b} \mapsto \mathbb{R}_{[0, 1]}$ such that
    %
    \begin{align*}
        p(r^{a_b} \vert x; v_b) = \sum_{m^{a_b} \in \mathcal{M}^{a_b}} g(r^{a_b}, m^{a_b}) p(m^{a_b} \vert x; v_b),
    \end{align*}
    %
    for every $a_b \in \mathcal{A}_b$, which in our case holds by design simply for $g(r^{a_b}, m^{a_b}) = 1$, for every $m^{a_b} \in \mathcal{M}^{a_b}$.
\end{proof}
%
With Lemma~\ref{lemma:garbling}, message $r^{a_b}$ conditioned on the state has equal probability mass to the sum of all those in $\mathcal{M}^{a_b}$, so the joint distribution of states and actions are the same, so $v_b$ is indifferent between these two communication rules. In addition, garbling can be viewed as a way of adding noise to a communication rule, so is weakly less informative for all types. Hence, by Blackwell's theorem we get that
%
\begin{align*}
   \mathbb{E}_{\mathcal{R}, \mathcal{X}} \left[ u_b^{+} (\sigma(\theta_r^b), x) \right] \leq \mathbb{E}_{\mathcal{M}, \mathcal{X}} \left[ u_b^{+} (\sigma(\theta_m^b), x) \right], 
\end{align*} 
%
for every $b \in \mathcal{B}$, which means that every other reported type weakly prefers $p(m \vert x; b)$ over $p(r \vert x; b)$, whilst the true type is indifferent \citep{blackwell1951comparison, blackwell1953equivalent}. 

In brief, considering only direct communication rules with $\mathcal{M} = \mathcal{A}_b$, the value will be unchanged for $v_b$, and the value will only be reduced for $b \neq v_b$, so incentive compatibility and individual rationality are preserved.
\hfill \BlackBox

\section{Proof of Proposition~\ref{prop:concentrated-communication-rules}} \label{app:concentrated-communication-rules}
We use the following result from convex analysis:
\begin{lemma}[\citealp{boyd2004convex}] \label{lemma:concentrated}
    Let $g : \mathbb{R}^n \mapsto \mathbb{R}$ be an affine function and let $\mathcal{S}$ be a (nonempty) convex polytope. Then for every $z \in \operatorname{int}(\mathcal{S})$ there exists a point $z^\prime$ on the boundary $\partial \mathcal{S}$ of $\mathcal{S}$ with $p(z) = p(z^\prime)$.
\end{lemma}
\begin{proof}
    If $g$ is constant on $\mathcal{S}$ the claim is trivial, so assume that $g$ is nonconstant. Then, for every $z \in \operatorname{int}(\mathcal{S})$, the level set $\mathcal{L} = \{z^\prime \in \mathbb{R}^n : g(z^\prime) = g(z)\}$ is the intersection of $\mathcal{S}$ with an affine hyperplane. As $\mathcal{S}$ is compact and convex, $\mathcal{L}$ is nonempty, intersecting $\partial \mathcal{S}$ at some point $z^\prime$. 
\end{proof}

Let $I_0 = P (m_0 \vert X = 0)$ and $I_1 = P (m_1  \vert X = 1)$ be a direct communication rule as in Table~\ref{tab:binary-communication-rule}, with $I_0, I_1 \in \mathbb{R}_{[0, 1]}$ and $I_0 + I_1 \geq 1$. Recall $I = I_0 - I_1$, so we can write the feasible region as $\mathcal{S} = \{(I_0, I) \in \mathbb{R}^2: 0 \leq I_0 \leq 1, \ -1 \leq I \leq 1, I \geq 1 - 2I_0, \ I_0 + I \leq 1 \}$ which defines a convex polytope. As the seller's objective is linear in these variables, by Lemma~\ref{lemma:concentrated}, there exists a level set $\mathcal{L}$ whose intersection with $\mathcal{S}$ is nonempty. Therefore $\mathcal{L} \cup \mathcal{S}$ is a line segment with endpoints on $\partial \mathcal{S}$.

Let $\bar{\partial} \mathcal{S} = \{(I_0, I) \in \mathcal{S}: I_0 = h(I)\}$ be the ceiling of $\mathcal{S}$, with $h(I) = 1$ if $I \leq 0$, otherwise $h(I) = 1-I$, as shown in Figure~\ref{fig:concentrated-communication-rules}. We claim any line $\mathcal{L}$ which intersects $\partial \mathcal{S}$ must intersect $\bar{\partial} \mathcal{S}$. If $\mathcal{L} \cup \bar{\partial} \mathcal{S} = \varnothing$, then $\mathcal{L} \cup \partial \mathcal{S}$ would lie entirely in the region where $I_0 < h(I)$. However, by the geometry of $\mathcal{S}$, any line traversing the boundary $\partial \mathcal{S}$ must eventually cross $h(I)$, thus $\mathcal{L} \cup \bar{\partial} \mathcal{S} \neq \varnothing$. Any feasible objective value has an equivalent solution on the ceiling, so communication rules can be defined by this line.
\hfill \BlackBox

\subsection{Proof of Corollary~\ref{corr:value-communication-rule-cases}} \label{app:value-communication-rule-cases}
If type $v_b$ reports bid $b$, the expected value of the nonnegative utility term given message $m$ is received can be written as follows:
%
\begin{align*}
    \mathbb{E}_{\mathcal{X}} \big[ u_b^{+} (\sigma (\theta_{m}^{b})&, x) \vert m \big] \\
    &= \sum_{x \in \mathcal{X}} p(x \vert m, s_b; \theta_{m}^{b}) u_b^{+} (\sigma(\theta_{m}^{b}), x) \\
    &= \theta_{m}^{b} \Ind{\theta_{m}^{b} \geq 1/2} + (1 - \theta_{m}^{b}) \Ind{\theta_{m}^{b} < 1/2}\\
    &= \left(\theta_m^b \vee (1- \theta_m^b) \right),
\end{align*}
%
and so by integrating over the message space, the expected nonnegative utility term is given by
%
\begin{align*}
    \mathbb{E}_{\mathcal{M}, \mathcal{X}} \big[ u_b^{+} (\sigma(&\theta_{m}^{b}), x)\big] \\
    &= \mathbb{E}_{\mathcal{M}} \left[ \mathbb{E}_{\mathcal{X}} \left[ u_b^{+} (\sigma(\theta_{m}^{b}), x) \vert m \right] \right] \\
    &= \sum_{m \in \mathcal{M}} \bigg( v_b P(m \vert X=0; b) \\
    &\quad \quad \quad \vee (1 - v_b) P(m \vert X=1; b) \bigg). 
\end{align*}
%
Following Proposition~\ref{prop:direct-communication-rules}, let $\mathcal{M} = \{m_{0}, m_1\}$, where $m_0$ and $m_1$ recommend actions $a_b = 0$ and $a_b = 1$. Let $I_0(b) = P(m_0 \vert X = 0; b)$ and $I_1(b) = P(m_1 \vert X = 1; b)$, then with inequalities (\ref{eq:recommends-action-0}) and (\ref{eq:recommends-action-1}), the above expression becomes
\begin{align*}
    \mathbb{E}_{\mathcal{M}, \mathcal{X}} \left[ u_b^{+} (\sigma(\theta_m^b), x)\right] 
    &= v_b I_0 (b) + (1-v_b) I_1 (b) \\
    &= I_1 (b) + v_b \left(  I_0 (b) - I_1 (b) \right) \\
    &= I_1(b) + v_b I(b),
\end{align*}
%
and following Proposition~\ref{prop:concentrated-communication-rules}, we get
\begin{align*}
    I_1(b) 
    &= I_0(b) - \left(I_0(b) - I_1(b)\right) \\
    &= I_0(b) - I (b) \\
    &= 1 - I(b) \Ind{I(b) \geq 0},
\end{align*}
%
and so by substituting this into the previous expression, the gain of a communication rule is given by
%
\begin{align*}
    &\delta(I(b), v_b) \\
    &= \mathbb{E}_{\mathcal{M}, \mathcal{X}} \left[ u_b^{+} (\sigma(\theta_m^b, x)\right] - \mathbb{E}_{\mathcal{X}} \left[ u_b^{+} (\sigma(v_b), x)\right] \\
    &= 1 - I(b) \left( \Ind{I(b) \geq 0} - v_b \right) - \underbracket{\left(v_b \vee (1 - v_b)\right)}_{\textrm{see (\ref{eq:value-no-information})}},
\end{align*}
for every $v_b, m \in \mathbb{R}_{[0, 1]}$.
\hfill \BlackBox

\section{Proof of Proposition~\ref{prop:necessary-and-sufficient-conditions}} \label{app:necessary-and-sufficient-conditions}
In mechanism design, for a social choice function that is defined over a finite set of alternatives, monotonicity is, in general, necessary but not sufficient for implementability \citep{rochet1987necessary}. Identifying domains where monotonicity is sufficient remains an active research area \citep{ashlagi2010monotonicity}. However, \citet{myerson1981optimal} proved sufficiency when a seller auctions a single item to buyers with private valuations and quasilinear utilities. We leverage similarities of this setup to ours, where $I$ is the item allocation. Our proof is similar to that of \citet{bergemann2018design} as the demand for information is independent of the seller's cost. Nevertheless, we provide a detailed proof to be self-contained.

\subsection{Necessity} \label{app:necessary-conditions}
To prove necessity, we start by assuming $I$ is implementable, in which case truthfulness implies that
%
\begin{align*}
    \delta &(I(v_b), v_b) - t(v_b) \\
    & \geq \delta(I(b), v_b) - t(b) \\
    &= \delta(I(b), b) - t(b) + \delta(I(b), v_b) - \delta(I(b), b),
\end{align*}
%
for every $b \in \mathcal{B}$. If we now define $\Delta (z) = \delta(I(z), z) - t (z)$ as the rent of type $z \in \mathcal{V}_{b}$ for a truthful report, it follows from (\ref{eq:gain-communication-rule-expanded}) that we can re-write this inequality as
\begin{align*}
     &\Delta (v_b) - \Delta (b)\\
     &= \delta(I(v_b), v_b) - t (v_b) - \delta(I(b), b) + t (b) \\
     &\geq \delta(I(b), v_b) - \delta(I(b), b) \\ 
     &= (v_b - b) I (b) - \left(v_{b} \vee (1-v_{b}) \right) + \left(b \vee (1-b) \right). 
\end{align*}
%
Without loss of generality we can assume that $v_b \geq b$, as we can simply swap terms otherwise. 
Then, for $v_b < 1/2$, this inequality can be re-written as
\begin{align*}
    I (v_b) + 1 \geq \frac{\Delta(v_b) - \Delta(b)}{v_b - b} \geq I (b) + 1 
\end{align*}
%
and so $I (v_b) \geq I (b)$ if $v_b \geq b$, hence monotonicity is a necessary condition, which can be shown to hold for $v_b > 1/2$ in a similar fashion. 

\subsection{Sufficiency} \label{app:sufficient-conditions}
Next, to prove sufficiency we need to consider the fact that $\Delta$ is differentiable with respect to $v_b$ on $[0, 1/2)$ and $(1/2, 1]$, so we examine these two intervals separately.
Within these intervals, the value is continuous in $v_b$, so by the envelope theorem \citep{milgrom2002envelope}, incentive compatibility imposes, for $v_b \leq 1/2$
%
\begin{align*}
    \Delta(1/2) &= \Delta(0) + \int_{0}^{1/2} \frac{d}{dv_b} \delta(I(v_b), v_b) d v_b \\
    &= \Delta(0) + \int_{0}^{1/2} \left(I(v_b) + 1 \right) d v_b,
\end{align*}
%
and similarly for $v_b \geq 1/2$
\begin{align*}
    \Delta(1/2) &= \Delta(1) - \int_{1/2}^{1} \frac{d}{dv_b}  \delta(I(v_b), v_b) d v_b \\
    &= \Delta(1) - \int_{1/2}^{1} \left(I(v_b) - 1\right) d v_b,
\end{align*}
%
therefore, as information has no value for types $v_b \in \{0, 1\}$, such that $\Delta(0) = \Delta(1) = 0$, the following must hold
\begin{align*}
    \left. v_b \right\rvert_{0}^{1/2} + \int_{0}^{1/2} I(v_b) d v_b &= \left. v_b \right\rvert_{1/2}^{1} - \int_{1/2}^{1} I(v_b)  d v_b \\
    \implies \int_{0}^{1} I(v_b)  d v_b &= 0,
\end{align*}
%
thus constraint (\ref{eq:integral-constraint}) is needed.
As $\Delta(v_b) = \delta(I(v_b), v_b) - t (v_b)$, we can construct the following transfers from the envelope representation if $v_b \leq 1/2$,
\begin{align*}
    t(v_b) &= \delta(I(v_b), v_b) - \int_{0}^{v_b} \left( I(z) + 1\right) d z \\
    %&= 1 - I(v_b) \left( \Ind{I(v_b) \geq 0} -v_b \right) - (1 - v_b) - \int_{0}^{v_b} \left( I(z) + 1\right) d z, \\
    &= I(v_b) \left( v_b - \Ind{I(v_b) \geq 0} \right) - \int_{0}^{v_b} I(z) d z,
\end{align*}
%
and similarly if $v_b \geq 1/2$,
\begin{align*}
    t(v_b) &= \delta(I(v_b), v_b) + \int_{v_b}^{1} \left( I(z) - 1\right)  d z \\
    &= I(v_b) \left( v_b - \Ind{I(v_b) \geq 0} \right) + \int_{v_b}^{1} I(z) d z \\
    &= I(v_b) \left( v_b - \Ind{I(v_b) \geq 0} \right) - \int_{0}^{v_b} I(z) d z, 
\end{align*}
%
where the last line is due to (\ref{eq:integral-constraint}). 
Now we have an expression the transfers for every $v_b \in \mathcal{V}_b$, so we write the rent of type $v_b$ from reporting $b$ as follows:
\begin{align*}
    &\delta(I(b), v_b) - t (b) \\
    &= 1 - I(b)\left( \Ind{I(b) \geq 0} - v_b \right) - \left(v_{b} \vee (1-v_{b}) \right) \\
    & \quad - I(b)\left( b - \Ind{I(b) \geq 0}\right) + \int_{0}^{b}  I(z) d z \\
    &= 1 - \left(v_{b} \vee (1-v_{b}) \right) + (v_b - b) I(b) + \int_{0}^{b}  I(z) d z.
\end{align*}
%
By inspection, if $b < v_b$ then the term $(v_b - b)$ is positive and the rent increases as $b \rightarrow v_b$ as $I$ is monotone. On the other hand, if $b > v_b$, the term $(v_b - b)$ is negative so we want to decrease $I$, which happens as $b \rightarrow v_b$. The rent is thus is maximized at $b = v_b$, hence the incentive constraints are satisfied.
Individual rationality is also satisfied given the resulting rent is nonnegative for all $v_b \in \mathcal{V}_b$, hence we have proved sufficiency.

\subsection{Proof of Corollary~\ref{corr:optimal-mechanism-continuous}} \label{app:optimal-mechanism-continuous}
Lastly, we show that the seller's objective can be reduced to that in (\ref{eq:integrand}). Stated in Section~\ref{sec:optimal-mechanism}, for a given $I$, the seller's cost is the expected externality when the buyer chooses the correct action, which for a given state $x$, is:
%
\begin{align*}
    \mathbb{E}_{\mathcal{X}} \big[ u_s^{-} (\sigma (\theta_{m}^{b}), &x; \tau) \vert m \big] \\
    &= \sum_{x \in \mathcal{X}} p(x \vert m, s_s; v_s) u_s^{-} (\sigma(\theta_{m}^{b}), x; \tau) \\
    %&= \underbracket{\tau v_s (1-\sigma(\theta_{r}^{m}))}_{X = 0} +  \underbracket{\tau (1-v_s) \sigma (\theta_{r}^{m})}_{X = 1},\\
    &= \tau v_s \Ind{\theta_{m}^{b} \geq 1/2} + \tau (1 - v_s) \Ind{\theta_{m}^{b} < 1/2}.
\end{align*}
%
Following Proposition~\ref{prop:direct-communication-rules}, we know that $\theta_m^b \geq 1/2$ for $m_0$ and $\theta_m^b < 1/2$ for $m_1$, so by integrating over the message space, the expected cost given a communication rule is
%
\begin{align*}
    c(I(b); \tau) &= \mathbb{E}_{\mathcal{M}, \mathcal{X}} \left[ u_s^{-} (\sigma(\theta_{m}^{b}), x; \tau)\right] \\
    &= \mathbb{E}_{\mathcal{M}} \left[ \mathbb{E}_{\mathcal{X}} \left[ u_s^{-} (\sigma(\theta_{m}^{b}), x; \tau) \vert m \right] \right] \\
    &= \tau v_s P(m_0; v_s) + \tau (1 - v_s) P(m_1; v_s)
\end{align*}
%
and given we know that
%
\begin{align*}
    P(m_1; v_s) 
    &= v_s I_1 (b) + (1-v_s) I_1 (b) \\
    &= v_s (1 - I_0 (b)) + (1-v_s) I_1 (b)\\
    %&= v_s - v_s  I_0 (b) + I_1 (b) - v_s I_1 (b) \\
    &= v_s + I_1 (b) - v_s I(v_s) - 2v_s I_1 (b) \\
    &= v_s - v_s I(b) + (1 - 2v_s) I_1 (b) \\
    %&= v_s - v_s I(v_s) + (1 - 2v_s) (1 + \min \{-I(v_s), 0\}), \\
    &= 1 - v_s - v_s I(b) - (1 - 2v_s) \left(I(b) \vee 0 \right)
\end{align*}
%
the expected cost reduces to
%
\begin{align*}
    c (I (b); \tau) =  \ &\tau v_s + \tau (1-2v_s)(1-v_s) \\
    &\quad - \tau (1 - 2v_s) I (b) \left(v_s + \Ind{I (b) \geq 0} \right),
\end{align*}
%
such that considering direct mechanisms, the sellers minimizes $\mathbb{E}_{\mathcal{V}_b}[c (I (v_b); \tau) ]$. Now we turn our attention to the transfers, with the expected transfer given by
\begin{align*}
    \mathbb{E}_{\mathcal{V}_{b}} \left[ t(v_b) \right] &= \int_{\mathcal{V}_{b}}  t(v_b) d F (v_b) \\
    &= \int_{\mathcal{V}_{b}} \Bigg( I(v_b) \left(v_b - \Ind{I(v_b) \geq 0}\right) \\
    &\quad - \int_{0}^{v_b}  I(v_b) d v_b\Bigg) d F(v_b),% \\
    %&= \int_{\mathcal{V}_{b}} \Bigg( I(v_b) \left(v_b - \Ind{I(v_b) \geq 0}\right) \Bigg)d F(v_b) \\
    %&\quad - \int_{\mathcal{V}_{b}} \Bigg( \int_{0}^{v_b}  I(v_b) d v_b \Bigg)  d F(v_b), 
\end{align*}
%
hence if we let $\alpha = \int_{0}^{v_b}  I(v_b) d v_b$ and $d\beta = p(v_b) dv_b$, then the right-most expression reduces to
\begin{align*}
    &\int_{\mathcal{V}_{b}} \left( \int_{0}^{v_b}  I(v_b) d v_b \right) p(v_b) dv_b \\
    &= \int_{\mathcal{V}_{b}} \alpha d \beta \\
    &= \Big. \alpha \beta \Big\rvert_{0}^{1} - \int_{\mathcal{V}_{b}} \beta d\alpha \\
    &= \left. F(v_b) \int_{0}^{v_b} I(z) d {z} \right\rvert_{0}^{1} - \int_{\mathcal{V}_{b}} F(v_b) I(v_b) d v_b \\
    &= \int_{\mathcal{V}_{b}} I(v_b) d {v_b}  - \int_{\mathcal{V}_{b}} F(v_b) I(v_b) d v_b \\
    &= \int_{\mathcal{V}_{b}} I(v_b) (1 - F(v_b)) d {v_b}, 
\end{align*}
%
which if we substitute back into the original expression gives
%
\begin{subequations}
\begin{align*}
    &\mathbb{E}_{\mathcal{V}_{b}} \left[ t(v_b) \right]\\
    &= \int_{\mathcal{V}_{b}} \Bigg( I(v_b) \left(v_b - \Ind{I(v_b) \geq 0}\right) \Bigg)d F(v_b) \\
    &\quad - \int_{\mathcal{V}_{b}} I(v_b) (1 - F(v_b)) d {v_b} \\
    &=\int_{\mathcal{V}_{b}} \Bigg( I(v_b) \left(v_b - \Ind{I(v_b) \geq 0}\right) \Bigg) dF(v_b) \\
    &\quad- \int_{\mathcal{V}_{b}} I(v_b) \frac{1 - F(v_b)}{p(v_b)} dF(v_b) \\
    &= \int_{\mathcal{V}_{b}} \Bigg( I(v_b) \left(v_b - \Ind{I(v_b) \geq 0}\right)  -I(v_b) \frac{1 - F(v_b)}{p(v_b)} \Bigg) dF(v_b) \\
    &= \int_{\mathcal{V}_{b}} \Bigg( I(v_b) \left(v_b - \Ind{I(v_b) \geq 0}\right) + I(v_b) \frac{F(v_b)}{p(v_b)}\Bigg)  dv_b \\
    &\quad - \underbracket{\int_{\mathcal{V}_{b}} I(v_b) dv_b}_{=0 \, \mathrm{by} \, (\ref{eq:integral-constraint})} \\
    &= \int_{\mathcal{V}_{b}} \Bigg( I(v_b) \left(v_b - \Ind{I(v_b) \geq 0} + \frac{F(v_b)}{p(v_b)} \right) \Bigg)  dF(v_b). 
\end{align*}
\end{subequations}
%
Finally, the expected profit is equal to the expected transfer minus the expected cost, so the objective function in (\ref{eq:optimal-mechanism-continuous}) is given by
\begin{align*}
    \mathbb{E}_{\mathcal{V}_{b}} \left[ t(v_b) -  c (I (v_b); \tau) \right] = \int_{\mathcal{V}_b} J(I, v_b) dF(v_b),
\end{align*}
% 
where 
\begin{align*}
    J(I, v_b) = \, &I(v_b)  \big( v_b  + \frac{F(v_b)}{p(v_b)} + \tau v_s (1 - 2v_s) \\
    &+ \Ind{I(v_b) \geq 0} \left(\tau (1 - 2v_s)^2  - 1\right)\big). \tag*{\hfill \BlackBox}
\end{align*}

\section{Proof of Proposition~\ref{prop:optimal-menu}} \label{app:optimal-menu}
By inspection, the solution to the Lagrangian maximization in (\ref{eq:max-virtual-surplus}) is given by 
\begin{align*}
    I^\ast (v_b) = 
    \begin{cases}
        -1 & \text{if} \ \  \pi^-(v_b) < \lambda^\ast, \\
        z \in \mathbb{R}_{[-1, 0]} & \text{if} \ \  \pi^-(v_b) = \lambda^\ast, \\
        0 & \text{if} \ \ \pi^-(v_b) > \lambda^\ast > \pi^+(v_b), \\
        z \in \mathbb{R}_{[0, 1]} & \text{if} \ \  \pi^+(v_b) = \lambda^\ast, \\
        1 & \text{if} \ \ \pi^+(v_b) > \lambda^\ast,
    \end{cases}
\end{align*}
%
such that partial information is only offered when the virtual values coincide with the dual variable. With the regularity assumption, the virtual values are strictly increasing, so they have measure zero at these points. Thus, partial information is never offered and the optimal menu is a step function, $I^\ast (v_b) \in \{-1, 0, 1\}$.

